-- RN Integra | BACKUP EXCLUSIVAMENTE DA ESTRUTURA (sem registros)
-- Extraído do catálogo PostgreSQL do projeto Supabase "Agenda RN".
-- Data da captura: 2026-10-28 | Esquema: public | PostgreSQL 17
-- ATENÇÃO: Executar SOMENTE em um projeto Supabase novo/isolado, nunca no banco atual.
-- Não inclui pacientes, usuários, senhas, sessões, atendimentos, documentos,
-- itens de Storage, arquivos, secrets, configuração de Auth nem dados de tabelas.
-- O schema "auth" e as extensões gerenciadas pelo Supabase devem existir no destino.
-- Não use este arquivo como backup de dados de produção.

BEGIN;
SET LOCAL check_function_bodies = off;
CREATE SCHEMA IF NOT EXISTS public;
CREATE SCHEMA IF NOT EXISTS extensions;
-- Extensões observadas no projeto: pg_stat_statements (extensions 1.11), pgcrypto (extensions 1.3), plpgsql (pg_catalog 1.0), supabase_vault (vault 0.3.1), uuid-ossp (extensions 1.1).
-- As extensões Supabase do esquema vault/pg_catalog não são recriadas aqui.
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;

