-- [2] SEQUÊNCIAS NÃO VINCULADAS A IDENTITY
-- Todas as 7 sequências atuais são geradas automaticamente pelas colunas IDENTITY.

-- [3] FUNÇÕES E PROCEDIMENTOS
CREATE OR REPLACE FUNCTION public.apply_perseus_semantic_review(p_document_id uuid, p_table_id text, p_source_key text, p_semantic_field text, p_learn boolean, p_context jsonb, p_item_updates jsonb, p_expected_updated_at timestamp with time zone, p_updated_by bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_document public.insurance_documents%rowtype; v_entity uuid; v_payer text; v_kind text; v_fingerprint text; v_expected integer; v_count integer; v_previous uuid; v_review uuid; v_rule uuid; v_rule_action text; v_operation uuid:=gen_random_uuid();
begin
 if p_semantic_field is not null and p_semantic_field not in ('patient_name','beneficiary_number','guide_number','external_reference','service_date','procedure_code','procedure_description','amount_presented','amount_approved','amount_glossed','gloss_code','gloss_reason') then raise exception 'Significado inválido.' using errcode='22023'; end if;
 if jsonb_typeof(p_item_updates) is distinct from 'array' then raise exception 'Atualização de itens inválida.' using errcode='22023'; end if;
 select * into v_document from public.insurance_documents where id=p_document_id for update;
 if not found or v_document.upload_status<>'READY' then raise exception 'Documento não disponível.' using errcode='55000'; end if;
 select billing_entity_id,payer,kind into v_entity,v_payer,v_kind from public.insurance_movements where id=v_document.movement_id;
 if not found then raise exception 'Movimento do documento não encontrado.' using errcode='55000'; end if;
 if p_expected_updated_at is null or v_document.updated_at is distinct from p_expected_updated_at then raise exception 'O documento mudou. Atualize a prévia antes de revisar.' using errcode='40001'; end if;
 v_fingerprint:=coalesce(v_document.raw_metadata->'perseus'->>'layout_fingerprint','');
 if p_context->>'billing_entity_id' is distinct from v_entity::text or p_context->>'payer_normalized' is distinct from upper(regexp_replace(trim(v_payer),'\s+',' ','g')) or p_context->>'movement_kind' is distinct from v_kind or p_context->>'layout_fingerprint' is distinct from v_fingerprint then raise exception 'Contexto de aprendizado incompatível com o documento.' using errcode='22023'; end if;
 select count(*) into v_expected from public.insurance_document_items where document_id=p_document_id and source_metadata->>'table_id'=p_table_id and raw_data ? p_source_key;
 if v_expected=0 or jsonb_array_length(p_item_updates)<>v_expected then raise exception 'Os itens revisados não correspondem à coluna selecionada.' using errcode='22023'; end if;
 if exists(select 1 from public.perseus_semantic_value_corrections c join public.insurance_document_items i on i.id=c.item_id where c.document_id=p_document_id and c.state='ACTIVE' and i.source_metadata->>'table_id'=p_table_id) then raise exception 'Esta estrutura possui correções individuais. Revise-as antes de alterar o mapeamento.' using errcode='55000'; end if;
 update public.perseus_semantic_reviews set state='SUPERSEDED' where document_id=p_document_id and table_id=p_table_id and source_key=p_source_key and state in ('CONFIRMED','REJECTED') returning id into v_previous;
 with input as (select * from jsonb_to_recordset(p_item_updates) as x(id uuid,normalized_data jsonb,semantic_evidence jsonb,patient_name text,beneficiary_number text,guide_number text,external_reference text,service_date date,procedure_code text,procedure_description text,amount_presented numeric,amount_approved numeric,amount_glossed numeric,gloss_code text,gloss_reason text)) update public.insurance_document_items i set normalized_data=x.normalized_data,match_evidence=x.semantic_evidence,patient_name=x.patient_name,beneficiary_number=x.beneficiary_number,guide_number=x.guide_number,external_reference=x.external_reference,service_date=x.service_date,procedure_code=x.procedure_code,procedure_description=x.procedure_description,amount_presented=x.amount_presented,amount_approved=x.amount_approved,amount_glossed=x.amount_glossed,gloss_code=x.gloss_code,gloss_reason=x.gloss_reason from input x where i.id=x.id and i.document_id=p_document_id and i.source_metadata->>'table_id'=p_table_id and i.raw_data ? p_source_key;
 get diagnostics v_count=row_count;
 if v_count<>v_expected then raise exception 'A revisão não alcançou todos os itens esperados.' using errcode='40001'; end if;
 insert into public.perseus_semantic_reviews(document_id,table_id,source_key,semantic_field,state,applied_item_count,supersedes_review_id,created_by) values(p_document_id,p_table_id,p_source_key,p_semantic_field,case when p_semantic_field is null then 'REJECTED' else 'CONFIRMED' end,v_count,v_previous,p_updated_by) returning id into v_review;
 if p_learn and p_semantic_field is not null then
  perform pg_advisory_xact_lock(hashtext(concat_ws('/',p_context->>'billing_entity_id',p_context->>'payer_normalized',p_context->>'movement_kind',p_context->>'layout_fingerprint',p_context->>'table_signature',p_context->>'column_normalized')));
  select id into v_rule from public.perseus_semantic_rules where state='ACTIVE' and domain='INSURANCE' and billing_entity_id=v_entity and payer_normalized=p_context->>'payer_normalized' and movement_kind=v_kind and layout_fingerprint=v_fingerprint and table_signature=p_context->>'table_signature' and column_normalized=p_context->>'column_normalized' for update;
  if found then
   if (select semantic_field from public.perseus_semantic_rules where id=v_rule) is distinct from p_semantic_field then raise exception 'Há uma regra aprendida conflitante; revogue-a antes de ensinar outra.' using errcode='23505'; end if;
   v_rule_action:='REUSED';
  else
   insert into public.perseus_semantic_rules(domain,billing_entity_id,payer_normalized,movement_kind,layout_fingerprint,table_signature,column_normalized,semantic_field,source_document_id,created_by) values('INSURANCE',v_entity,p_context->>'payer_normalized',v_kind,v_fingerprint,p_context->>'table_signature',p_context->>'column_normalized',p_semantic_field,p_document_id,p_updated_by) returning id into v_rule;
   v_rule_action:='CREATED';
  end if;
 end if;
 insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,semantic_version,related_review_id,event_metadata) values(p_document_id,case when p_semantic_field is null then 'MAPPING_REVIEW_REJECTED' else 'MAPPING_REVIEW_APPLIED' end,'USER',p_updated_by,v_operation,coalesce(v_document.raw_metadata->'perseus'->'semantic'->>'version','1.0.0'),v_review,jsonb_build_object('column',left(p_source_key,80),'field',coalesce(p_semantic_field,''),'items',v_count));
 if v_previous is not null then insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,related_review_id,event_metadata) values(p_document_id,'MAPPING_REVIEW_REPLACED','USER',p_updated_by,v_operation,v_review,jsonb_build_object('column',left(p_source_key,80),'field',coalesce(p_semantic_field,''))); end if;
 if v_rule is not null then insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,related_review_id,related_rule_id,event_metadata) values(p_document_id,case when v_rule_action='CREATED' then 'LEARNED_RULE_CREATED' else 'LEARNED_RULE_REUSED' end,'USER',p_updated_by,v_operation,v_review,v_rule,jsonb_build_object('column',left(p_source_key,80),'field',p_semantic_field)); end if;
 update public.insurance_documents set updated_at=now(),updated_by=p_updated_by where id=p_document_id;
 return jsonb_build_object('applied_item_count',v_count,'rule_id',v_rule,'rule_action',v_rule_action,'review_id',v_review);
end $function$;

CREATE OR REPLACE FUNCTION public.apply_perseus_semantic_value_correction(p_document_id uuid, p_item_id uuid, p_semantic_field text, p_normalized_value text, p_expected_updated_at timestamp with time zone, p_updated_by bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_document public.insurance_documents%rowtype; v_previous uuid; v_correction uuid; v_table text; v_operation uuid:=gen_random_uuid();
begin
 if p_semantic_field not in ('patient_name','beneficiary_number','guide_number','external_reference','service_date','procedure_code','procedure_description','amount_presented','amount_approved','amount_glossed','gloss_code','gloss_reason') then raise exception 'Significado inválido.' using errcode='22023'; end if;
 select * into v_document from public.insurance_documents where id=p_document_id for update;
 if not found or v_document.upload_status<>'READY' then raise exception 'Documento não disponível.' using errcode='55000'; end if;
 if p_expected_updated_at is null or v_document.updated_at is distinct from p_expected_updated_at then raise exception 'O documento mudou. Atualize a prévia antes de corrigir.' using errcode='40001'; end if;
 select source_metadata->>'table_id' into v_table from public.insurance_document_items where id=p_item_id and document_id=p_document_id;
 if not found then raise exception 'Item não pertence ao documento.' using errcode='22023'; end if;
 update public.perseus_semantic_value_corrections set state='SUPERSEDED' where item_id=p_item_id and semantic_field=p_semantic_field and state='ACTIVE' returning id into v_previous;
 insert into public.perseus_semantic_value_corrections(document_id,item_id,semantic_field,normalized_value,supersedes_correction_id,created_by) values(p_document_id,p_item_id,p_semantic_field,p_normalized_value,v_previous,p_updated_by) returning id into v_correction;
 update public.insurance_document_items set normalized_data=jsonb_set(normalized_data,array[p_semantic_field],to_jsonb(p_normalized_value),true),match_evidence=jsonb_set(match_evidence,array[p_semantic_field],jsonb_build_object('origin','USER_CONFIRMED','corrected',true),true),patient_name=case when p_semantic_field='patient_name' then p_normalized_value else patient_name end,beneficiary_number=case when p_semantic_field='beneficiary_number' then p_normalized_value else beneficiary_number end,guide_number=case when p_semantic_field='guide_number' then p_normalized_value else guide_number end,external_reference=case when p_semantic_field='external_reference' then p_normalized_value else external_reference end,service_date=case when p_semantic_field='service_date' then p_normalized_value::date else service_date end,procedure_code=case when p_semantic_field='procedure_code' then p_normalized_value else procedure_code end,procedure_description=case when p_semantic_field='procedure_description' then p_normalized_value else procedure_description end,amount_presented=case when p_semantic_field='amount_presented' then p_normalized_value::numeric else amount_presented end,amount_approved=case when p_semantic_field='amount_approved' then p_normalized_value::numeric else amount_approved end,amount_glossed=case when p_semantic_field='amount_glossed' then p_normalized_value::numeric else amount_glossed end,gloss_code=case when p_semantic_field='gloss_code' then p_normalized_value else gloss_code end,gloss_reason=case when p_semantic_field='gloss_reason' then p_normalized_value else gloss_reason end where id=p_item_id and document_id=p_document_id;
 insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,related_correction_id,event_metadata) values(p_document_id,'INDIVIDUAL_CORRECTION_APPLIED','USER',p_updated_by,v_operation,v_correction,jsonb_build_object('field',p_semantic_field));
 update public.insurance_documents set updated_at=now(),updated_by=p_updated_by where id=p_document_id;
end $function$;

CREATE OR REPLACE FUNCTION public.appointment_billing_method(a jsonb, legacy text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select coalesce(nullif(a->>'forma_cobranca',''),nullif(a->>'billing_method',''),nullif(a->>'billingMethod',''),legacy);
$function$;

CREATE OR REPLACE FUNCTION public.attribute_financial_attendance(p_id text, p_entity uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.attendances%rowtype;alternate text;
begin
 select * into t from public.attendances where id=p_id;
 if t.id is null then return null;end if;
 if t.appointment_id is not null and not exists(select 1 from public.billing_records where attendance_id=t.id)
 and not exists(select 1 from public.billing_doctor_entities where doctor_id=t.doctor_id and billing_entity_id=p_entity and active) then
  select a->>'anesthetistId' into alternate from public.app_state s cross join lateral jsonb_array_elements(coalesce(s.payload->'appointments','[]')) a where s.id=1 and a->>'id'=t.appointment_id;
  if alternate is not null and exists(select 1 from public.billing_doctor_entities where doctor_id=alternate and billing_entity_id=p_entity and active) then
   update public.attendances set doctor_id=alternate where id=t.id;
  end if;
 end if;
 return public.financial_attendance(p_id);
end;$function$;

CREATE OR REPLACE FUNCTION public.authorized_financial_attachment_actor(actor bigint, invoice uuid, record uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_role text;
begin
  select role into v_role from public.users where id=actor;
  if v_role='general_manager' then return true; end if;
  if v_role<>'secretary' then return false; end if;

  if record is not null then
    return exists(
      select 1
      from public.billing_records b
      join public.attendances a on a.id=b.attendance_id
      where b.id=record
        and exists(
          select 1
          from public.agenda_access g
          where g.user_id=actor
            and (
              g.professional_id=a.doctor_id
              or exists(
                select 1
                from public.app_state s
                cross join lateral jsonb_array_elements(coalesce(s.payload->'appointments','[]'::jsonb)) ap(value)
                where s.id=1
                  and ap.value->>'id'=a.appointment_id
                  and nullif(ap.value->>'anesthetistId','')=g.professional_id
              )
            )
        )
    );
  end if;

  return exists(select 1 from public.invoice_billing_records ib where ib.invoice_id=invoice)
    and not exists(
      select 1
      from public.invoice_billing_records ib
      join public.billing_records b on b.id=ib.billing_record_id
      join public.attendances a on a.id=b.attendance_id
      where ib.invoice_id=invoice
        and not exists(
          select 1
          from public.agenda_access g
          where g.user_id=actor
            and (
              g.professional_id=a.doctor_id
              or exists(
                select 1
                from public.app_state s
                cross join lateral jsonb_array_elements(coalesce(s.payload->'appointments','[]'::jsonb)) ap(value)
                where s.id=1
                  and ap.value->>'id'=a.appointment_id
                  and nullif(ap.value->>'anesthetistId','')=g.professional_id
              )
            )
        )
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.begin_financial_attachment(p_actor bigint, p_invoice uuid, p_record uuid, p_filename text, p_mime text, p_size bigint, p_replaces uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, storage_path text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 attachment_id uuid:=gen_random_uuid();
 current_attachment public.financial_attachments%rowtype;
begin
 if (p_invoice is null)=(p_record is null) then
  raise exception 'Informe exatamente um pagamento';
 end if;
 if not public.authorized_financial_attachment_actor(p_actor,p_invoice,p_record) then
  raise exception 'Acesso negado';
 end if;
 if p_invoice is not null and not exists(
  select 1 from public.invoices i
  where i.id=p_invoice and i.recipient_type='CONVENIO' and i.status='ACTIVE'
   and i.voided_at is null and i.paid_at is not null
 ) then
  raise exception 'NF paga não encontrada';
 end if;
 if p_record is not null and not exists(
  select 1 from public.billing_records b
  where b.id=p_record and b.payment_status='PAGO' and b.paid_at is not null
   and b.received_amount is not null
   and (b.billing_method='PARTICULAR' or b.settlement_mode='DIRECT')
 ) then
  raise exception 'Pagamento direto não encontrado';
 end if;
 if p_filename is null or p_filename<>trim(p_filename)
   or p_filename~'[\\/[:cntrl:]]' or length(p_filename)>200
   or p_mime not in ('application/pdf','image/jpeg','image/png')
   or p_size<=0 or p_size>10485760 then
  raise exception 'Comprovante inválido';
 end if;
 if p_replaces is not null then
  select fa.* into current_attachment
  from public.financial_attachments fa
  where fa.id=p_replaces
  for update;
  if current_attachment.id is null or not current_attachment.is_current
    or current_attachment.status<>'READY'
    or current_attachment.invoice_id is distinct from p_invoice
    or current_attachment.billing_record_id is distinct from p_record then
   raise exception 'Comprovante atual não encontrado';
  end if;
 end if;
 perform public.financial_operation(p_actor,'payment_proof',coalesce(p_invoice,p_record)::text);
 insert into public.financial_attachments(
  id,document_type,invoice_id,billing_record_id,storage_path,
  original_filename,mime_type,file_size,replaces_attachment_id
 ) values(
  attachment_id,'PAYMENT_PROOF',p_invoice,p_record,
  format('payment-proofs/%s/%s',coalesce(p_invoice,p_record),attachment_id),
  p_filename,p_mime,p_size,p_replaces
 );
 return query
  select attachment_id,format('payment-proofs/%s/%s',coalesce(p_invoice,p_record),attachment_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.billing_entity_receipts_analytics(p_entity uuid)
 RETURNS TABLE(payment_year integer, payment_month integer, source text, amount numeric, operations bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 with direct_payments as (
  select extract(year from b.paid_at)::integer payment_year,
         extract(month from b.paid_at)::integer payment_month,
         case when nullif(trim(b.invoice_number),'') is not null
           or exists (
            select 1 from public.invoice_billing_records item
            join public.invoices inv on inv.id=item.invoice_id
            where item.billing_record_id=b.id
             and item.is_active and inv.status='ACTIVE'
             and inv.voided_at is null and inv.recipient_type='PARTICULAR'
           )
           then 'Particular - Com NF' else 'Particular - Sem NF' end as source,
         b.received_amount::numeric amount
  from public.billing_records b
  where b.billing_entity_id=p_entity
   and b.settlement_mode='DIRECT'
   and b.billing_method='PARTICULAR'
   and b.payment_status='PAGO'
   and b.paid_at is not null
   and b.received_amount is not null
   and b.received_amount>=0
 ), insurance_payments as (
  select extract(year from i.paid_at)::integer payment_year,
         extract(month from i.paid_at)::integer payment_month,
         coalesce(nullif(upper(trim(i.payer)),''),'CONVÊNIO NÃO INFORMADO') as source,
         i.net_amount::numeric as amount
  from public.invoices i
  where i.billing_entity_id=p_entity
   and i.recipient_type='CONVENIO'
   and i.status='ACTIVE' and i.voided_at is null
   and i.paid_at is not null and i.net_amount is not null
   and i.net_amount>=0
 ), receipts as (
  select * from direct_payments
  union all
  select * from insurance_payments
 )
 select r.payment_year,r.payment_month,r.source,
        round(sum(r.amount),2) as amount,
        count(*)::bigint as operations
 from receipts r
 group by r.payment_year,r.payment_month,r.source
 order by r.payment_year,r.payment_month,r.source;
$function$;

CREATE OR REPLACE FUNCTION public.billing_payer_key(value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select upper(regexp_replace(trim(coalesce(value,'')),'[[:space:]]+',' ','g'));
$function$;

CREATE OR REPLACE FUNCTION public.cancel_manual_attendance(p_actor bigint, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.attendances%rowtype;
begin
 perform pg_advisory_xact_lock(194701,1);perform pg_advisory_xact_lock(194701,2);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Acesso restrito à gerência';end if;
 select * into a from public.attendances where id=p_data->>'id' for update;
 if a.id is null or a.origin not in ('FATURAMENTO_MANUAL','FISCAL_MANUAL') then raise exception 'Cancele atendimentos da Agenda na própria Agenda';end if;
 if a.status='cancelled' then return a.id;end if;
 if a.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Atendimento alterado. Atualize';end if;
 if nullif(trim(p_data->>'reason'),'') is null then raise exception 'Informe o motivo do cancelamento';end if;
 if exists(select 1 from public.invoice_billing_records x join public.billing_records b on b.id=x.billing_record_id where b.attendance_id=a.id and x.is_active) then raise exception 'Remova ou regularize a Nota Fiscal vinculada antes de cancelar este atendimento.';end if;
 perform public.financial_operation(p_actor,'cancel_attendance',a.id);
 update public.invoice_requests set status='CANCELLED' where attendance_id=a.id and status='PENDING';
 update public.billing_records set payment_status='PENDENTE',received_amount=null,paid_at=null where attendance_id=a.id;
 update public.attendances set status='cancelled',cancelled_at=clock_timestamp(),cancelled_by=p_actor,cancellation_reason=trim(p_data->>'reason') where id=a.id;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return a.id;
end;$function$;

CREATE OR REPLACE FUNCTION public.check_fiscal_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id where x.is_active is distinct from (i.status='ACTIVE' and i.voided_at is null)) then raise exception 'Vínculo operacional incompatível com status fiscal';end if;
 if exists(select 1 from public.invoices i where i.recipient_type='PARTICULAR' and ((select count(*) from public.invoice_billing_records x where x.invoice_id=i.id)<>1 or (i.status='ACTIVE' and i.voided_at is null and not exists(select 1 from public.invoice_requests r join public.invoice_billing_records x on x.billing_record_id=r.billing_record_id and x.invoice_id=i.id where r.invoice_id=i.id and r.status='ISSUED' and i.billing_entity_id=r.billing_entity_id and i.recipient_tax_id=r.taker_tax_id and i.recipient_name=r.taker_name and i.recipient_address is not distinct from r.taker_address and i.patient_id=r.patient_id and i.recipient_kind=r.taker_kind)))) then raise exception 'NF Particular exige exatamente um atendimento e sua solicitação emitida';end if;
 if exists(select 1 from public.invoice_requests r join public.billing_records b on b.id=r.billing_record_id where r.status in ('PENDING','ISSUED') and (b.attendance_id<>r.attendance_id or b.billing_method<>'PARTICULAR' or b.payment_status<>'PAGO' or b.received_amount is distinct from r.received_amount_snapshot or b.paid_at is distinct from r.paid_at_snapshot or b.billing_entity_id<>r.billing_entity_id)) then raise exception 'Pagamento e solicitação fiscal incompatíveis';end if;
 if exists(select 1 from public.invoice_requests r left join public.invoices i on i.id=r.invoice_id where r.status='ISSUED' and (i.id is null or i.status<>'ACTIVE' or i.voided_at is not null)) then raise exception 'Solicitação emitida exige NF ativa';end if;
 if exists(select 1 from public.invoice_requests r join public.invoice_billing_records x on x.billing_record_id=r.billing_record_id and x.is_active where r.status='PENDING') then raise exception 'Solicitação pendente já possui NF ativa';end if;
 if exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id join public.billing_records b on b.id=x.billing_record_id join public.attendances a on a.id=b.attendance_id where x.is_active and (i.recipient_type<>b.billing_method or a.status='cancelled')) then raise exception 'NF incompatível com atendimento';end if;
 if exists(select 1 from public.invoices i where i.recipient_type='CONVENIO' and i.status='ACTIVE' and i.voided_at is null and i.allocation_verified and (i.net_amount is null or not exists(select 1 from public.invoice_billing_records x where x.invoice_id=i.id) or exists(select 1 from public.invoice_billing_records x where x.invoice_id=i.id and x.received_amount is null) or i.net_amount is distinct from (select sum(x.received_amount) from public.invoice_billing_records x where x.invoice_id=i.id)+i.closing_adjustment)) then raise exception 'A soma dos itens e ajuste deve ser igual ao valor líquido';end if;
 if exists(select 1 from public.billing_records b where b.billing_method='PARTICULAR' and b.payment_status='PAGO' and b.payment_composition_verified and b.received_amount is distinct from (select sum(p.amount) from public.payment_parts p where p.billing_record_id=b.id)) then raise exception 'As formas de pagamento devem somar o valor recebido';end if;
 if exists(select 1 from public.invoices i where i.recipient_type='CONVENIO' and i.status='ACTIVE' and i.voided_at is null and i.paid_at is not null and i.payment_composition_verified and i.net_amount is distinct from (select sum(p.amount) from public.payment_parts p where p.invoice_id=i.id)) then raise exception 'As formas de pagamento devem somar o valor líquido';end if;
 if exists(select 1 from public.payment_parts p left join public.billing_records b on b.id=p.billing_record_id left join public.invoices i on i.id=p.invoice_id where (p.billing_record_id is not null and b.billing_method<>'PARTICULAR') or (p.invoice_id is not null and i.recipient_type<>'CONVENIO')) then raise exception 'Origem inválida da composição de pagamento';end if;
 if exists(select 1 from public.billing_records b where b.billing_method='CONVENIO' and b.settlement_mode='INVOICE' and (b.payment_status='PAGO') is distinct from exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id where x.billing_record_id=b.id and x.is_active and i.paid_at is not null)) then raise exception 'Quitação de convênio exige NF ativa paga';end if;
 if exists(select 1 from public.attendances a join public.invoice_requests r on r.attendance_id=a.id where a.status='cancelled' and r.status in ('PENDING','ISSUED') and a.origin<>'AGENDA') then raise exception 'Atendimento manual cancelado com solicitação ativa';end if;
 if exists(select 1 from public.invoices where (status='REPLACED') is distinct from (replaced_by_invoice_id is not null)) then raise exception 'Substituição exige documento sucessor';end if;
 if exists(with recursive chain as(select id,replaced_by_invoice_id,array[id] path,false cycle from public.invoices where replaced_by_invoice_id is not null union all select c.id,i.replaced_by_invoice_id,c.path||i.id,i.id=any(c.path) from chain c join public.invoices i on i.id=c.replaced_by_invoice_id where not c.cycle) select 1 from chain where cycle) then raise exception 'Ciclo de substituição fiscal';end if;
 return null;
end;$function$;

CREATE OR REPLACE FUNCTION public.close_billing_month(p_actor bigint, p_entity uuid, p_month text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 first_day date;
 snapshot_data jsonb;
 saved_id uuid;
 latest public.billing_monthly_closing_events%rowtype;
begin
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then
  raise exception 'Somente a gerência pode fechar uma competência';
 end if;
 if p_month is null or p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
  raise exception 'Competência inválida';
 end if;
 first_day:=(p_month||'-01')::date;
 if first_day>=date_trunc('month',timezone('America/Sao_Paulo',now()))::date then
  raise exception 'A competência atual ou futura não pode ser encerrada';
 end if;
 if length(coalesce(p_notes,''))>2000 then raise exception 'Observação muito longa';end if;

 perform pg_advisory_xact_lock(hashtext(p_entity::text||p_month)::bigint);
 select * into latest from public.billing_monthly_closing_events
  where billing_entity_id=p_entity and competence_month=first_day
  order by event_number desc limit 1;
 if latest.id is not null then
  if latest.event_type<>'UNLOCKED' then raise exception 'Competência bloqueada. Desbloqueie com a senha do Gerente Geral';end if;
 elsif exists(select 1 from public.billing_monthly_closings
   where billing_entity_id=p_entity and competence_month=first_day) then
  raise exception 'Competência bloqueada. Desbloqueie com a senha do Gerente Geral';
 end if;

 snapshot_data:=public.preview_billing_month(p_actor,p_entity,p_month);
 if coalesce((snapshot_data->'cash'->>'insurance_paid_invoices_without_net')::integer,0)>0
    or coalesce((snapshot_data->'issued_invoices'->>'without_net_amount')::integer,0)>0 then
   raise exception 'Existem NFs sem valor líquido identificado. Revise antes de fechar';
 end if;
 if latest.id is not null then
  insert into public.billing_monthly_closing_events(
    billing_entity_id,competence_month,event_type,snapshot,snapshot_checksum,notes,actor_id)
  values(p_entity,first_day,'CLOSED',snapshot_data,md5(snapshot_data::text),
    nullif(trim(p_notes),''),p_actor) returning id into saved_id;
 else
  insert into public.billing_monthly_closings(
    billing_entity_id,competence_month,snapshot,snapshot_checksum,notes,closed_by)
  values(p_entity,first_day,snapshot_data,md5(snapshot_data::text),
     nullif(trim(p_notes),''),p_actor) returning id into saved_id;
 end if;
 return saved_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.commit_agenda_change(p_expected timestamp with time zone, p_payload jsonb, p_revision timestamp with time zone, p_audit jsonb, p_request_id text DEFAULT NULL::text, p_decision text DEFAULT NULL::text, p_actor bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_notification jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare current_revision timestamptz; request_status text;
begin
  -- Serialize initialization as well as writes to the singleton.
  perform pg_advisory_xact_lock(194701,1);
  select updated_at into current_revision from public.app_state where id=1 for update;
  if current_revision is distinct from p_expected then return false; end if;
  if p_request_id is not null then
    select status into request_status from public.agenda_requests where id=p_request_id for update;
    if request_status is distinct from 'pending' then return false; end if;
    if p_decision not in ('accepted','denied') then raise exception 'Invalid decision'; end if;
    update public.agenda_requests set status=p_decision,decided_by=p_actor,decision_note=p_note,decided_at=p_revision where id=p_request_id;
  end if;
  perform public.financial_operation(coalesce(p_actor,(p_audit->0->>'actor_user_id')::bigint),'agenda',p_request_id);
  if p_payload is not null then
    -- UPDATE first: ON CONFLICT fires BEFORE INSERT row triggers even for
    -- an existing singleton, causing historical blocks to reject unrelated saves.
    -- Updates instead compare against OLD.payload, validating only new/changed
    -- appointment availability. Keep INSERT validation for first-time setup.
    update public.app_state
      set payload=p_payload, updated_at=p_revision
      where id=1;
    if not found then
      insert into public.app_state(id,payload,updated_at)
        values(1,p_payload,p_revision);
    end if;
  end if;
  insert into public.audit_logs(id,actor_user_id,actor_name,actor_role,action,professional_id,appointment_id,patient_id,description,metadata,created_at)
    select x.id,x.actor_user_id,x.actor_name,x.actor_role,x.action,x.professional_id,x.appointment_id,x.patient_id,x.description,x.metadata,coalesce(x.created_at,p_revision)
    from jsonb_to_recordset(p_audit) as x(id text,actor_user_id bigint,actor_name text,actor_role text,action text,professional_id text,appointment_id text,patient_id text,description text,metadata jsonb,created_at timestamptz);
  if p_notification is not null then
    insert into public.notifications(id,user_id,type,request_id,message,created_at)
    values(p_notification->>'id',(p_notification->>'user_id')::bigint,p_notification->>'type',p_request_id,p_notification->>'message',p_revision);
  end if;
  perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_financial_attachment(p_actor bigint, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare attachment public.financial_attachments%rowtype;
begin
 select * into attachment from public.financial_attachments where id=p_id for update;
 if attachment.id is null or attachment.status<>'PENDING' or attachment.created_by<>p_actor then raise exception 'Envio não disponível';end if;
 if not public.authorized_financial_attachment_actor(p_actor,attachment.invoice_id,attachment.billing_record_id) then raise exception 'Acesso negado';end if;
 if attachment.invoice_id is not null and not exists(select 1 from public.invoices where id=attachment.invoice_id and status='ACTIVE' and voided_at is null and paid_at is not null) then raise exception 'Pagamento não está mais ativo';end if;
 if attachment.billing_record_id is not null and not exists(select 1 from public.billing_records where id=attachment.billing_record_id and payment_status='PAGO' and paid_at is not null) then raise exception 'Pagamento não está mais ativo';end if;
 perform public.financial_operation(p_actor,'payment_proof',coalesce(attachment.invoice_id,attachment.billing_record_id)::text);
 if attachment.replaces_attachment_id is not null then update public.financial_attachments set is_current=false,deactivated_at=clock_timestamp(),deactivation_reason='REPLACED',replaced_by_attachment_id=attachment.id where id=attachment.replaces_attachment_id and is_current;end if;
 update public.financial_attachments set status='READY',is_current=true where id=attachment.id;
end;$function$;

CREATE OR REPLACE FUNCTION public.consume_security_limit(p_key text, p_limit integer, p_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer; t timestamptz := clock_timestamp();
begin
  if p_limit < 1 or p_limit > 10000 or p_seconds < 1 or p_seconds > 86400 then raise exception 'Invalid limit'; end if;
  delete from public.security_rate_limits where expires_at < t;
  insert into public.security_rate_limits(key,hits,expires_at) values(p_key,1,t + make_interval(secs=>p_seconds))
  on conflict(key) do update set hits=public.security_rate_limits.hits+1
  returning hits into n;
  return n <= p_limit;
end;
$function$;

CREATE OR REPLACE FUNCTION public.deactivate_reversed_payment_proofs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='billing_records' and old.payment_status='PAGO' and new.payment_status='PENDENTE' then
  update public.financial_attachments set is_current=false,deactivated_at=clock_timestamp(),deactivation_reason='PAYMENT_REVERSED' where billing_record_id=new.id and status='READY' and is_current;
 elsif tg_table_name='invoices' and old.paid_at is not null and new.paid_at is null then
  update public.financial_attachments set is_current=false,deactivated_at=clock_timestamp(),deactivation_reason='PAYMENT_REVERSED' where invoice_id=new.id and status='READY' and is_current;
 end if;
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.derive_doctor_specialty()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 if tg_op='INSERT' or new.specialty is distinct from old.specialty then
  if not public.valid_medical_specialty(new.specialty) then raise exception 'Selecione uma especialidade da lista';end if;
 end if;
 new.category:=case when public.is_anesthesiologist(new.specialty) then 'anesthetist' else 'doctor' end;return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.financial_attachment_log_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op uuid:=nullif(current_setting('rn.operation',true),'')::uuid; actor public.users%rowtype; before_value jsonb; after_value jsonb; action_name text;
begin
 if op is null then raise exception 'Alteração financeira exige log';end if;
 select * into actor from public.users where id=nullif(current_setting('rn.actor',true),'')::bigint;
 if actor.id is null then raise exception 'Autor inválido';end if;
 if tg_op='INSERT' and new.status='PENDING' then return new;end if;
 if tg_op='UPDATE' and old.status='PENDING' and new.status='REJECTED' then return new;end if;
 before_value:=case when tg_op='INSERT' or (tg_op='UPDATE' and old.status='PENDING' and new.status='READY') then null else public.financial_attachment_snapshot(to_jsonb(old)) end;
 after_value:=case when tg_op='DELETE' then null else public.financial_attachment_snapshot(to_jsonb(new)) end;
 if tg_op='UPDATE' and before_value is not null and before_value=after_value then return new;end if;
 action_name:=case when before_value is null then 'INSERT' when after_value is null then 'DELETE' else 'UPDATE' end;
 insert into public.financial_logs(id,actor_id,actor_name,actor_email,kind,record_id)
 values(op,actor.id,coalesce(nullif(actor.name,''),actor.email,'Não informado'),actor.email,current_setting('rn.kind',true),nullif(current_setting('rn.record',true),'')) on conflict(id) do nothing;
 insert into public.financial_log_changes(log_id,record_type,record_id,action,before_data,after_data)
 values(op,'financial_attachments',coalesce(new.id,old.id)::text,action_name,before_value,after_value);
 return coalesce(new,old);
end;$function$;

CREATE OR REPLACE FUNCTION public.financial_attachment_snapshot(value jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select case when value is null then null else jsonb_strip_nulls(jsonb_build_object(
  'document_type',value->'document_type','original_filename',value->'original_filename',
  'mime_type',value->'mime_type','file_size',value->'file_size','status',value->'status',
  'is_current',value->'is_current','deactivation_reason',value->'deactivation_reason',
  'invoice_id',value->'invoice_id','billing_record_id',value->'billing_record_id'
 )) end
$function$;

CREATE OR REPLACE FUNCTION public.financial_attendance(p_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select to_jsonb(t)||jsonb_build_object('doctorId',t.doctor_id,'patientId',t.patient_id,'forma_cobranca',t.billing_method) from public.attendances t where t.id=p_id
$function$;

CREATE OR REPLACE FUNCTION public.financial_log_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor public.users%rowtype;op uuid:=nullif(current_setting('rn.operation',true),'')::uuid;before_value jsonb;after_value jsonb;rid text;
begin
 if op is null then raise exception 'Alteração financeira exige log';end if;
 select * into actor from public.users where id=nullif(current_setting('rn.actor',true),'')::bigint;
 if actor.id is null then raise exception 'Autor inválido';end if;
 before_value:=case when tg_op<>'INSERT' then to_jsonb(old)-'details' end;after_value:=case when tg_op<>'DELETE' then to_jsonb(new)-'details' end;
 if tg_op='UPDATE' and (before_value-'updated_by'-'updated_at')=(after_value-'updated_by'-'updated_at') then return new;end if;
 rid:=coalesce(after_value->>'id',before_value->>'id');
 before_value:=public.financial_log_snapshot(before_value);after_value:=public.financial_log_snapshot(after_value);
 insert into public.financial_logs(id,actor_id,actor_name,actor_email,kind,record_id) values(op,actor.id,coalesce(nullif(actor.name,''),actor.email,'Não informado'),actor.email,current_setting('rn.kind'),nullif(current_setting('rn.record'),'')) on conflict(id) do nothing;
 insert into public.financial_log_changes(log_id,record_type,record_id,action,before_data,after_data) values(op,tg_table_name,rid,tg_op,before_value,after_value);
 return coalesce(new,old);
end;$function$;

CREATE OR REPLACE FUNCTION public.financial_log_snapshot(v jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select case when v is null then null else v||jsonb_build_object('_labels',jsonb_strip_nulls(jsonb_build_object(
 'doctor_id',(select name from public.doctors where id=v->>'doctor_id'),
 'billing_entity_id',(select name from public.billing_entities where id::text=v->>'billing_entity_id'),
 'paid_by_doctor_entity_link_id',(select d.name from public.billing_doctor_entities l join public.doctors d on d.id=l.doctor_id where l.id::text=v->>'paid_by_doctor_entity_link_id'),
 'paid_by_associate_id',(select name from public.company_associates where id::text=v->>'paid_by_associate_id'),
 'invoice_id',(select invoice_number from public.invoices where id::text=v->>'invoice_id'),
 'patient_id',(select p->>'name' from public.app_state s cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]')) p where s.id=1 and p->>'id'=v->>'patient_id' limit 1)
 ))) end
$function$;

CREATE OR REPLACE FUNCTION public.financial_operation(p_actor bigint, p_kind text, p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from public.users where id=p_actor and role in ('general_manager','secretary','doctor')) then raise exception 'Acesso negado';end if;
 perform set_config('rn.actor',p_actor::text,true);perform set_config('rn.operation',gen_random_uuid()::text,true);
 perform set_config('rn.kind',p_kind,true);perform set_config('rn.record',coalesce(p_id,''),true);
end;$function$;

CREATE OR REPLACE FUNCTION public.financial_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor bigint:=nullif(current_setting('rn.actor',true),'')::bigint;
begin
 if actor is null then raise exception 'Alteração financeira exige autoria';end if;
 if tg_op='INSERT' then new.created_by:=actor;new.created_at:=clock_timestamp();else new.created_by:=old.created_by;new.created_at:=old.created_at;end if;
 new.updated_by:=actor;new.updated_at:=clock_timestamp();return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.finish_private_payment(p_actor bigint, p_id uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.billing_records%rowtype;a public.attendances%rowtype;r public.invoice_requests%rowtype;f jsonb:=p_data->'fiscal';patient jsonb;cpf text;
begin
 select * into b from public.billing_records where id=p_id;
 if b.payment_status='PENDENTE' then
  update public.billing_records set no_invoice=false where id=p_id and no_invoice; update public.invoice_requests set status='CANCELLED' where billing_record_id=p_id and status='PENDING';return;end if;
 if b.billing_method<>'PARTICULAR' then
   update public.billing_records set no_invoice=false where id=p_id and no_invoice;
   return;
 end if;
 if coalesce((p_data->>'no_invoice')::boolean,false) then
  if exists(select 1 from public.invoice_requests
    where billing_record_id=p_id and status in ('PENDING','ISSUED')) then
    raise exception 'Solicitação de NF existente. Regularize antes de selecionar Sem Nota Fiscal';
  end if;
  if nullif(trim(b.invoice_number),'') is not null then
    raise exception 'Existe NF registrada: Sem Nota Fiscal não é permitido';
  end if;
  update public.billing_records set no_invoice=true where id=p_id and not no_invoice;
  return;
 end if;
 update public.billing_records set no_invoice=false where id=p_id and no_invoice;
 if nullif(trim(b.invoice_number),'') is not null then raise exception 'NF particular legada: preserve o documento e solicite regularização fiscal à gerência';end if;
 if f is null or coalesce(f->>'taker_kind','') not in ('PATIENT','OTHER') or nullif(trim(f->>'taker_name'),'') is null or not public.valid_cpf(f->>'taker_tax_id') then raise exception 'Confirme o pagamento e solicite NF com nome e CPF válido do tomador';end if;
 cpf:=regexp_replace(f->>'taker_tax_id','[^0-9]','','g');select * into a from public.attendances where id=b.attendance_id;
 select p into patient from public.app_state s cross join lateral jsonb_array_elements(s.payload->'patients') p where s.id=1 and p->>'id'=a.patient_id;
 if patient is null or nullif(trim(patient->>'name'),'') is null then raise exception 'Paciente não encontrado para confirmação fiscal';end if;
 if f->>'taker_kind'='PATIENT' and nullif(patient->>'cpf','') is not null and regexp_replace(patient->>'cpf','[^0-9]','','g')<>cpf then raise exception 'CPF diferente do cadastro. Corrija o paciente ou selecione Outra pessoa';end if;
 if f->>'taker_kind'='PATIENT' then
  f:=jsonb_set(f,'{taker_name}',to_jsonb(patient->>'name'));
  update public.app_state set payload=jsonb_set(payload,'{patients}',(select jsonb_agg(case when p->>'id'=a.patient_id then p||jsonb_build_object('cpf',cpf)||case when nullif(trim(f->>'taker_address'),'') is not null then jsonb_build_object('address',trim(f->>'taker_address')) else '{}'::jsonb end else p end order by n) from jsonb_array_elements(payload->'patients') with ordinality x(p,n))),updated_at=greatest(clock_timestamp(),updated_at+interval '1 millisecond') where id=1;
 end if;
 -- Uma solicitação pendente representa a próxima emissão, inclusive após desfazer a NF.
 -- Repetir a confirmação na Agenda não cria outro pedido nem altera snapshot fiscal.
 select * into r from public.invoice_requests
 where billing_record_id=p_id and status in ('PENDING','ISSUED') for update;
 if r.id is not null then
  if r.status='PENDING' and r.billing_entity_id=b.billing_entity_id
   and r.received_amount_snapshot is not distinct from b.received_amount
   and r.paid_at_snapshot is not distinct from b.paid_at
   and r.taker_kind=f->>'taker_kind'
   and r.taker_tax_id=cpf
   and r.taker_name=trim(f->>'taker_name')
   and r.taker_address is not distinct from nullif(trim(f->>'taker_address'),'')
   and r.notes is not distinct from nullif(trim(f->>'notes'),'')
  then return; end if;
  raise exception 'Já existe solicitação fiscal para este pagamento. Use Faturamento > Notas Fiscais > Solicitações. Para mudar valor, data ou tomador, reverta o pagamento de forma auditada.';
 end if;
 insert into public.invoice_requests(attendance_id,billing_record_id,billing_entity_id,taker_kind,taker_name,taker_tax_id,taker_address,notes,received_amount_snapshot,paid_at_snapshot,patient_id,patient_name_snapshot,doctor_id,doctor_name_snapshot,attendance_date_snapshot,procedure_snapshot,entity_name_snapshot,entity_tax_id_snapshot)
 select a.id,b.id,b.billing_entity_id,f->>'taker_kind',trim(f->>'taker_name'),cpf,nullif(trim(f->>'taker_address'),''),nullif(trim(f->>'notes'),''),b.received_amount,b.paid_at,a.patient_id,patient->>'name',a.doctor_id,d.name,a.date,a.procedure,e.name,e.tax_id from public.billing_entities e cross join public.doctors d where e.id=b.billing_entity_id and d.id=a.doctor_id;
end;$function$;

CREATE OR REPLACE FUNCTION public.get_billing_month_closing(p_actor bigint, p_entity uuid, p_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
 snap jsonb;
 original public.billing_monthly_closings%rowtype;
 latest public.billing_monthly_closing_events%rowtype;
 saved_snapshot jsonb;
 saved_id uuid;
 saved_at timestamptz;
 saved_by bigint;
 saved_notes text;
 saved_checksum text;
 is_closed boolean;
 revisions jsonb;
begin
 snap:=public.preview_billing_month(p_actor,p_entity,p_month);
 select * into original from public.billing_monthly_closings
  where billing_entity_id=p_entity and competence_month=(p_month||'-01')::date;
 select * into latest from public.billing_monthly_closing_events
  where billing_entity_id=p_entity and competence_month=(p_month||'-01')::date
  order by event_number desc limit 1;
 is_closed:=case when latest.id is not null then latest.event_type='CLOSED'
                  else original.id is not null end;
 if latest.id is not null and latest.event_type='CLOSED' then
   saved_snapshot:=latest.snapshot;saved_id:=latest.id;
   saved_at:=latest.created_at;saved_by:=latest.actor_id;
   saved_notes:=latest.notes;saved_checksum:=latest.snapshot_checksum;
 elsif original.id is not null then
   saved_snapshot:=original.snapshot;saved_id:=original.id;
   saved_at:=original.closed_at;saved_by:=original.closed_by;
   saved_notes:=original.notes;saved_checksum:=original.snapshot_checksum;
 end if;

 select coalesce(jsonb_agg(to_jsonb(h) order by h.version),'[]'::jsonb) into revisions from (
   select 0::bigint version,o.id,o.closed_at date,o.closed_by actor_id,o.notes,
    'CLOSED'::text event_type
   from public.billing_monthly_closings o
   where o.billing_entity_id=p_entity and o.competence_month=(p_month||'-01')::date
   union all
   select e.event_number,e.id,e.created_at,e.actor_id,e.notes,e.event_type
   from public.billing_monthly_closing_events e
   where e.billing_entity_id=p_entity and e.competence_month=(p_month||'-01')::date
 ) h;
 return jsonb_build_object(
  'current',snap,'closed',is_closed,
  'unlocked',latest.id is not null and latest.event_type='UNLOCKED',
  'history',revisions,
  'closing',case when saved_snapshot is null then null else jsonb_build_object(
    'id',saved_id,'snapshot',saved_snapshot,'closed_at',saved_at,
    'closed_by',saved_by,'notes',saved_notes,
    'changed_since_close',md5(snap::text)<>saved_checksum) end
 );
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_agenda_appointment_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  a jsonb; prior jsonb; b jsonb; r jsonb; p jsonb;
  old_payload jsonb; day_value date; occurrence integer; weekday integer;
  beginning integer; ending integer; block_start integer; block_end integer;
  work_start integer; work_end integer; r_start integer; r_end integer;
  pid text; doctor text; hospital_id text; procedure_name text; date_text text;
  allowed_times text[]; forbidden_time text; max_patients integer; used_count integer;
BEGIN
  PERFORM pg_advisory_xact_lock(194701,1);
  old_payload:=CASE WHEN TG_OP='UPDATE' THEN OLD.payload ELSE '{}'::jsonb END;
  FOR a IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'appointments','[]'::jsonb))
  LOOP
    IF a->>'status'='cancelled' THEN CONTINUE; END IF;
    SELECT value INTO prior FROM jsonb_array_elements(coalesce(old_payload->'appointments','[]'::jsonb))
      WHERE value->>'id'=a->>'id' LIMIT 1;
    IF prior IS NOT NULL AND
      (prior->>'date',prior->>'time',prior->>'duration',prior->>'doctorId',
       prior->>'anesthetistId',prior->>'hospitalId',prior->>'procedure')
      IS NOT DISTINCT FROM
      (a->>'date',a->>'time',a->>'duration',a->>'doctorId',
       a->>'anesthetistId',a->>'hospitalId',a->>'procedure') THEN
      CONTINUE;
    END IF;
    date_text:=a->>'date';
    IF date_text IS NULL OR a->>'time' IS NULL THEN CONTINUE; END IF;
    day_value:=date_text::date; weekday:=extract(dow from day_value)::int;
    occurrence:=((extract(day from day_value)::int-1)/7)+1;
    beginning:=split_part(a->>'time',':',1)::int*60+split_part(a->>'time',':',2)::int;
    ending:=beginning+coalesce((a->>'duration')::int,0);
    IF ending<=beginning THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: duração inválida.';
    END IF;
    doctor:=a->>'doctorId';hospital_id:=a->>'hospitalId';procedure_name:=coalesce(a->>'procedure','');

    -- Manual schedule blocks apply to both surgeon and anesthetist, including
    -- intervals crossed by the appointment rather than just the start time.
    FOR b IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'scheduleBlocks','[]'::jsonb))
      WHERE value->>'date'=date_text AND value->>'professionalId' IN (doctor,coalesce(a->>'anesthetistId',''))
    LOOP
      block_start:=split_part(b->>'start',':',1)::int*60+split_part(b->>'start',':',2)::int;
      block_end:=split_part(b->>'end',':',1)::int*60+split_part(b->>'end',':',2)::int;
      IF beginning<block_end AND ending>block_start THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: bloqueio do profissional.';
      END IF;
    END LOOP;
    IF doctor IS NULL OR doctor='' THEN CONTINUE; END IF;

    SELECT value INTO p FROM jsonb_array_elements(coalesce(NEW.payload->'professionals','[]'::jsonb))
      WHERE value->>'id'=doctor LIMIT 1;
    work_start:=coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workStart',NEW.payload->'settings'->>'workStart','07:00'),':',1),''),'07')::int*60
      +coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workStart',NEW.payload->'settings'->>'workStart','07:00'),':',2),''),'00')::int;
    work_end:=coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workEnd',NEW.payload->'settings'->>'workEnd','19:00'),':',1),''),'19')::int*60
      +coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workEnd',NEW.payload->'settings'->>'workEnd','19:00'),':',2),''),'00')::int;

    FOR r IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'schedulingRules','[]'::jsonb))
      WHERE value->>'professionalId'=doctor AND value->>'enabled' IS DISTINCT FROM 'false'
        AND (value->>'blockAllDay'='true' OR value->>'severity'='block')
    LOOP
      IF nullif(r->>'weekday','') IS NOT NULL AND (r->>'weekday')::int<>weekday THEN CONTINUE; END IF;
      IF nullif(r->>'occurrence','') IS NOT NULL THEN
        IF r->>'occurrence'='last' THEN
          IF extract(month from day_value+7)::int=extract(month from day_value)::int THEN CONTINUE; END IF;
        ELSIF (r->>'occurrence')::int<>occurrence THEN CONTINUE; END IF;
      END IF;
      IF r->>'blockAllDay'='true' THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: dia totalmente bloqueado.';
      END IF;
      -- A rule's start/end encode the allowed window. Its complement is
      -- blocked, as already drawn by the existing desktop calendar.
      IF nullif(r->>'start','') IS NOT NULL THEN
        r_start:=split_part(r->>'start',':',1)::int*60+split_part(r->>'start',':',2)::int;
        IF r_start>work_start AND beginning<least(r_start,work_end) AND ending>work_start THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: antes da janela permitida.';
        END IF;
      END IF;
      IF nullif(r->>'end','') IS NOT NULL THEN
        r_end:=split_part(r->>'end',':',1)::int*60+split_part(r->>'end',':',2)::int;
        IF r_end<work_end AND beginning<work_end AND ending>greatest(r_end,work_start) THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: após a janela permitida.';
        END IF;
      END IF;
      FOR forbidden_time IN SELECT btrim(value) FROM regexp_split_to_table(coalesce(r->>'forbiddenTimes',''),',') AS value
        WHERE btrim(value)<>'' LOOP
        block_start:=split_part(forbidden_time,':',1)::int*60+split_part(forbidden_time,':',2)::int;
        IF beginning<least(block_start+30,work_end) AND ending>block_start THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: horário proibido.';
        END IF;
      END LOOP;
      -- Advanced rule restrictions keep their existing scope (hospital /
      -- procedure), unlike absolute time bands and full-day closure.
      IF nullif(r->>'hospitalId','') IS NOT NULL AND r->>'hospitalId' IS DISTINCT FROM hospital_id THEN CONTINUE; END IF;
      IF nullif(r->>'procedureContains','') IS NOT NULL AND position(lower(r->>'procedureContains') in lower(procedure_name))=0 THEN CONTINUE; END IF;
      IF nullif(r->>'preferredTimes','') IS NOT NULL THEN
        SELECT array_agg(btrim(value)) INTO allowed_times FROM regexp_split_to_table(r->>'preferredTimes',',') AS value WHERE btrim(value)<>'';
        IF array_length(allowed_times,1)>0 AND NOT (a->>'time'=ANY(allowed_times)) THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: fora dos horários permitidos.';
        END IF;
      END IF;
      IF nullif(r->>'maxPatients','') IS NOT NULL THEN
        max_patients:=(r->>'maxPatients')::int;
        IF max_patients>0 THEN
          SELECT count(*) INTO used_count FROM jsonb_array_elements(coalesce(NEW.payload->'appointments','[]'::jsonb)) AS item
          WHERE item->>'id' IS DISTINCT FROM a->>'id' AND item->>'doctorId'=doctor
            AND item->>'date'=date_text AND item->>'status' IS DISTINCT FROM 'cancelled'
            AND (nullif(r->>'hospitalId','') IS NULL OR item->>'hospitalId'=r->>'hospitalId');
          IF used_count>=max_patients THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: limite diário atingido.';
          END IF;
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_billing_monthly_closing_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 raise exception 'Fechamento mensal é imutável. Correções precisam de processo de retificação auditável';
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_invoice_appointments()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  appointment jsonb;
  previous jsonb;
  entry record;
  method text;
  payer text;
begin
  for appointment in select value from jsonb_array_elements(coalesce(new.payload->'appointments','[]'::jsonb)) loop
    method:=public.appointment_billing_method(appointment);
    if method is not null and method not in ('PARTICULAR','CONVENIO') then
      raise exception 'Forma de cobrança inválida';
    end if;
  end loop;

  for entry in
    select b.appointment_id,b.professional_id,b.professional_role,b.attendance_id,
           i.payer,b.billing_method,b.billing_entity_id,
           (b.professional_role is distinct from 'PRIMARY' or
              exists(select 1 from public.billing_records other
                     where other.attendance_id=b.attendance_id and other.id<>b.id)) independent
    from public.billing_records b
    join public.invoice_billing_records ib on ib.billing_record_id=b.id
    join public.invoices i on i.id=ib.invoice_id
    where b.appointment_id is not null and i.recipient_type='CONVENIO' and ib.is_active
  loop
    select value into appointment from jsonb_array_elements(coalesce(new.payload->'appointments','[]'::jsonb))
      where value->>'id'=entry.appointment_id;
    select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]'::jsonb))
      where value->>'id'=entry.appointment_id;
    -- Estado antigo de outra NF não pode impedir alteração de agendamento não relacionado.
    if appointment is not null and appointment is not distinct from previous then continue; end if;
    if appointment is null or appointment->>'status' is distinct from 'realized'
       or appointment->>'doctorId' is distinct from previous->>'doctorId'
       or appointment->>'anesthetistId' is distinct from previous->>'anesthetistId'
       or appointment->>'patientId' is distinct from previous->>'patientId' then
      raise exception 'Atendimento com NF: preserve realização, médico, anestesista e paciente';
    end if;
    if entry.independent and entry.professional_id is not null then
      if entry.professional_id is distinct from appointment->>'doctorId'
         and entry.professional_id is distinct from appointment->>'anesthetistId' then
        raise exception 'Profissional faturado não participa mais do atendimento';
      end if;
    else
      payer:=coalesce(appointment->>'insurance','');
      if public.appointment_billing_method(appointment,entry.billing_method) is distinct from 'CONVENIO'
         or (public.billing_payer_key(payer)<>public.billing_payer_key(entry.payer)
             and (appointment->>'insurance' is distinct from previous->>'insurance'
                or nullif(trim(previous->>'insurance'),'') is not null)) then
        raise exception 'NF legada: preserve convênio e forma de cobrança';
      end if;
    end if;
  end loop;

  for entry in
    select b.appointment_id,b.attendance_id,b.professional_id,b.professional_role,r.patient_id,
      (b.professional_role is distinct from 'PRIMARY' or
       exists(select 1 from public.billing_records other
              where other.attendance_id=b.attendance_id and other.id<>b.id)) independent
    from public.invoice_requests r join public.billing_records b on b.id=r.billing_record_id
    where r.status in ('PENDING','ISSUED') and b.appointment_id is not null
  loop
    select value into appointment
    from jsonb_array_elements(coalesce(new.payload->'appointments','[]'::jsonb)||
                              coalesce(new.payload->'cancelledAppointments','[]'::jsonb))
    where value->>'id'=entry.appointment_id;
    select value into previous
    from jsonb_array_elements(coalesce(old.payload->'appointments','[]'::jsonb)||
                              coalesce(old.payload->'cancelledAppointments','[]'::jsonb))
    where value->>'id'=entry.appointment_id;
    -- Só revalidar o atendimento protegido quando ele tiver sido alterado.
    if appointment is not null and appointment is not distinct from previous then continue; end if;
    if appointment is null or appointment->>'patientId' is distinct from entry.patient_id then
      raise exception 'Atendimento com solicitação fiscal: preserve o paciente';
    end if;
    if entry.independent and entry.professional_id is not null then
      if entry.professional_id is distinct from appointment->>'doctorId'
         and entry.professional_id is distinct from appointment->>'anesthetistId' then
        raise exception 'Profissional da solicitação fiscal não participa do atendimento';
      end if;
    elsif appointment->>'forma_cobranca' is distinct from 'PARTICULAR' then
      raise exception 'Solicitação fiscal legada: preserve a forma particular';
    end if;
  end loop;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_issued_invoice_agenda_cancellation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  -- All normal agenda and billing mutations already serialize on this key.
  PERFORM pg_advisory_xact_lock(194701,1);
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(OLD.payload->'appointments','[]'::jsonb)) previous
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(coalesce(NEW.payload->'appointments','[]'::jsonb)) current_appointment
      WHERE current_appointment->>'id'=previous->>'id'
        AND current_appointment->>'status' IS DISTINCT FROM 'cancelled'
    )
    AND EXISTS (
      SELECT 1
      FROM public.billing_records b
      JOIN public.attendances a ON a.id=b.attendance_id
      JOIN public.invoice_billing_records item ON item.billing_record_id=b.id
      JOIN public.invoices invoice ON invoice.id=item.invoice_id
      WHERE (b.appointment_id=previous->>'id' OR a.appointment_id=previous->>'id')
        AND item.is_active
        AND invoice.status='ACTIVE'
        AND invoice.voided_at IS NULL
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='Não é possível cancelar ou excluir este atendimento, pois existe uma Nota Fiscal emitida vinculada a ele.';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_issued_invoice_attendance_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND
     (NEW.status IS DISTINCT FROM 'cancelled' OR OLD.status='cancelled') THEN
    RETURN NEW;
  END IF;

  -- Prevent concurrent invoice creation through financial RPC from racing
  -- against an attendance cancellation.
  PERFORM pg_advisory_xact_lock(194701,1);

  IF EXISTS (
    SELECT 1
    FROM public.billing_records b
    JOIN public.invoice_billing_records item ON item.billing_record_id=b.id
    JOIN public.invoices invoice ON invoice.id=item.invoice_id
    WHERE b.attendance_id=OLD.id
      AND item.is_active
      AND invoice.status='ACTIVE'
      AND invoice.voided_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='Não é possível cancelar ou excluir este atendimento, pois existe uma Nota Fiscal emitida vinculada a ele.';
  END IF;

  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.immutable_financial_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin raise exception 'Logs de faturamento são imutáveis';end;$function$;

CREATE OR REPLACE FUNCTION public.is_anesthesiologist(p_specialty text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select lower(trim(coalesce(p_specialty,'')))='anestesiologia' $function$;

CREATE OR REPLACE FUNCTION public.log_monthly_financial_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  operator public.users%rowtype;
  entity_name text;
  operation_id uuid:=gen_random_uuid();
  operation_kind text;
  operation_at timestamptz;
  month date;
  entity uuid;
  actor bigint;
  reason text;
  payload jsonb;
begin
  if tg_table_name='billing_monthly_closings' then
    actor:=new.closed_by;
    month:=new.competence_month;
    entity:=new.billing_entity_id;
    reason:=new.notes;
    operation_at:=new.closed_at;
    operation_kind:='monthly_closing';
  else
    actor:=new.actor_id;
    month:=new.competence_month;
    entity:=new.billing_entity_id;
    reason:=new.notes;
    operation_at:=new.created_at;
    operation_kind:=case when new.event_type='UNLOCKED' then 'monthly_unlock'
      else 'monthly_closing' end;
  end if;
  select * into operator from public.users where id=actor;
  if operator.id is null then raise exception 'Responsável pelo fechamento inválido';end if;
  select coalesce(nullif(e.trade_name,''),e.name) into entity_name
  from public.billing_entities e where e.id=entity;
  payload:=jsonb_build_object(
    'event_type',case when operation_kind='monthly_unlock' then 'UNLOCKED' else 'CLOSED' end,
    'billing_entity_id',entity,'entity_name',coalesce(entity_name,'Entidade histórica'),
    'competence_month',month,'notes',reason,
    'event_id',new.id
  );
  insert into public.financial_logs(id,actor_id,actor_name,actor_email,kind,record_id,created_at)
  values(operation_id,operator.id,coalesce(nullif(operator.name,''),operator.email),
   operator.email,operation_kind,entity::text||':'||month::text,operation_at);
  insert into public.financial_log_changes(
    log_id,record_type,record_id,action,before_data,after_data)
  values(operation_id,'billing_monthly_closing',entity::text||':'||month::text,
    'INSERT',null,payload);
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prepare_private_payment(p_old jsonb, p_data jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.invoice_requests%rowtype;
begin
 if nullif(trim(p_data->>'invoice_number'),'') is distinct from nullif(trim(p_old->>'invoice_number'),'') then raise exception 'Registre o número de NF no Faturamento, em Notas Fiscais';end if;
 if nullif(trim(p_old->>'invoice_number'),'') is not null then
  if (p_old->>'payment_status') is distinct from p_data->>'payment_status' or (p_old->>'received_amount')::numeric is distinct from (p_data->>'received_amount')::numeric or (p_old->>'paid_at')::date is distinct from (p_data->>'paid_at')::date or p_old->>'billing_entity_id' is distinct from p_data->>'billing_entity_id' then raise exception 'NF legada emitida. Solicite correção fiscal/manual ao Faturamento';end if;return true;
 end if;
 select * into r from public.invoice_requests where billing_record_id=(p_old->>'id')::uuid and status in ('PENDING','ISSUED');
 if r.id is null then return false;end if;
 if p_data ? 'fiscal' and p_data->'fiscal'<>'null'::jsonb and (p_data->'fiscal'->>'taker_kind' is distinct from r.taker_kind or trim(p_data->'fiscal'->>'taker_name') is distinct from r.taker_name or regexp_replace(p_data->'fiscal'->>'taker_tax_id','[^0-9]','','g') is distinct from r.taker_tax_id or nullif(trim(p_data->'fiscal'->>'taker_address'),'') is distinct from r.taker_address or nullif(trim(p_data->'fiscal'->>'notes'),'') is distinct from r.notes) then raise exception 'Snapshot fiscal já confirmado. Reverta o pagamento antes da emissão para corrigir';end if;
 if p_data->>'billing_method'='PARTICULAR' and p_data->>'payment_status'='PAGO' and (p_data->>'received_amount')::numeric=r.received_amount_snapshot and (p_data->>'paid_at')::date=r.paid_at_snapshot and p_data->>'billing_entity_id'=r.billing_entity_id::text and nullif(trim(p_data->>'notes'),'') is not distinct from nullif(trim(p_old->>'notes'),'') then return true;end if;
 if r.status='ISSUED' then raise exception 'NF já emitida. Solicite correção fiscal/manual ao Faturamento antes de alterar o pagamento';end if;
 if p_data->>'payment_status' is distinct from 'PENDENTE' or p_data->>'billing_method' is distinct from 'PARTICULAR' then raise exception 'Solicitação fiscal existente. Reverta para Pendente antes de corrigir e confirmar os dados';end if;return false;
end;$function$;

CREATE OR REPLACE FUNCTION public.preview_billing_month(p_actor bigint, p_entity uuid, p_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
 first_day date;
 last_day date;
 entity_row public.billing_entities%rowtype;
 production jsonb;
 professionals jsonb;
 invoice_summary jsonb;
 invoice_rows jsonb;
 cash_summary jsonb;
 direct_rows jsonb;
 paid_unrealized jsonb;
 expense_summary jsonb;
 expense_rows jsonb;
 denial_summary jsonb;
 denial_rows jsonb;
 pending_summary jsonb;
 professional_attendances jsonb;
 attendance_overview jsonb;
 cancelled_archive jsonb;
 professional_invoice_rows jsonb;
begin
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then
  raise exception 'Somente a gerência consulta o fechamento mensal';
 end if;
 if p_month is null or p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
  raise exception 'Competência deve estar no formato AAAA-MM';
 end if;
 first_day:=make_date(substring(p_month,1,4)::integer,substring(p_month,6,2)::integer,1);
 last_day:=(first_day + interval '1 month')::date;
 select * into entity_row from public.billing_entities where id=p_entity;
 if not found then raise exception 'Entidade recebedora não encontrada';end if;

 -- A produção clínica usa a DATA DO ATENDIMENTO, não a data do depósito.
 select jsonb_build_object(
   'attendances',count(distinct a.id),
   'charges',count(b.id),
   'professionals',count(distinct coalesce(b.professional_id,a.doctor_id)),
   'private_charges',count(b.id) filter(where b.billing_method='PARTICULAR'),
   'insurance_charges',count(b.id) filter(where b.billing_method='CONVENIO'),
   'pending_charges_now',count(b.id) filter(where b.payment_status<>'PAGO'),
   'unpriced_charges',count(b.id) filter(where b.received_amount is null and
       not exists(select 1 from public.invoice_billing_records ib
          where ib.billing_record_id=b.id and ib.is_active and ib.received_amount is not null))
 ) into production
 from public.billing_records b
 join public.attendances a on a.id=b.attendance_id
 where b.billing_entity_id=p_entity and a.status='realized'
 and a.date>=first_day and a.date<last_day;

 -- Detalhe informativo por profissional; NÃO é um rateio do caixa.
 select coalesce(jsonb_agg(to_jsonb(t) order by t.professional_name,t.professional_id),'[]'::jsonb)
 into professionals
 from (
  select coalesce(b.professional_id,a.doctor_id) professional_id,
   coalesce(d.name,'Profissional histórico') professional_name,
   count(*) charges,
   count(distinct a.id) attendances,
   count(*) filter(where b.billing_method='PARTICULAR') private_charges,
   count(*) filter(where b.billing_method='CONVENIO') insurance_charges,
   count(*) filter(where b.payment_status<>'PAGO') pending_charges_now,
   coalesce(sum(ibvals.attributed_amount),0) attributed_invoice_items
  from public.billing_records b
  join public.attendances a on a.id=b.attendance_id
  left join public.doctors d on d.id=coalesce(b.professional_id,a.doctor_id)
  left join lateral(
    select sum(ib.received_amount) attributed_amount
    from public.invoice_billing_records ib
    join public.invoices i on i.id=ib.invoice_id
    where ib.billing_record_id=b.id and ib.is_active
      and i.status='ACTIVE' and i.voided_at is null
      and i.recipient_type='CONVENIO'
  ) ibvals on true
  where b.billing_entity_id=p_entity and a.status='realized'
    and a.date>=first_day and a.date<last_day
  group by coalesce(b.professional_id,a.doctor_id),d.name
 ) t;


 -- Atendimentos por profissional para o relatório, agrupáveis por convênio.
 -- Cada cobrança mantém sua própria pessoa, pagador e procedimento.
 select coalesce(jsonb_agg(to_jsonb(t) order by t.professional_name,t.payer_name,t.service_date,t.patient_name,t.billing_record_id),'[]'::jsonb)
 into professional_attendances
 from (
  select b.id billing_record_id,
   coalesce(b.professional_id,a.doctor_id) professional_id,
   coalesce(d.name,'Profissional histórico') professional_name,
   a.id attendance_id, a.date service_date, a.procedure,
   coalesce(nullif(trim(b.effective_payer_name_snapshot),''),
     case when b.billing_method='PARTICULAR' then 'Particular'
       else nullif(trim(a.insurance),'') end,'Não informado') payer_name,
   b.billing_method,b.payment_status,b.no_invoice,b.received_amount,b.paid_at,
   coalesce(nullif(trim(b.patient_insurance_snapshot),''),
    nullif(trim(a.insurance),''),'Convênio não informado') as insurance_name,
   (select sum(ib.received_amount) from public.invoice_billing_records ib
    join public.invoices i on i.id=ib.invoice_id
    where ib.billing_record_id=b.id and ib.is_active
      and i.status='ACTIVE' and i.voided_at is null
   ) as invoice_item_received,
   coalesce(nullif(trim((
     select pat->>'name' from public.app_state s
      cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) pat
      where s.id=1 and pat->>'id'=a.patient_id limit 1
   )),'') ,'Paciente histórico') patient_name
  from public.billing_records b
   join public.attendances a on a.id=b.attendance_id
   left join public.doctors d on d.id=coalesce(b.professional_id,a.doctor_id)
  where b.billing_entity_id=p_entity and a.status='realized'
    and a.date>=first_day and a.date<last_day
 ) t;


 -- Uma linha por ATENDIMENTO, não por cobrança: inclui realizados e cancelados,
 -- inclusive cancelamentos sem cobrança. A competência é a data prevista do atendimento.
 -- A entidade é determinada por vínculo persistido, nunca por empresa atual do médico.
 select coalesce(jsonb_agg(to_jsonb(t) order by t.service_date,t.professional_name,t.patient_name,t.attendance_id),'[]'::jsonb)
 into attendance_overview
 from (
  select a.id attendance_id,a.date service_date,a.status,
   a.procedure,a.cancelled_at,a.cancellation_reason,
   coalesce(d.name,'Médico histórico') professional_name,
   coalesce(nullif(trim(a.billing_method),''),
     (select b.billing_method from public.billing_records b
      where b.attendance_id=a.id and b.billing_entity_id=p_entity
      order by b.created_at nulls last,b.id limit 1),'CONVENIO') billing_method,
   coalesce(nullif(trim(a.insurance),''),'Convênio não informado') insurance_name,
   coalesce(nullif(trim((
     select pat->>'name' from public.app_state s
      cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) pat
      where s.id=1 and pat->>'id'=a.patient_id limit 1
   )),''),'Paciente histórico') patient_name
  from public.attendances a
  left join public.doctors d on d.id=a.doctor_id
  where a.date>=first_day and a.date<last_day
   and a.status in ('realized','cancelled')
   and (a.billing_entity_id=p_entity or exists(
     select 1 from public.billing_records b
     where b.attendance_id=a.id and b.billing_entity_id=p_entity))
 ) t;
 -- Arquivo clínico da Agenda: cancelamentos podem não ter registro financeiro
 -- ou ter um registro com status agendado. O arquivo clínico prevalece.
 -- Sem criar cobranças; entidade do atendimento ou vínculo único do médico.
 select coalesce(jsonb_agg(to_jsonb(t) order by t.service_date,t.attendance_id),'[]'::jsonb)
 into cancelled_archive
 from (
  select coalesce((
    select a.id from public.attendances a
    where a.appointment_id=c.item->>'id'
      and (a.billing_entity_id=p_entity or exists (
       select 1 from public.billing_records b
       where b.attendance_id=a.id and b.billing_entity_id=p_entity))
    order by a.id limit 1
   ),'cancelled:'||(c.item->>'id')) attendance_id,
   ((c.item->>'date'))::date service_date,
   'cancelled'::text status,
   coalesce(c.item->>'procedure','—') procedure,
   (c.item->>'cancelledAt')::timestamptz cancelled_at,
   c.item->>'cancelReason' cancellation_reason,
   coalesce(d.name,'Médico histórico') professional_name,
   coalesce(nullif(trim(c.item->>'forma_cobranca'),''),
    (select b.billing_method from public.billing_records b
     join public.attendances a on a.id=b.attendance_id
     where a.appointment_id=c.item->>'id' and b.billing_entity_id=p_entity
     order by b.created_at nulls last,b.id limit 1),'CONVENIO') billing_method,
   coalesce(nullif(trim(c.item->>'insurance'),''),'Convênio não informado') insurance_name,
   coalesce(nullif(trim((
    select pat->>'name' from jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) pat
    where pat->>'id'=c.item->>'patientId' limit 1
   )),''),'Paciente histórico') patient_name
  from public.app_state s
  cross join lateral jsonb_array_elements(coalesce(s.payload->'cancelledAppointments','[]'::jsonb)) c(item)
  left join public.doctors d on d.id=c.item->>'doctorId'
  where s.id=1 and c.item->>'id' is not null
    and (c.item->>'date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    and (c.item->>'date')>=to_char(first_day,'YYYY-MM-DD')
    and (c.item->>'date')<to_char(last_day,'YYYY-MM-DD')
    and (
     exists (
      select 1 from public.attendances a where a.appointment_id=c.item->>'id'
       and (a.billing_entity_id=p_entity or exists (
        select 1 from public.billing_records b
        where b.attendance_id=a.id and b.billing_entity_id=p_entity))
     ) or (
      not exists(select 1 from public.attendances a where a.appointment_id=c.item->>'id')
      and p_entity=(
       select case when count(distinct l.billing_entity_id)=1
         then max(l.billing_entity_id::text)::uuid else null end
       from public.billing_doctor_entities l where l.doctor_id=c.item->>'doctorId'
      )
     )
    )
 ) t;
 -- Substituir status defasado do financeiro, sem duplicar o mesmo atendimento.
 select coalesce(jsonb_agg(entries.item),'[]'::jsonb) into attendance_overview
 from (
  select x.item from jsonb_array_elements(attendance_overview) x(item)
   where not exists (
    select 1 from jsonb_array_elements(cancelled_archive) archived(item)
    where archived.item->>'attendance_id'=x.item->>'attendance_id'
   )
  union all
  select archived.item from jsonb_array_elements(cancelled_archive) archived(item)
 ) entries;
 production:=production || jsonb_build_object(
  'cancelled_attendances',
  (select count(*) from jsonb_array_elements(attendance_overview) entry
   where entry->>'status'='cancelled')
 );

 -- Uma NF pode pertencer a vários profissionais. Lista-se o documento por
 -- vínculo histórico de item/solicitação, SEM ratear ou somar seus totais.
 -- Itens inativos continuam permitindo identificar NFs substituídas.
 select coalesce(jsonb_agg(to_jsonb(t) order by t.professional_name,t.invoice_number,t.invoice_id),'[]'::jsonb)
 into professional_invoice_rows from (
  select distinct on (linked.professional_id,linked.invoice_id)
    linked.professional_id,coalesce(d.name,'Profissional histórico') professional_name,
    linked.invoice_id, inv.invoice_number,
    (select coalesce(jsonb_agg(distinct coalesce(nullif(trim((
      select pat->>'name' from public.app_state s
      cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) pat
      where s.id=1 and pat->>'id'=act.patient_id limit 1
    )),''),'Paciente histórico')),'[]'::jsonb)
    from public.invoice_billing_records item
    join public.billing_records bill on bill.id=item.billing_record_id
    join public.attendances act on act.id=bill.attendance_id
    where item.invoice_id=linked.invoice_id and item.is_active
      and coalesce(bill.professional_id,act.doctor_id)=linked.professional_id
    ) patient_names,
    (select coalesce(jsonb_agg(distinct bill.id::text),'[]'::jsonb)
    from public.invoice_billing_records item
    join public.billing_records bill on bill.id=item.billing_record_id
    join public.attendances act on act.id=bill.attendance_id
    where item.invoice_id=linked.invoice_id and item.is_active
      and coalesce(bill.professional_id,act.doctor_id)=linked.professional_id
    ) billing_record_ids,
    (select sum(items.received_amount)
      from public.invoice_billing_records items
      join public.billing_records bill on bill.id=items.billing_record_id
      join public.attendances act on act.id=bill.attendance_id
      where items.invoice_id=linked.invoice_id and items.is_active
        and coalesce(bill.professional_id,act.doctor_id)=linked.professional_id
    ) as attributed_amount
  from (
   select coalesce(b.professional_id,a.doctor_id) professional_id,ib.invoice_id
   from public.invoice_billing_records ib
    join public.billing_records b on b.id=ib.billing_record_id
    join public.attendances a on a.id=b.attendance_id
   where b.billing_entity_id=p_entity
   union
   select coalesce(b.professional_id,r.doctor_id) professional_id,r.invoice_id
   from public.invoice_requests r
    left join public.billing_records b on b.id=r.billing_record_id
   where r.invoice_id is not null and r.billing_entity_id=p_entity
  ) linked
  join public.invoices inv on inv.id=linked.invoice_id and inv.billing_entity_id=p_entity
  left join public.doctors d on d.id=linked.professional_id
  where linked.professional_id is not null
    and (inv.issue_date>=first_day and inv.issue_date<last_day
      or inv.paid_at>=first_day and inv.paid_at<last_day
      or inv.cancelled_at::date>=first_day and inv.cancelled_at::date<last_day
      or inv.voided_at::date>=first_day and inv.voided_at::date<last_day)
  order by linked.professional_id,linked.invoice_id
 ) t;

 -- NF emitida na competência: um registro por NF, nunca por item.
 select jsonb_build_object(
   'count',count(*),
   'gross_total',coalesce(sum(i.total_amount),0),
   'net_total',coalesce(sum(i.net_amount),0),
   'without_net_amount',count(*) filter(where i.net_amount is null),
   'insurance_count',count(*) filter(where i.recipient_type='CONVENIO'),
   'private_count',count(*) filter(where i.recipient_type='PARTICULAR')
 ) into invoice_summary
 from public.invoices i
 where i.billing_entity_id=p_entity and i.status='ACTIVE' and i.voided_at is null
 and i.issue_date>=first_day and i.issue_date<last_day;

 select coalesce(jsonb_agg(to_jsonb(t) order by
   case when t.invoice_number ~ '^[0-9]+$' and length(t.invoice_number)<=18
     then t.invoice_number::bigint end nulls last,
   t.invoice_number,t.issue_date,t.id),'[]'::jsonb)
 into invoice_rows from(
   select i.id,i.invoice_number,i.payer,i.issue_date,i.paid_at,
          i.recipient_type,i.total_amount,i.net_amount,i.status,
          i.voided_at,i.cancelled_at,i.replaced_by_invoice_id,
          (select replacement.invoice_number
             from public.invoices replacement
             where replacement.id=i.replaced_by_invoice_id
               and replacement.billing_entity_id=i.billing_entity_id
          ) as replacement_invoice_number
   from public.invoices i
   where i.billing_entity_id=p_entity
     and (i.issue_date>=first_day and i.issue_date<last_day
          or i.paid_at>=first_day and i.paid_at<last_day
          or i.cancelled_at::date>=first_day and i.cancelled_at::date<last_day
          or i.voided_at::date>=first_day and i.voided_at::date<last_day)
 ) t;

 -- Fluxo de caixa: pagamentos diretos + NF CONVÊNIO recebida,
 -- sem contar a NF PARTICULAR outra vez (já foi pagamento direto).
 select jsonb_build_object(
  'direct_received',coalesce((select sum(b.received_amount)
    from public.billing_records b join public.attendances a on a.id=b.attendance_id
    where b.billing_entity_id=p_entity and a.status<>'cancelled'
      and b.settlement_mode='DIRECT' and b.payment_status='PAGO'
      and b.paid_at>=first_day and b.paid_at<last_day),0),
  'insurance_invoice_received',coalesce((select sum(i.net_amount)
    from public.invoices i where i.billing_entity_id=p_entity
      and i.status='ACTIVE' and i.voided_at is null and i.recipient_type='CONVENIO'
      and i.paid_at>=first_day and i.paid_at<last_day),0),
  'insurance_paid_invoices_without_net',(
    select count(*) from public.invoices i where i.billing_entity_id=p_entity
      and i.status='ACTIVE' and i.voided_at is null and i.recipient_type='CONVENIO'
      and i.paid_at>=first_day and i.paid_at<last_day and i.net_amount is null)
 ) into cash_summary;

 select coalesce(jsonb_agg(to_jsonb(t) order by t.paid_at,t.id),'[]'::jsonb)
 into direct_rows from (
   select b.id,b.attendance_id,coalesce(b.professional_id,a.doctor_id) professional_id,coalesce(d.name,'Profissional histórico') professional_name,
       b.paid_at,b.received_amount,b.billing_method,
       coalesce(nullif(trim((
        select pat->>'name' from public.app_state s
        cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) pat
        where s.id=1 and pat->>'id'=a.patient_id limit 1
       )),''),'Paciente histórico') patient_name
   from public.billing_records b
   join public.attendances a on a.id=b.attendance_id
   left join public.doctors d on d.id=coalesce(b.professional_id,a.doctor_id)
   where b.billing_entity_id=p_entity and a.status<>'cancelled'
     and b.settlement_mode='DIRECT' and b.payment_status='PAGO'
     and b.paid_at>=first_day and b.paid_at<last_day
 ) t;


 -- Pagamentos diretos de atendimentos AINDA NÃO marcados como realizados:
 -- pertencem ao caixa, mas não entram na produção. Controle separado e auditável.
 select coalesce(jsonb_agg(to_jsonb(t) order by t.service_date,t.paid_at,t.billing_record_id),'[]'::jsonb)
 into paid_unrealized
 from (
  select b.id billing_record_id,a.id attendance_id,a.date service_date,
   a.status clinical_status,a.procedure,
   coalesce(d.name,'Médico histórico') professional_name,
   coalesce(nullif(trim((
    select p->>'name' from public.app_state s
    cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) p
    where s.id=1 and p->>'id'=a.patient_id limit 1
   )),''),'Paciente histórico') patient_name,
   b.billing_method,b.received_amount,b.paid_at,
   coalesce(nullif(trim(a.insurance),''),'Convênio não informado') insurance_name
  from public.billing_records b
  join public.attendances a on a.id=b.attendance_id
  left join public.doctors d on d.id=coalesce(b.professional_id,a.doctor_id)
  where b.billing_entity_id=p_entity
   and a.status not in ('realized','cancelled')
   and b.settlement_mode='DIRECT' and b.payment_status='PAGO'
   and a.date>=first_day and a.date<last_day
 ) t;

 -- Despesas por COMPETÊNCIA e desembolso por DATA DE PAGAMENTO.
 select jsonb_build_object(
   'competence_total',coalesce((select sum(e.amount) from public.company_expenses e
      where e.billing_entity_id=p_entity and e.competence_date>=first_day
       and e.competence_date<last_day),0),
   'paid_total',coalesce((select sum(e.amount) from public.company_expenses e
      where e.billing_entity_id=p_entity and e.status='PAGO'
       and e.paid_at>=first_day and e.paid_at<last_day),0)
 ) into expense_summary;

 select coalesce(jsonb_agg(to_jsonb(t) order by t.competence_date,t.id),'[]'::jsonb)
 into expense_rows from (
   select e.id,e.description,e.category,e.competence_date,e.paid_at,
          e.amount,e.status,e.supplier
   from public.company_expenses e
   where e.billing_entity_id=p_entity and
     (e.competence_date>=first_day and e.competence_date<last_day
      or e.status='PAGO' and e.paid_at>=first_day and e.paid_at<last_day)
 ) t;

 -- Glosa independe do caixa; recuperação não vira segundo depósito.
 select jsonb_build_object(
   'denied_in_month',coalesce((select sum(c.denied_amount)
      from public.billing_denial_cases c
      where c.billing_entity_id=p_entity and c.denied_on>=first_day and c.denied_on<last_day),0),
   'recovered_in_month',coalesce((select sum(r.amount)
      from public.billing_denial_recoveries r
      join public.billing_denial_cases c on c.id=r.denial_id
      where c.billing_entity_id=p_entity and r.recovered_on>=first_day and r.recovered_on<last_day),0),
   'loss_on_cases_opened_in_month_now',coalesce((select sum(c.denied_amount-c.recovered_amount)
      from public.billing_denial_cases c
      where c.billing_entity_id=p_entity and c.status='CLOSED'
      and c.denied_on>=first_day and c.denied_on<last_day),0)
 ) into denial_summary;

 select coalesce(jsonb_agg(to_jsonb(t) order by t.denied_on,t.id),'[]'::jsonb)
 into denial_rows from (
   select c.id,c.billing_record_id,c.denial_kind,c.denied_on,c.denied_amount,
       c.recovered_amount,c.status,c.reason
   from public.billing_denial_cases c
   where c.billing_entity_id=p_entity and c.denied_on>=first_day and c.denied_on<last_day
 ) t;

 select jsonb_build_object(
   'unpaid_invoice_count',count(*),
   'unpaid_invoice_net',coalesce(sum(i.net_amount),0),
   'unpaid_invoice_unknown_net',count(*) filter(where i.net_amount is null)
 ) into pending_summary
 from public.invoices i
 where i.billing_entity_id=p_entity and i.status='ACTIVE' and i.voided_at is null
   and i.recipient_type='CONVENIO'
   and i.issue_date>=first_day and i.issue_date<last_day and i.paid_at is null;

 return jsonb_build_object(
   'entity',jsonb_build_object('id',entity_row.id,'name',entity_row.name,
      'trade_name',entity_row.trade_name,'tax_id',entity_row.tax_id,'person_type',entity_row.person_type),
   'competence',p_month,
   'period_start',first_day,'period_end_exclusive',last_day,
   'production',production,
   'professionals',professionals,
   'professional_attendances',professional_attendances,
   'attendance_overview',attendance_overview,
   'professional_invoice_rows',professional_invoice_rows,
   'issued_invoices',invoice_summary,'invoices',invoice_rows,
   'cash',cash_summary,'direct_payments',direct_rows,
    'paid_unrealized',paid_unrealized,
   'expenses',expense_summary,'expense_items',expense_rows,
   'denials',denial_summary,'denial_items',denial_rows,
   'pending_now',pending_summary,
   'notices',jsonb_build_array(
      'Produção é apurada por atendimento realizado na competência.',
      'Notas emitidas usam a data de emissão; recebimentos e despesas pagas usam data de pagamento.',
      'A NF de convênio é contabilizada uma única vez, independentemente da quantidade de profissionais ou pacientes.',
      'NF particular não é somada ao caixa novamente quando existe pagamento direto.',
      'Pendências e perdas de glosa no relatório refletem a situação atual no momento da consulta ou do fechamento.',
      'Recuperação de glosa é indicador operacional, não segunda entrada de caixa.',
      'Valores não identificados são destacados e não estimados.')
 );
end;
$function$;

CREATE OR REPLACE FUNCTION public.project_central_doctors()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare appointment jsonb; previous jsonb; professional text;
begin
 for appointment in select value from jsonb_array_elements(coalesce(new.payload->'appointments','[]')) loop
  previous:=null;
  if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]')) where value->>'id'=appointment->>'id'; end if;
  if previous is null or previous->>'doctorId' is distinct from appointment->>'doctorId' or previous->>'anesthetistId' is distinct from appointment->>'anesthetistId' then
   if nullif(appointment->>'anesthetistId','') is not null and not exists(select 1 from public.doctors where id=appointment->>'anesthetistId' and public.is_anesthesiologist(specialty)) then raise exception 'Selecione um médico com especialidade Anestesiologia';end if;
   foreach professional in array array[appointment->>'doctorId',appointment->>'anesthetistId'] loop
    if nullif(professional,'') is not null and not exists(select 1 from public.doctors where id=professional and active) then raise exception 'Médico inexistente ou inativo'; end if;
   end loop;
   if not exists(select 1 from public.doctor_agendas where doctor_id in(appointment->>'doctorId',appointment->>'anesthetistId') and active and exists(select 1 from public.doctors d where d.id=doctor_id and d.scheduling_enabled)) then raise exception 'Configure uma agenda ativa para o médico antes de agendar'; end if;
  end if;
 end loop;
 new.payload:=jsonb_set(new.payload,'{professionals}',coalesce((select jsonb_agg(d.details||jsonb_build_object('id',d.id,'name',d.name,'crm',d.crm,'specialty',d.specialty,'category',d.category,'active',d.active,'scheduling_enabled',d.scheduling_enabled,'billing_enabled',d.billing_enabled,'invoice_enabled',d.invoice_enabled,'agendaEnabled',coalesce(a.active,false) and d.scheduling_enabled,'agendaSettings',coalesce(a.settings,'{}'::jsonb)) order by d.name) from public.doctors d left join public.doctor_agendas a on a.doctor_id=d.id),'[]'));
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.protect_fiscal_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise exception 'Preserve o documento fiscal histórico';end if;
 if tg_op='UPDATE' then
  if (old.status<>'ACTIVE' or old.voided_at is not null) and current_setting('rn.kind',true)<>'replace_invoice' then raise exception 'Documento histórico imutável';end if;
  if (new.status is distinct from old.status or new.voided_at is distinct from old.voided_at or new.replaced_by_invoice_id is distinct from old.replaced_by_invoice_id) and current_setting('rn.kind',true) not in ('undo_invoice','cancel_invoice','replace_invoice') then raise exception 'Use a operação fiscal autorizada';end if;
  if (old.allocation_verified and not new.allocation_verified) or (old.payment_composition_verified and not new.payment_composition_verified and not (new.recipient_type='CONVENIO' and new.paid_at is null and coalesce(current_setting('rn.kind',true),'') in ('invoice','replace_invoice'))) then raise exception 'Não remova a validação financeira';end if;
 end if;
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.protect_invoice_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare kind text:=current_setting('rn.kind',true);
begin
 if tg_op='DELETE' then raise exception 'Preserve o histórico da solicitação fiscal';end if;
 if kind='edit_invoice_request' then
  if old.status<>'PENDING' or new.status<>'PENDING'
     or old.invoice_id is not null or new.invoice_id is not null then
    raise exception 'Somente solicitações pendentes e sem NF emitida podem ser corrigidas';
  end if;
  if (to_jsonb(new)-array['taker_kind','taker_name','taker_tax_id','taker_address','notes','updated_at','updated_by'])
     is distinct from (to_jsonb(old)-array['taker_kind','taker_name','taker_tax_id','taker_address','notes','updated_at','updated_by']) then
    raise exception 'A correção não pode alterar pagamento, paciente, médico ou vínculo fiscal';
  end if;
  return new;
 end if;
 if (to_jsonb(new)-array['status','invoice_id','updated_at','updated_by'])
     is distinct from (to_jsonb(old)-array['status','invoice_id','updated_at','updated_by']) then
  raise exception 'Snapshot fiscal imutável';
 end if;
 if old.status='PENDING' and new.status in ('PENDING','ISSUED','CANCELLED') then return new;end if;
 if old.status='ISSUED' and new.status='PENDING' and new.invoice_id is null
    and kind in ('undo_invoice','cancel_invoice','replace_invoice')
    and exists(select 1 from public.users where id=nullif(current_setting('rn.actor',true),'')::bigint
      and role='general_manager') then return new;end if;
 raise exception 'Transição fiscal não autorizada';
end;$function$;

CREATE OR REPLACE FUNCTION public.protect_legacy_expense_payer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 if tg_op='INSERT' and new.paid_by_associate_id is not null then raise exception 'Use o vínculo médico da empresa';end if;
 if tg_op='UPDATE' and new.paid_by_associate_id is distinct from old.paid_by_associate_id then raise exception 'Pagador legado é imutável';end if;
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.reject_financial_attachment(p_actor bigint, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform public.financial_operation(p_actor,'payment_proof',p_id::text);
 update public.financial_attachments set status='REJECTED' where id=p_id and created_by=p_actor and status='PENDING';
 if not found then raise exception 'Envio não disponível';end if;
end;$function$;

CREATE OR REPLACE FUNCTION public.remove_financial_attachment(p_actor bigint, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 attachment public.financial_attachments%rowtype;
begin
 select * into attachment
 from public.financial_attachments
 where id=p_id
 for update;

 if attachment.id is null or attachment.status<>'READY'
    or not attachment.is_current or attachment.deactivated_at is not null then
  raise exception 'O comprovante já não está ativo';
 end if;
 if not public.authorized_financial_attachment_actor(
    p_actor,attachment.invoice_id,attachment.billing_record_id) then
  raise exception 'Sem permissão para excluir este comprovante';
 end if;

 perform public.financial_operation(p_actor,'payment_proof',
  coalesce(attachment.invoice_id,attachment.billing_record_id)::text);

 update public.financial_attachments
 set is_current=false,
     deactivated_at=clock_timestamp(),
     deactivation_reason='REMOVED_BY_USER'
 where id=attachment.id and status='READY' and is_current;

 if not found then raise exception 'Não foi possível remover o comprovante';end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.replace_perseus_document_analysis(p_document_id uuid, p_items jsonb, p_parser_key text, p_parser_version text, p_perseus_metadata jsonb, p_updated_by bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_document public.insurance_documents%rowtype; v_tables integer; v_columns integer; v_records integer; v_semantic integer; v_conflicts integer; v_rule record; v_operation uuid:=gen_random_uuid();
begin
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>2000 then raise exception 'Itens do Perseu inválidos.' using errcode='22023'; end if;
 select * into v_document from public.insurance_documents where id=p_document_id for update;
 if not found then raise exception 'Documento não encontrado.' using errcode='P0002'; end if;
 if v_document.upload_status<>'READY' then raise exception 'Somente documentos prontos podem ser analisados.' using errcode='55000'; end if;
 if exists(select 1 from public.perseus_semantic_reviews where document_id=p_document_id and state in ('CONFIRMED','REJECTED')) or exists(select 1 from public.perseus_semantic_value_corrections where document_id=p_document_id and state='ACTIVE') then raise exception 'O documento possui revisão humana e não pode ser reanalisado automaticamente.' using errcode='55000'; end if;
 if exists(select 1 from public.insurance_document_items where document_id=p_document_id and (attendance_id is not null or billing_record_id is not null or coalesce(match_status,'UNMATCHED') not in ('UNMATCHED',''))) then raise exception 'O documento possui registros vinculados e não pode ser reanalisado automaticamente.' using errcode='55000'; end if;
 if exists(select 1 from jsonb_to_recordset(p_items) as item(source_index integer,raw_data jsonb,normalized_data jsonb) where item.source_index is null or item.source_index<0 or item.raw_data is null or item.normalized_data is not null and jsonb_typeof(item.normalized_data)<>'object') or exists(select 1 from jsonb_to_recordset(p_items) as item(source_index integer) group by item.source_index having count(*)>1) then raise exception 'Itens do Perseu inválidos.' using errcode='22023'; end if;
 delete from public.insurance_document_items where document_id=p_document_id;
 insert into public.insurance_document_items(document_id,source_index,raw_data,normalized_data,source_metadata,match_status,match_evidence,patient_name,beneficiary_number,guide_number,external_reference,service_date,procedure_code,procedure_description,amount_presented,amount_approved,amount_glossed,gloss_code,gloss_reason)
 select p_document_id,item.source_index,item.raw_data,coalesce(item.normalized_data,'{}'::jsonb),coalesce(item.source_metadata,'{}'::jsonb),'UNMATCHED',coalesce(item.semantic_evidence,'{}'::jsonb),item.patient_name,item.beneficiary_number,item.guide_number,item.external_reference,item.service_date,item.procedure_code,item.procedure_description,item.amount_presented,item.amount_approved,item.amount_glossed,item.gloss_code,item.gloss_reason
 from jsonb_to_recordset(p_items) as item(source_index integer,raw_data jsonb,normalized_data jsonb,semantic_evidence jsonb,source_metadata jsonb,patient_name text,beneficiary_number text,guide_number text,external_reference text,service_date date,procedure_code text,procedure_description text,amount_presented numeric,amount_approved numeric,amount_glossed numeric,gloss_code text,gloss_reason text) order by item.source_index;
 update public.insurance_documents set parser_key=p_parser_key,parser_version=p_parser_version,raw_metadata=coalesce(raw_metadata,'{}'::jsonb)||jsonb_build_object('perseus',coalesce(p_perseus_metadata,'{}'::jsonb)),perseus_status='REVIEW_REQUIRED',updated_at=now(),updated_by=p_updated_by where id=p_document_id;
 v_tables:=jsonb_array_length(coalesce(p_perseus_metadata->'structure'->'tables','[]'::jsonb)); v_columns:=coalesce((p_perseus_metadata->>'column_count')::integer,0); v_records:=coalesce((p_perseus_metadata->>'row_count')::integer,0);
 insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,parser_version,semantic_version,event_metadata) values
  (p_document_id,'ANALYSIS_COMPLETED','SYSTEM',p_updated_by,v_operation,p_parser_version,p_perseus_metadata->'semantic'->>'version',jsonb_build_object('tables',v_tables,'columns',v_columns,'records',v_records)),
  (p_document_id,'STRUCTURE_IDENTIFIED','SYSTEM',p_updated_by,v_operation,p_parser_version,p_perseus_metadata->'semantic'->>'version',jsonb_build_object('tables',v_tables,'columns',v_columns,'records',v_records));
 select count(*) into v_semantic from jsonb_array_elements(coalesce(p_perseus_metadata->'semantic'->'tables','[]'::jsonb)) table_item cross join lateral jsonb_array_elements(coalesce(table_item->'columns','[]'::jsonb)) column_item where column_item->>'field' is not null;
 if v_semantic>0 then insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,parser_version,semantic_version,event_metadata) values(p_document_id,'SEMANTIC_INTERPRETATION_COMPLETED','SEMANTIC_ENGINE',p_updated_by,v_operation,p_parser_version,p_perseus_metadata->'semantic'->>'version',jsonb_build_object('items',v_semantic)); end if;
 select count(*) into v_conflicts from jsonb_array_elements(coalesce(p_perseus_metadata->'semantic'->'tables','[]'::jsonb)) table_item cross join lateral jsonb_array_elements(coalesce(table_item->'columns','[]'::jsonb)) column_item where column_item->>'origin'='CONFLICT';
 if v_conflicts>0 then insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,semantic_version,event_metadata) values(p_document_id,'SEMANTIC_CONFLICT_IDENTIFIED','SEMANTIC_ENGINE',p_updated_by,v_operation,p_perseus_metadata->'semantic'->>'version',jsonb_build_object('items',v_conflicts)); end if;
 for v_rule in select distinct (column_item->>'ruleId')::uuid as rule_id,left(coalesce(column_item->>'sourceColumn',''),80) as source_column,left(coalesce(column_item->>'field',''),80) as semantic_field from jsonb_array_elements(coalesce(p_perseus_metadata->'semantic'->'tables','[]'::jsonb)) table_item cross join lateral jsonb_array_elements(coalesce(table_item->'columns','[]'::jsonb)) column_item where column_item->>'origin'='LEARNED_SUGGESTION' and column_item->>'ruleId' is not null loop
  insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,semantic_version,related_rule_id,event_metadata) values(p_document_id,'LEARNED_SUGGESTION_REUSED','LEARNED_KNOWLEDGE',p_updated_by,v_operation,p_perseus_metadata->'semantic'->>'version',v_rule.rule_id,jsonb_build_object('column',v_rule.source_column,'field',v_rule.semantic_field));
 end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.restore_billing_invoice(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 i public.invoices%rowtype;
 line record;
 pending_request public.invoice_requests%rowtype;
 request_total integer;
begin
 if (select role from public.users where id=p_actor) is distinct from 'general_manager'
 then raise exception 'Exige autorização do Gerente Geral'; end if;
 if nullif(trim(p_data->>'reason'),'') is null
 then raise exception 'Informe o motivo da restauração'; end if;
 if nullif(p_data->>'id','') is null
 then raise exception 'NF inválida'; end if;

 select * into i from public.invoices where id=(p_data->>'id')::uuid for update;
 if i.id is null then raise exception 'NF não encontrada'; end if;
 if i.status not in ('CANCELLED','REPLACED') or i.voided_at is not null
 then raise exception 'Somente NFs canceladas ou substituídas não desfeitas podem ser reativadas'; end if;
 if i.updated_at is distinct from (p_data->>'updated_at')::timestamptz
 then raise exception 'NF alterada por outro usuário. Atualize a página'; end if;
 if not exists(select 1 from public.invoice_billing_records where invoice_id=i.id)
 then raise exception 'NF sem atendimentos vinculados não pode ser reativada automaticamente'; end if;

 -- Reativação de uma NF substituída exige desativação prévia da substituta.
 if i.replaced_by_invoice_id is not null and exists (
   select 1 from public.invoices next_invoice
   where next_invoice.id=i.replaced_by_invoice_id
     and next_invoice.status='ACTIVE' and next_invoice.voided_at is null
 ) then
  raise exception 'A NF substituta ainda está ativa. Cancele ou regularize a substituta antes de reativar esta NF';
 end if;
 -- Concurrency: row locks serialize restores involving the same cobrança.
 for line in
  select ib.billing_record_id
  from public.invoice_billing_records ib
  where ib.invoice_id=i.id order by ib.billing_record_id for update
 loop
  perform 1 from public.billing_records b where b.id=line.billing_record_id for update;
  if exists (
   select 1 from public.invoice_billing_records other_ib
   join public.invoices other_invoice on other_invoice.id=other_ib.invoice_id
   where other_ib.billing_record_id=line.billing_record_id
    and other_ib.invoice_id<>i.id and other_ib.is_active
  ) then
   raise exception 'Atendimento já vinculado a outra NF ativa. Regularize a NF atual antes de restaurar a anterior';
  end if;
  if exists (
   select 1 from public.invoice_requests ir
   where ir.billing_record_id=line.billing_record_id and ir.status='ISSUED'
    and ir.invoice_id is distinct from i.id
  ) then
   raise exception 'Solicitação fiscal já vinculada a outra NF. Regularize-a antes de restaurar a anterior';
  end if;
 end loop;

 perform public.financial_operation(p_actor,'restore_invoice',i.id::text);
 update public.invoice_billing_records
 set is_active=true where invoice_id=i.id;
 if i.recipient_type='CONVENIO' then
  update public.billing_records b
  set payment_status=case when i.paid_at is not null then 'PAGO' else 'PENDENTE' end
  where b.id in (select ib.billing_record_id from public.invoice_billing_records ib where ib.invoice_id=i.id);
 else
  -- Uma única solicitação ativa por cobrança: não trocar solicitações de outra NF.
  for line in select distinct ib.billing_record_id from public.invoice_billing_records ib where ib.invoice_id=i.id loop
   select count(*) into request_total from public.invoice_requests req
    where req.billing_record_id=line.billing_record_id and req.status in ('PENDING','ISSUED');
   if request_total>1 then raise exception 'Há solicitações fiscais concorrentes para o mesmo pagamento'; end if;
   update public.invoice_requests
   set status='ISSUED',invoice_id=i.id
   where billing_record_id=line.billing_record_id and status='PENDING' and invoice_id is null;
  end loop;
 end if;
 update public.invoices
 set status='ACTIVE', cancelled_at=null,cancelled_by=null,cancellation_reason=null,
     replaced_by_invoice_id=null
 where id=i.id;
 perform set_config('rn.operation','',true);
 perform set_config('rn.actor','',true);
 return i.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_changed_credentials()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.password_hash is distinct from new.password_hash or old.password_salt is distinct from new.password_salt or old.role is distinct from new.role then
    delete from public.sessions where user_id=old.id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_perseus_semantic_rule(p_rule_id uuid, p_updated_by bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_rule public.perseus_semantic_rules%rowtype; v_operation uuid:=gen_random_uuid();
begin
 select * into v_rule from public.perseus_semantic_rules where id=p_rule_id for update;
 if not found then raise exception 'Regra aprendida não encontrada.' using errcode='P0002'; end if;
 if v_rule.state<>'ACTIVE' then raise exception 'A regra não está ativa.' using errcode='55000'; end if;
 update public.perseus_semantic_rules set state='REVOKED',revoked_at=now(),revoked_by=p_updated_by where id=p_rule_id;
 insert into public.perseus_document_events(document_id,event_type,event_origin,actor_id,operation_id,related_rule_id,event_metadata) values(v_rule.source_document_id,'LEARNED_RULE_REVOKED','USER',p_updated_by,v_operation,p_rule_id,jsonb_build_object('column',left(v_rule.column_normalized,80),'field',v_rule.semantic_field));
 return jsonb_build_object('rule_id',p_rule_id,'state','REVOKED');
end $function$;

CREATE OR REPLACE FUNCTION public.save_billing(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  attendance_key text;
begin
  if p_kind='record' then
    attendance_key:=coalesce(nullif(p_data->>'attendance_id',''),nullif(p_data->>'appointment_id',''));
    if attendance_key is not null and (
      select count(*) from public.billing_records where attendance_id=attendance_key
    )>1 then
      raise exception 'Atendimento possui cobranças independentes; selecione a cobrança profissional específica';
    end if;
  elsif (
    (p_kind='invoice' and coalesce(p_data->>'recipient_type','CONVENIO')='CONVENIO')
    or (p_kind='replace_invoice' and exists(
      select 1 from public.invoices where id=nullif(p_data->>'id','')::uuid and recipient_type='CONVENIO'))
  ) and exists (
    with selected_attendances as (
      select value::text as attendance_id
      from jsonb_array_elements_text(coalesce(p_data->'attendance_ids',p_data->'appointment_ids','[]'::jsonb))
      union
      select b.attendance_id
      from public.billing_records b
      join jsonb_array_elements_text(coalesce(p_data->'record_ids','[]'::jsonb)) selected(id) on selected.id=b.id::text
    )
    select 1 from selected_attendances s
    where (select count(*) from public.billing_records b where b.attendance_id=s.attendance_id)>1
  ) then
    raise exception 'NF com cobranças independentes deve usar os IDs das cobranças profissionais';
  end if;
  return public.save_billing_legacy_single_charge(p_actor,p_kind,p_data);
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_billing_denial(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 actor_role text;
 act text:=p_data->>'action';
 charge public.billing_records%rowtype;
 attendance public.attendances%rowtype;
 case_row public.billing_denial_cases%rowtype;
 appeal_row public.billing_denial_appeals%rowtype;
 result_id uuid;
 old_snapshot jsonb;
 event_name text;
 value_amount numeric(14,2);
 action_date date;
 note_value text:=nullif(trim(p_data->>'notes'),'');
begin
 select role into actor_role from public.users where id=p_actor;
 if actor_role is null or actor_role not in ('general_manager','secretary')
    then raise exception 'Sem permissão para gerir glosas';end if;
 if act not in ('OPEN_CASE','FILE_APPEAL','DECIDE_APPEAL','REGISTER_RECOVERY','CLOSE_CASE')
    then raise exception 'Ação de glosa inválida';end if;
 if length(coalesce(note_value,''))>2000 then raise exception 'Observação muito longa';end if;

 if act='OPEN_CASE' then
   select * into charge from public.billing_records
    where id=nullif(p_data->>'billing_record_id','')::uuid;
 else
   select * into case_row from public.billing_denial_cases
    where id=nullif(p_data->>'denial_id','')::uuid for update;
   if not found then raise exception 'Glosa inexistente';end if;
   if case_row.updated_at is distinct from nullif(p_data->>'updated_at','')::timestamptz
     then raise exception 'Glosa alterada. Atualize a página';end if;
   select * into charge from public.billing_records where id=case_row.billing_record_id;
 end if;
 if charge.id is null or charge.professional_id is null or charge.billing_method<>'CONVENIO'
    then raise exception 'Glosa exige cobrança profissional de convênio';end if;
 select * into attendance from public.attendances where id=charge.attendance_id;
 if attendance.id is null or attendance.status<>'realized'
    then raise exception 'Atendimento não realizado';end if;
 if actor_role='secretary' and not exists(select 1 from public.agenda_access a
    where a.user_id=p_actor and a.professional_id=charge.professional_id)
    then raise exception 'Sem acesso à agenda deste profissional';end if;
 if act<>'OPEN_CASE' and (case_row.billing_entity_id is distinct from charge.billing_entity_id)
    then raise exception 'Entidade financeira histórica divergente';end if;
 if act<>'OPEN_CASE' and case_row.status='CLOSED'
    then raise exception 'Glosa encerrada. Abra nova ocorrência para registro adicional';end if;
 old_snapshot:=case when act='OPEN_CASE' then null else to_jsonb(case_row) end;

 if act='OPEN_CASE' then
   action_date:=nullif(p_data->>'denied_on','')::date;
   value_amount:=nullif(p_data->>'denied_amount','')::numeric;
   if p_data->>'denial_kind' not in ('TOTAL','PARCIAL')
      then raise exception 'Informe se a glosa foi total ou parcial';end if;
   if action_date is null or action_date<attendance.date or action_date>current_date
      or value_amount is null or value_amount<=0 or value_amount>999999999999.99
      or length(trim(coalesce(p_data->>'reason',''))) not between 5 and 2000
      or length(coalesce(p_data->>'payer_reference',''))>120
      then raise exception 'Informe data, valor e motivo válidos para a glosa';end if;
   insert into public.billing_denial_cases(
      billing_record_id,billing_entity_id,denied_on,denial_kind,denied_amount,reason,payer_reference,
      notes,created_by,updated_by)
   values(charge.id,charge.billing_entity_id,action_date,p_data->>'denial_kind',value_amount,
      trim(p_data->>'reason'),nullif(trim(p_data->>'payer_reference'),''),
      note_value,p_actor,p_actor) returning * into case_row;
   event_name:='OPENED';

 elsif act='FILE_APPEAL' then
   if case_row.recovered_amount>=case_row.denied_amount then
     raise exception 'Glosa integralmente recuperada. Não é possível abrir outro recurso';end if;
   action_date:=nullif(p_data->>'filed_on','')::date;
   value_amount:=nullif(p_data->>'appealed_amount','')::numeric;
   if action_date is null or action_date<case_row.denied_on or action_date>current_date
     or value_amount is null or value_amount<=0 or value_amount>case_row.denied_amount
     or length(trim(coalesce(p_data->>'protocol',''))) not between 3 and 120
   then raise exception 'Informe data, valor e protocolo do recurso válidos';end if;
   if exists(select 1 from public.billing_denial_appeals where denial_id=case_row.id and decision='PENDING')
   then raise exception 'Já existe recurso aguardando decisão';end if;
   insert into public.billing_denial_appeals(
      denial_id,filed_on,appealed_amount,protocol,notes,created_by)
   values(case_row.id,action_date,value_amount,trim(p_data->>'protocol'),note_value,p_actor)
   returning * into appeal_row;
   update public.billing_denial_cases set status='APPEALED',
      updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id;
   event_name:='APPEAL_FILED';

 elsif act='DECIDE_APPEAL' then
   select * into appeal_row from public.billing_denial_appeals
     where id=nullif(p_data->>'appeal_id','')::uuid and denial_id=case_row.id for update;
   if appeal_row.id is null or appeal_row.decision<>'PENDING'
      then raise exception 'Recurso não está pendente';end if;
   action_date:=nullif(p_data->>'decision_on','')::date;
   value_amount:=coalesce(nullif(p_data->>'approved_amount','')::numeric,0);
   if p_data->>'decision' not in ('ACCEPTED','PARTIAL','REJECTED')
     or action_date is null or action_date<appeal_row.filed_on or action_date>current_date
     or value_amount<0 or value_amount>appeal_row.appealed_amount
     or (p_data->>'decision'='ACCEPTED' and value_amount<>appeal_row.appealed_amount)
     or (p_data->>'decision'='PARTIAL' and (value_amount<=0 or value_amount>=appeal_row.appealed_amount))
     or (p_data->>'decision'='REJECTED' and value_amount<>0)
   then raise exception 'Decisão ou valor deferido incompatível com o recurso';end if;
   update public.billing_denial_appeals set decision=p_data->>'decision',
     decision_on=action_date,approved_amount=value_amount,
     decision_notes=note_value,decided_by=p_actor where id=appeal_row.id
     returning * into appeal_row;
   update public.billing_denial_cases set status=case when recovered_amount>0 then 'PARTIAL' else 'DECIDED' end,
     updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id;
   event_name:='APPEAL_DECIDED';

 elsif act='REGISTER_RECOVERY' then
   select * into appeal_row from public.billing_denial_appeals
     where id=nullif(p_data->>'appeal_id','')::uuid and denial_id=case_row.id for update;
   action_date:=nullif(p_data->>'recovered_on','')::date;
   value_amount:=nullif(p_data->>'amount','')::numeric;
   if appeal_row.id is null or appeal_row.decision not in ('ACCEPTED','PARTIAL')
     or action_date is null or action_date<appeal_row.decision_on or action_date>current_date
     or value_amount is null or value_amount<=0
     or length(trim(coalesce(p_data->>'receipt_reference',''))) not between 3 and 120
     or case_row.recovered_amount+value_amount>case_row.denied_amount
     or value_amount+(select coalesce(sum(amount),0) from public.billing_denial_recoveries
                       where appeal_id=appeal_row.id)>appeal_row.approved_amount
   then raise exception 'Recuperação excede o deferimento ou faltam comprovantes';end if;
   insert into public.billing_denial_recoveries(
      denial_id,appeal_id,recovered_on,amount,receipt_reference,notes,created_by)
   values(case_row.id,appeal_row.id,action_date,value_amount,
      trim(p_data->>'receipt_reference'),note_value,p_actor);
   update public.billing_denial_cases set recovered_amount=recovered_amount+value_amount,
     status=case when recovered_amount+value_amount=denied_amount then 'RECOVERED' else 'PARTIAL' end,
     updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id;
   event_name:='RECOVERY_RECORDED';

 elsif act='CLOSE_CASE' then
   if length(trim(coalesce(p_data->>'closing_reason',''))) not between 5 and 1000
     then raise exception 'Informe o motivo do encerramento';end if;
   if exists(select 1 from public.billing_denial_appeals where denial_id=case_row.id and decision='PENDING')
     then raise exception 'Resolva o recurso pendente antes de encerrar';end if;
   update public.billing_denial_cases set status='CLOSED',closed_at=clock_timestamp(),
     closed_by=p_actor,closing_reason=trim(p_data->>'closing_reason'),
     updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id;
   event_name:='CLOSED';
 end if;

 select * into case_row from public.billing_denial_cases where id=case_row.id;
 result_id:=case_row.id;
 insert into public.billing_denial_events(denial_id,actor_id,event_type,before_snapshot,after_snapshot)
 values(result_id,p_actor,event_name,old_snapshot,
   jsonb_build_object('case',to_jsonb(case_row),
     'appeal',case when appeal_row.id is null then null else to_jsonb(appeal_row) end,
     'payload',p_data));
 return result_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_billing_fiscal_core(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare role_name text; sid uuid; old_row jsonb; result_row jsonb; state jsonb; a jsonb;
 entity uuid; item uuid; record public.billing_records%rowtype; old_items jsonb; appointment_ids jsonb; selected_records uuid[]:='{}'; appt_id text; payer_name text; before_records jsonb; old_record jsonb; before_item_values jsonb; amount_entry record; mode text; physician public.doctors%rowtype;
begin
 perform pg_advisory_xact_lock(194701,1);
 perform pg_advisory_xact_lock(194701,2);
 select role into role_name from public.users where id=p_actor;
 if role_name is null or role_name not in ('general_manager','secretary') then raise exception 'Acesso negado'; end if;
 if p_kind='record' then p_data:=p_data||jsonb_build_object('appointment_id',coalesce(p_data->>'attendance_id',p_data->>'appointment_id'));end if;
 if p_kind='invoice' and p_data ? 'attendance_ids' then p_data:=p_data||jsonb_build_object('appointment_ids',p_data->'attendance_ids');end if;
 select payload into state from public.app_state where id=1;
 sid:=coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());
 if nullif(current_setting('rn.operation',true),'') is null or current_setting('rn.actor',true)<>p_actor::text then raise exception 'Operação fiscal obrigatória';end if;
 if p_kind in ('entity','link','delete_entity','delete_link') and role_name<>'general_manager' then raise exception 'Somente a gerência pode configurar entidades'; end if;
 if p_kind in ('delete_entity','delete_link') then
  if p_kind='delete_entity' then
   select to_jsonb(e) into old_row from public.billing_entities e where id=sid;
  else
   select to_jsonb(l) into old_row from public.billing_doctor_entities l where id=sid;
  end if;
  if old_row is null then raise exception 'Registro não encontrado'; end if;
  if (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Registro alterado. Atualize a página'; end if;
  if p_kind='delete_entity' then
   if exists(select 1 from public.billing_records where billing_entity_id=sid) or exists(select 1 from public.invoices where billing_entity_id=sid) or exists(select 1 from public.billing_doctor_entities where billing_entity_id=sid) then raise exception 'Entidade possui vínculos ou histórico financeiro. Inative-a para preservar o histórico'; end if;
   delete from public.billing_entities where id=sid;
  else
   delete from public.billing_doctor_entities where id=sid;
  end if;
 elsif p_kind='entity' then
  select to_jsonb(e) into old_row from public.billing_entities e where id=sid;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Registro alterado por outro usuário. Atualize a página'; end if;
  if coalesce(p_data->>'person_type','') not in ('PF','PJ') or length(regexp_replace(coalesce(p_data->>'tax_id',''),'[^0-9]','','g'))<>(case when p_data->>'person_type'='PF' then 11 else 14 end) then raise exception 'Informe CPF/CNPJ e tipo de pessoa'; end if;
  insert into public.billing_entities(id,name,tax_id,person_type,trade_name,active,updated_at,updated_by)
  values(sid,trim(p_data->>'name'),regexp_replace(p_data->>'tax_id','[^0-9]','','g'),p_data->>'person_type',nullif(trim(p_data->>'trade_name'),''),coalesce((p_data->>'active')::boolean,true),clock_timestamp(),p_actor)
  on conflict(id) do update set name=excluded.name,tax_id=excluded.tax_id,person_type=excluded.person_type,trade_name=excluded.trade_name,active=excluded.active,updated_at=excluded.updated_at,updated_by=p_actor
  returning to_jsonb(billing_entities.*) into result_row;
 elsif p_kind='link' then
  select to_jsonb(l) into old_row from public.billing_doctor_entities l where id=sid;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Vínculo alterado. Atualize a página'; end if;
  if not exists(select 1 from public.doctors where id=p_data->>'doctor_id') then raise exception 'Médico inexistente'; end if;
  if not exists(select 1 from public.billing_entities where id=(p_data->>'billing_entity_id')::uuid and active) then raise exception 'Entidade inativa ou inexistente'; end if;
  if exists(select 1 from public.billing_doctor_entities where doctor_id=p_data->>'doctor_id' and billing_entity_id=(p_data->>'billing_entity_id')::uuid and id<>sid) then raise exception 'Este vínculo já existe. Edite o vínculo cadastrado'; end if;
  insert into public.billing_doctor_entities(id,doctor_id,billing_entity_id,active,updated_at,updated_by)
  values(sid,p_data->>'doctor_id',(p_data->>'billing_entity_id')::uuid,coalesce((p_data->>'active')::boolean,true),clock_timestamp(),p_actor)
  on conflict(id) do update set active=excluded.active,updated_at=excluded.updated_at,updated_by=p_actor
  returning to_jsonb(billing_doctor_entities.*) into result_row;
 elsif p_kind='record' then
  if not exists(select 1 from public.attendances where id=p_data->>'appointment_id')
     and p_data->>'billing_method'='PARTICULAR' then
   select clinical into a from jsonb_array_elements(coalesce(state->'appointments','[]')) clinical
    where clinical->>'id'=p_data->>'appointment_id';
   if a is null or a->>'forma_cobranca' is distinct from 'PARTICULAR' then
    raise exception 'Use a forma de cobrança informada no agendamento';
   end if;
   if role_name<>'general_manager' and not exists(select 1 from public.agenda_access g
      where g.user_id=p_actor and g.professional_id in(a->>'doctorId',a->>'anesthetistId')) then
    raise exception 'Agenda sem permissão';
   end if;
   insert into public.attendances(id,appointment_id,origin,patient_id,doctor_id,date,procedure,insurance,billing_method,status)
    values(a->>'id',a->>'id','AGENDA',nullif(a->>'patientId',''),a->>'doctorId',(a->>'date')::date,
     coalesce(a->>'procedure','Procedimento'),coalesce(a->>'insurance',(select p->>'insurance'
       from jsonb_array_elements(coalesce(state->'patients','[]')) p where p->>'id'=a->>'patientId'),''),
     'PARTICULAR',a->>'status');
  end if;
  a:=public.financial_attendance(p_data->>'appointment_id');
  if a is null then raise exception 'Atendimento inexistente'; end if;
  if role_name<>'general_manager' and not exists(select 1 from public.app_state s cross join lateral jsonb_array_elements(coalesce(s.payload->'appointments','[]')) clinical join public.agenda_access g on g.user_id=p_actor and g.professional_id in(clinical->>'doctorId',clinical->>'anesthetistId') where s.id=1 and clinical->>'id'=a->>'appointment_id') then raise exception 'Agenda sem permissão'; end if;
  select to_jsonb(b) into old_row from public.billing_records b where attendance_id=p_data->>'appointment_id';
  if old_row is not null then sid:=(old_row->>'id')::uuid; else sid:=gen_random_uuid(); end if;
  perform set_config('rn.record',sid::text,true);
  if public.prepare_private_payment(old_row,p_data) then return sid;end if;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Financeiro alterado por outro usuário. Atualize'; end if;
  if exists(select 1 from public.invoice_billing_records where billing_record_id=sid and is_active) then raise exception 'Edite o pagamento e os dados fiscais na NF/lote vinculada'; end if;
  entity:=(p_data->>'billing_entity_id')::uuid;
  a:=public.attribute_financial_attendance(p_data->>'appointment_id',entity);
  if entity is null or (old_row->>'billing_entity_id' is distinct from entity::text and not exists(
   select 1 from public.billing_doctor_entities l join public.billing_entities e on e.id=l.billing_entity_id
   where l.billing_entity_id=entity and l.doctor_id in (a->>'doctorId',a->>'anesthetistId') and l.active and e.active
)) then raise exception 'Selecione uma entidade vinculada ao médico'; end if;
  if p_data->>'billing_method' not in ('PARTICULAR','CONVENIO') or p_data->>'payment_status' not in ('PENDENTE','PAGO') then raise exception 'Forma de cobrança ou status inválido'; end if;
  select * into physician from public.doctors where id=a->>'doctorId';
  if not physician.billing_enabled then raise exception 'Controle financeiro não habilitado para o médico';end if;
  mode:=case when p_data->>'billing_method'='PARTICULAR' or old_row->>'settlement_mode'='DIRECT' or not physician.invoice_enabled then 'DIRECT' else 'INVOICE' end;
  if mode='INVOICE' and p_data->>'payment_status'='PAGO' then raise exception 'Registre o pagamento do convênio na NF/lote'; end if;
  if p_data->>'payment_status'='PAGO' and (nullif(p_data->>'paid_at','') is null or nullif(p_data->>'received_amount','') is null) then raise exception 'Pagamento particular exige valor e data'; end if;
  if public.appointment_billing_method(a) is not null and public.appointment_billing_method(a) is distinct from p_data->>'billing_method' then raise exception 'Use a forma de cobrança informada no agendamento'; end if;
  insert into public.billing_records(id,attendance_id,appointment_id,settlement_mode,billing_entity_id,billing_method,payment_status,invoice_number,received_amount,paid_at,notes,updated_at,updated_by)
  values(sid,p_data->>'appointment_id',a->>'appointment_id',mode,entity,p_data->>'billing_method',p_data->>'payment_status',case when p_data->>'billing_method'='PARTICULAR' then nullif(trim(p_data->>'invoice_number'),'') end,
   case when mode='DIRECT' then nullif(p_data->>'received_amount','')::numeric end,
   case when mode='DIRECT' then nullif(p_data->>'paid_at','')::date end,nullif(trim(p_data->>'notes'),''),clock_timestamp(),p_actor)
  on conflict(id) do update set settlement_mode=excluded.settlement_mode,billing_entity_id=excluded.billing_entity_id,billing_method=excluded.billing_method,payment_status=excluded.payment_status,invoice_number=excluded.invoice_number,received_amount=excluded.received_amount,paid_at=excluded.paid_at,notes=excluded.notes,updated_at=excluded.updated_at,updated_by=p_actor
  returning to_jsonb(billing_records.*) into result_row;
  update public.attendances set billing_entity_id=entity,billing_method=p_data->>'billing_method' where id=p_data->>'appointment_id';
  -- Preserve compatibility with the explicit scheduling choice.
  update public.app_state st set payload=jsonb_set(st.payload,'{appointments}',coalesce((select jsonb_agg(case when x->>'id'=a->>'appointment_id' then x||jsonb_build_object('forma_cobranca',p_data->>'billing_method') else x end order by n) from jsonb_array_elements(st.payload->'appointments') with ordinality arr(x,n)),'[]')),updated_at=greatest(clock_timestamp(),st.updated_at+interval '1 millisecond') where st.id=1;
  perform public.finish_private_payment(p_actor,sid,p_data);
 elsif p_kind='invoice' then
  if coalesce(p_data->>'recipient_type','CONVENIO')='PARTICULAR' then
   sid:=public.save_private_invoice(p_actor,p_data);return sid;
  end if;
  if exists(select 1 from public.invoices where id=sid and recipient_type='PARTICULAR') then raise exception 'Não altere o tipo de uma NF emitida';end if;
  if role_name<>'general_manager' then raise exception 'Somente a gerência pode gerenciar lotes'; end if;
  select to_jsonb(i) into old_row from public.invoices i where id=sid;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'NF alterada por outro usuário. Atualize'; end if;
  entity:=(p_data->>'billing_entity_id')::uuid;
  if nullif(trim(p_data->>'payer'),'') is null or nullif(trim(p_data->>'invoice_number'),'') is null or nullif(p_data->>'issue_date','') is null then raise exception 'Preencha número, pagador e emissão'; end if;
  payer_name:=public.billing_payer_key(p_data->>'payer');
  if not exists(
   select 1 from (
    select insurance as name from public.attendances
    union all select value->>'insurance' as name from jsonb_array_elements(coalesce(state->'patients','[]'))
    union all select value->>'insurance' from jsonb_array_elements(coalesce(state->'appointments','[]'))
    union all select old_row->>'payer'
   ) payers where public.billing_payer_key(name)=payer_name and payer_name<>''
  ) then raise exception 'Selecione um pagador existente no sistema'; end if;
  if not exists(select 1 from public.billing_entities where id=entity and (active or old_row->>'billing_entity_id'=entity::text)) then raise exception 'Entidade inativa ou inexistente'; end if;
  if p_data ? 'appointment_ids' then
   appointment_ids:=p_data->'appointment_ids';
   if jsonb_typeof(appointment_ids) is distinct from 'array' then raise exception 'Lista de atendimentos inválida'; end if;
  else
   -- Compatibility for an already open older client. Every supplied ID must exist.
   if jsonb_typeof(p_data->'record_ids') is distinct from 'array' then raise exception 'Lista de atendimentos inválida'; end if;
   appointment_ids:='[]';
   for item in select value::uuid from jsonb_array_elements_text(p_data->'record_ids') loop
    select * into record from public.billing_records where id=item;
    if not found then raise exception 'Faturamento inexistente'; end if;
    appointment_ids:=appointment_ids||jsonb_build_array(record.attendance_id);
   end loop;
  end if;
  if jsonb_array_length(appointment_ids)=0 and nullif(p_data->>'paid_at','') is not null then raise exception 'Vincule pelo menos um atendimento antes de confirmar o pagamento'; end if;
  if p_data ? 'item_amounts' then
   if jsonb_typeof(p_data->'item_amounts') is distinct from 'object' then raise exception 'Valores individuais inválidos'; end if;
   for amount_entry in select * from jsonb_each(p_data->'item_amounts') loop
    if not (appointment_ids ? amount_entry.key) or jsonb_typeof(amount_entry.value) not in ('number','null') then raise exception 'Valor individual inválido ou atendimento não selecionado'; end if;
    if jsonb_typeof(amount_entry.value)='number' and ((amount_entry.value::text)::numeric<0 or (amount_entry.value::text)::numeric>9999999999.99 or round((amount_entry.value::text)::numeric,2)<>(amount_entry.value::text)::numeric) then raise exception 'Valor individual deve ser positivo ou zero, com até duas casas decimais'; end if;
   end loop;
  end if;
  select coalesce(jsonb_agg(to_jsonb(ib)),'[]') into before_item_values from public.invoice_billing_records ib where ib.invoice_id=sid;
  select coalesce(jsonb_agg(billing_record_id),'[]') into old_items from public.invoice_billing_records where invoice_billing_records.invoice_id=sid;
  select coalesce(jsonb_agg(to_jsonb(b)),'[]') into before_records from public.billing_records b where b.id in(select billing_record_id from public.invoice_billing_records where invoice_billing_records.invoice_id=sid);
  for appt_id in select distinct value from jsonb_array_elements_text(appointment_ids) loop
   a:=public.attribute_financial_attendance(appt_id,entity);
   if a is null then raise exception 'Atendimento cancelado ou inexistente'; end if;
   select * into record from public.billing_records b where b.attendance_id=appt_id;
   if a->>'status' is distinct from 'realized' then raise exception 'Somente atendimentos realizados podem ser vinculados'; end if;
   if public.appointment_billing_method(a,record.billing_method) is distinct from 'CONVENIO' then raise exception 'Atendimento não é cobrado por convênio'; end if;
   if public.billing_payer_key(coalesce(a->>'insurance',''))<>payer_name then raise exception 'Convênio do atendimento diferente do pagador'; end if;
   if not exists(select 1 from public.invoice_billing_records ib where ib.invoice_id=sid and ib.billing_record_id=record.id and record.billing_entity_id=entity) and not exists(select 1 from public.billing_doctor_entities l join public.billing_entities be on be.id=l.billing_entity_id and be.active where l.billing_entity_id=entity and l.active and l.doctor_id in(a->>'doctorId',a->>'anesthetistId')) then raise exception 'Médico sem vínculo ativo com a entidade recebedora'; end if;
   if not exists(select 1 from public.invoice_billing_records where invoice_id=sid and billing_record_id=record.id) and not exists(select 1 from public.doctors where id=a->>'doctorId' and invoice_enabled) then raise exception 'Gestão de NF não habilitada para o médico';end if;
   if record.id is not null and record.settlement_mode='DIRECT' then raise exception 'Atendimento utiliza pagamento direto, sem gestão de NF';end if;
   if record.id is not null and exists(select 1 from public.invoice_billing_records ib where ib.billing_record_id=record.id and ib.invoice_id<>sid and ib.is_active) then raise exception 'Atendimento já vinculado a outra NF'; end if;
   if record.id is not null and (record.billing_method<>'CONVENIO' or (record.payment_status='PAGO' and not exists(select 1 from public.invoice_billing_records ib where ib.billing_record_id=record.id and ib.invoice_id=sid))) then raise exception 'Faturamento individual já configurado ou pago. Revise antes de vincular'; end if;
   old_record:=case when record.id is not null then to_jsonb(record) end;
   if record.id is null then
    insert into public.billing_records(attendance_id,appointment_id,settlement_mode,billing_entity_id,billing_method,payment_status,received_amount,paid_at,invoice_number,updated_at,updated_by)
    values(appt_id,a->>'appointment_id','INVOICE',entity,'CONVENIO','PENDENTE',null,null,null,clock_timestamp(),p_actor) returning * into record;
   else
    update public.billing_records b set billing_entity_id=entity,received_amount=null,paid_at=null,invoice_number=null,updated_at=clock_timestamp(),updated_by=p_actor where b.id=record.id returning b.* into record;
   end if;
   update public.attendances set billing_entity_id=entity where id=appt_id;
   selected_records:=array_append(selected_records,record.id);
   insert into public.billing_audit(actor_id,action,record_id,before_data,after_data) values(p_actor,'invoice_record_prepared',record.id,old_record,to_jsonb(record));
  end loop;
  insert into public.invoices(id,billing_entity_id,invoice_number,payer,issue_date,total_amount,net_amount,paid_at,notes,updated_at,updated_by)
  values(sid,entity,trim(p_data->>'invoice_number'),payer_name,(p_data->>'issue_date')::date,nullif(p_data->>'total_amount','')::numeric,nullif(p_data->>'net_amount','')::numeric,nullif(p_data->>'paid_at','')::date,nullif(trim(p_data->>'notes'),''),clock_timestamp(),p_actor)
  on conflict(id) do update set billing_entity_id=excluded.billing_entity_id,invoice_number=excluded.invoice_number,payer=excluded.payer,issue_date=excluded.issue_date,total_amount=excluded.total_amount,net_amount=excluded.net_amount,paid_at=excluded.paid_at,notes=excluded.notes,updated_at=excluded.updated_at,updated_by=p_actor
  returning to_jsonb(invoices.*) into result_row;
  update public.billing_records set payment_status='PENDENTE',updated_at=clock_timestamp(),updated_by=p_actor where id in(select billing_record_id from public.invoice_billing_records where invoice_billing_records.invoice_id=sid);
  delete from public.invoice_billing_records where invoice_billing_records.invoice_id=sid and not(billing_record_id=any(selected_records));
  insert into public.invoice_billing_records(invoice_id,billing_record_id) select sid,unnest(selected_records) on conflict(invoice_id,billing_record_id) do nothing;
  update public.billing_records set payment_status=case when nullif(p_data->>'paid_at','') is null then 'PENDENTE' else 'PAGO' end,received_amount=null,paid_at=null,invoice_number=null,updated_at=clock_timestamp(),updated_by=p_actor where id=any(selected_records);
  update public.invoice_billing_records ib set received_amount=(p_data->'item_amounts'->>b.attendance_id)::numeric from public.billing_records b where b.id=ib.billing_record_id and ib.invoice_id=sid and (p_data->'item_amounts') ? b.attendance_id;
  old_row:=coalesce(old_row,'{}')||jsonb_build_object('record_ids',old_items,'records',before_records,'items',before_item_values);
  result_row:=result_row||jsonb_build_object('record_ids',to_jsonb(selected_records),'appointment_ids',appointment_ids,'items',(select coalesce(jsonb_agg(to_jsonb(ib)),'[]') from public.invoice_billing_records ib where ib.invoice_id=sid));
 else raise exception 'Operação inválida'; end if;
 insert into public.billing_audit(actor_id,action,record_id,before_data,after_data) values(p_actor,p_kind,sid,old_row,result_row);
 
 return sid;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_billing_legacy_single_charge(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid uuid; old_invoice public.invoices%rowtype; b public.billing_records%rowtype; a public.attendances%rowtype; r public.invoice_requests%rowtype;
 entry record; key text; recipient jsonb; canonical text; target_id text; total numeric; selected jsonb; previous_payment_status text;
begin
 perform pg_advisory_xact_lock(194701,1);perform pg_advisory_xact_lock(194701,2);
 if not exists(select 1 from public.users where id=p_actor and (role='general_manager' or (role='secretary' and p_kind='record'))) then raise exception 'Acesso negado';end if;
 perform public.financial_operation(p_actor,p_kind,p_data->>'id');
 foreach key in array array['total_amount','net_amount','received_amount','closing_adjustment'] loop
  if nullif(p_data->>key,'') is not null then p_data:=jsonb_set(p_data,array[key],to_jsonb(round((p_data->>key)::numeric,2)));end if;
 end loop;
 if p_kind in ('undo_invoice','cancel_invoice','replace_invoice') then
  select * into old_invoice from public.invoices where id=(p_data->>'id')::uuid for update;
  if old_invoice.id is null then raise exception 'NF não encontrada';end if;
  if old_invoice.status<>'ACTIVE' or old_invoice.voided_at is not null then raise exception 'NF sem vínculo operacional ativo';end if;
  if old_invoice.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'NF alterada. Atualize a página';end if;
  if nullif(trim(p_data->>'reason'),'') is null then raise exception 'Informe o motivo da operação fiscal';end if;
  update public.invoice_billing_records set is_active=false where invoice_id=old_invoice.id;
  update public.billing_records set payment_status='PENDENTE' where billing_method='CONVENIO' and id in(select billing_record_id from public.invoice_billing_records where invoice_id=old_invoice.id);
  select * into r from public.invoice_requests where invoice_id=old_invoice.id;
  if r.id is not null then update public.invoice_requests set status='PENDING',invoice_id=null where id=r.id;end if;
  if p_kind='undo_invoice' then
   update public.invoices set voided_at=clock_timestamp(),voided_by=p_actor,void_reason=trim(p_data->>'reason') where id=old_invoice.id;
  elsif p_kind='cancel_invoice' then
   update public.invoices set status='CANCELLED',cancelled_at=clock_timestamp(),cancelled_by=p_actor,cancellation_reason=trim(p_data->>'reason') where id=old_invoice.id;
  else
   if jsonb_typeof(p_data->'replacement') is distinct from 'object' then raise exception 'Informe a NF substituta';end if;
   recipient:=(p_data->'replacement')-'id'-'updated_at';
   if recipient->>'recipient_type' is distinct from old_invoice.recipient_type then raise exception 'Preserve o tipo da NF substituída';end if;
   if r.id is not null then recipient:=recipient||jsonb_build_object('request_id',r.id);end if;
   -- The same operation context is retained through creation, allocation and payment parts.
   foreach key in array array['total_amount','net_amount','closing_adjustment'] loop
    if nullif(recipient->>key,'') is not null then recipient:=jsonb_set(recipient,array[key],to_jsonb(round((recipient->>key)::numeric,2)));end if;
   end loop;
   p_data:=recipient;
   update public.invoices set status='REPLACED' where id=old_invoice.id;
  end if;
  if p_kind<>'replace_invoice' then
   perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return old_invoice.id;
  end if;
 end if;
 if p_kind='record' then
  target_id:=coalesce(p_data->>'attendance_id',p_data->>'appointment_id');
  if exists(select 1 from public.attendances where id=target_id and status='cancelled') then raise exception 'Atendimento cancelado';end if;
  select * into b from public.billing_records where attendance_id=target_id;
  previous_payment_status:=b.payment_status;
  -- Ignore stale client payment values when explicitly returning to pending.
  if b.payment_status='PAGO' and p_data->>'payment_status'='PENDENTE' then
   p_data:=p_data||jsonb_build_object('received_amount',null,'paid_at',null);
  end if;
  if p_data->'fiscal'->>'taker_kind'='PATIENT' then
   select * into r from public.invoice_requests where billing_record_id=b.id and status in ('PENDING','ISSUED');
   select p->>'name' into canonical from public.app_state s cross join lateral jsonb_array_elements(s.payload->'patients') p where s.id=1 and p->>'id'=coalesce((select patient_id from public.attendances where id=target_id),(select ap->>'patientId' from public.app_state st cross join lateral jsonb_array_elements(st.payload->'appointments') ap where ap->>'id'=target_id));
   p_data:=jsonb_set(p_data,'{fiscal,taker_name}',to_jsonb(coalesce(r.taker_name,canonical,'')));
  end if;
 end if;
 if p_kind in ('invoice','replace_invoice') then
  if exists(select 1 from public.invoices where id=nullif(p_data->>'id','')::uuid and (status<>'ACTIVE' or voided_at is not null)) then raise exception 'Documento histórico não pode ser editado';end if;
  if coalesce(p_data->>'recipient_type','CONVENIO')='CONVENIO' then
   selected:=coalesce(p_data->'attendance_ids',p_data->'appointment_ids');
   if jsonb_typeof(selected) is distinct from 'array' or jsonb_array_length(selected)=0 then raise exception 'Selecione os atendimentos da NF';end if;
   if nullif(p_data->>'net_amount','') is null then raise exception 'Informe o valor líquido';end if;
   if jsonb_typeof(p_data->'item_amounts') is distinct from 'object' then raise exception 'Informe o valor de cada atendimento';end if;
   total:=0;
   for key in select distinct value from jsonb_array_elements_text(selected) loop
    if jsonb_typeof(p_data->'item_amounts'->key) is distinct from 'number' then raise exception 'Informe o valor de cada atendimento';end if;
    p_data:=jsonb_set(p_data,array['item_amounts',key],to_jsonb(round((p_data->'item_amounts'->>key)::numeric,2)));
    total:=total+(p_data->'item_amounts'->>key)::numeric;
   end loop;
   if total+coalesce((p_data->>'closing_adjustment')::numeric,0)<>(p_data->>'net_amount')::numeric then raise exception 'A soma dos itens e ajuste deve ser igual ao valor líquido';end if;
  end if;
 end if;
 sid:=public.save_billing_fiscal_core(p_actor,case when p_kind='replace_invoice' then 'invoice' else p_kind end,p_data);
 if p_kind='record' then
  select * into b from public.billing_records where id=sid;
  if b.billing_method='PARTICULAR' and b.payment_status='PAGO' then
   if p_data ? 'payment_parts' then perform public.write_payment_parts(sid,null,p_data->'payment_parts');
    update public.billing_records set payment_composition_verified=true where id=sid;
   elsif not exists(select 1 from public.payment_parts where billing_record_id=sid) and (b.payment_composition_verified or p_data ? 'fiscal' or previous_payment_status is distinct from 'PAGO') then raise exception 'Informe as formas de pagamento';end if;
  elsif previous_payment_status='PAGO' and b.payment_status='PENDENTE' then
   delete from public.payment_parts where billing_record_id=sid;
   update public.billing_records set received_amount=null,paid_at=null,payment_composition_verified=false where id=sid;
  end if;
 elsif p_kind in ('invoice','replace_invoice') then
  update public.invoices set closing_adjustment=coalesce((p_data->>'closing_adjustment')::numeric,0),closing_adjustment_reason=nullif(trim(p_data->>'closing_adjustment_reason'),''),allocation_verified=true where id=sid;
  if coalesce(p_data->>'recipient_type','CONVENIO')='CONVENIO' and nullif(p_data->>'paid_at','') is not null then
   if p_data ? 'payment_parts' then perform public.write_payment_parts(null,sid,p_data->'payment_parts');
    update public.invoices set payment_composition_verified=true where id=sid;
   elsif not exists(select 1 from public.payment_parts where invoice_id=sid) then raise exception 'Informe as formas de pagamento';end if;
  elsif coalesce(p_data->>'recipient_type','CONVENIO')='CONVENIO' then
   delete from public.payment_parts where invoice_id=sid;
   update public.invoices set payment_composition_verified=false where id=sid;
  end if;
  if p_kind='replace_invoice' then update public.invoices set replaced_by_invoice_id=sid where id=old_invoice.id;end if;
 end if;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return sid;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_billing_portal_rule(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  key text:=upper(trim(regexp_replace(coalesce(p_data->>'destination_key',''),'\s+',' ','g')));
  channel text:=nullif(p_data->>'submission_channel_code','');
  doctor text:=nullif(p_data->>'professional_id','');
  start_date date:=nullif(p_data->>'valid_from','')::date;
  end_date date:=nullif(p_data->>'valid_to','')::date;
  anchor text:=p_data->>'starts_from';
  days_count integer:=nullif(p_data->>'deadline_days','')::integer;
  lead_days integer:=nullif(p_data->>'alert_before_days','')::integer;
  saved_id uuid;
begin
  if not exists(select 1 from public.users where id=p_actor and role='general_manager')
    then raise exception 'Somente a gerência pode configurar prazos';end if;
  if length(key) not between 2 and 120 or channel not in ('PORTAL_CONVENIO','COOPERATIVA','MANUAL')
     or anchor not in ('SERVICE_DATE','GUIDE_RECEIVED') or start_date is null
     or days_count not between 1 and 365 or lead_days not between 0 and least(days_count,90)
     or (end_date is not null and end_date<start_date) then
     raise exception 'Preencha destino, canal, início da vigência, prazo e antecedência válidos';
  end if;
  if doctor is not null and not exists(select 1 from public.doctors where id=doctor and active)
    then raise exception 'Profissional inexistente';end if;
  -- Serializa edição de regras para impedir duas regras sobrepostas concorrentes.
  perform pg_advisory_xact_lock(194701,11);
  if exists(select 1 from public.billing_portal_deadline_rules r
    where r.active and r.destination_key=key and r.submission_channel_code=channel
      and r.professional_id is not distinct from doctor
      and r.valid_from<=coalesce(end_date,'infinity'::date)
      and start_date<=coalesce(r.valid_to,'infinity'::date))
    then raise exception 'Já existe regra sobreposta para esse destino, canal e profissional';end if;
  insert into public.billing_portal_deadline_rules(destination_key,submission_channel_code,professional_id,
      starts_from,deadline_days,alert_before_days,valid_from,valid_to,created_by)
  values(key,channel,doctor,anchor,days_count,lead_days,start_date,end_date,p_actor)
  returning id into saved_id;
  return saved_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_billing_portal_submission(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_role text;
  record_id uuid:=nullif(p_data->>'billing_record_id','')::uuid;
  charge public.billing_records%rowtype;
  attendance public.attendances%rowtype;
  old_row public.billing_portal_submissions%rowtype;
  new_row public.billing_portal_submissions%rowtype;
  saved_id uuid;
  destination text:=upper(trim(regexp_replace(coalesce(p_data->>'destination_key',''),'\s+',' ','g')));
  channel text:=nullif(p_data->>'submission_channel_code','');
  guide_date date:=nullif(p_data->>'guide_received_at','')::date;
  action text:=p_data->>'action';
  submission_date date:=nullif(p_data->>'submitted_at','')::date;
  protocol text:=nullif(trim(p_data->>'portal_protocol'),'');
  note_value text:=nullif(trim(p_data->>'notes'),'');
begin
  select role into actor_role from public.users where id=p_actor;
  if actor_role not in ('general_manager','secretary') or actor_role is null
    then raise exception 'Acesso negado ao envio de guias';end if;
  select * into charge from public.billing_records where id=record_id;
  if not found or charge.professional_id is null or charge.billing_method<>'CONVENIO'
    or charge.settlement_mode<>'INVOICE' then
    raise exception 'Cobrança profissional de convênio não elegível';
  end if;
  select * into attendance from public.attendances where id=charge.attendance_id;
  if not found or attendance.status<>'realized' then raise exception 'Atendimento ainda não realizado';end if;
  if actor_role='secretary' and not exists(select 1 from public.agenda_access
    where user_id=p_actor and professional_id=charge.professional_id)
    then raise exception 'Sem acesso à agenda desse profissional';end if;
  if action not in ('SAVE_PENDING','MARK_SUBMITTED')
    or length(destination) not between 2 and 120
    or channel not in ('PORTAL_CONVENIO','COOPERATIVA','MANUAL')
    or (charge.submission_channel_code not in ('LEGADO','MANUAL')
        and channel is distinct from charge.submission_channel_code)
    or (guide_date is not null and guide_date>current_date)
    or length(coalesce(note_value,''))>2000 then
    raise exception 'Revise destino, canal e dados da guia';
  end if;
  if action='MARK_SUBMITTED' and
    (guide_date is null or submission_date is null or submission_date>current_date
      or submission_date<guide_date or length(coalesce(protocol,'')) not between 3 and 120)
    then raise exception 'Faturado no portal exige recebimento da guia, data e protocolo válidos';end if;
  if action='SAVE_PENDING' and (submission_date is not null or protocol is not null)
    then raise exception 'Data e protocolo pertencem apenas à confirmação de faturamento';end if;

  perform pg_advisory_xact_lock(194701,12);
  select * into old_row from public.billing_portal_submissions where billing_record_id=record_id for update;
  if old_row.status='FATURADO' then raise exception 'Guia já faturada no portal. Preserve o histórico';end if;
  if old_row.id is not null and old_row.guide_received_at is not null
      and guide_date is null then
    raise exception 'Para corrigir o recebimento de uma guia já registrada, contate a gerência';end if;

  if old_row.id is null then
    insert into public.billing_portal_submissions(
      billing_record_id,status,destination_key,submission_channel_code,guide_received_at,
      submitted_at,portal_protocol,notes,submitted_by,created_by,updated_by)
    values(record_id,case when action='MARK_SUBMITTED' then 'FATURADO' else 'PENDENTE' end,
      destination,channel,guide_date,
      case when action='MARK_SUBMITTED' then submission_date end,
      case when action='MARK_SUBMITTED' then protocol end,note_value,
      case when action='MARK_SUBMITTED' then p_actor end,p_actor,p_actor)
    returning * into new_row;
  else
    update public.billing_portal_submissions set
      status=case when action='MARK_SUBMITTED' then 'FATURADO' else 'PENDENTE' end,
      destination_key=destination,submission_channel_code=channel,
      guide_received_at=guide_date,
      submitted_at=case when action='MARK_SUBMITTED' then submission_date end,
      portal_protocol=case when action='MARK_SUBMITTED' then protocol end,
      submitted_by=case when action='MARK_SUBMITTED' then p_actor end,
      notes=note_value,updated_at=clock_timestamp(),updated_by=p_actor
      where id=old_row.id returning * into new_row;
  end if;
  insert into public.billing_portal_submission_events(submission_id,actor_id,event_type,before_snapshot,after_snapshot)
    values(new_row.id,p_actor,
      case when action='MARK_SUBMITTED' then 'SUBMITTED'
        when old_row.guide_received_at is distinct from new_row.guide_received_at then 'GUIDE_UPDATED'
        else 'CONFIGURED' end,
      case when old_row.id is null then null else to_jsonb(old_row) end,to_jsonb(new_row));
  return new_row.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_billing_with_manager_approval(p_actor bigint, p_approver bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 operator_row public.users%rowtype;
 manager_row public.users%rowtype;
 original_invoice public.invoices%rowtype;
 new_invoice public.invoices%rowtype;
 saved_id uuid;
 operation_id uuid:=gen_random_uuid();
begin
 if p_kind not in ('cancel_invoice','replace_invoice','undo_invoice','restore_invoice') then
   raise exception 'Autorização restrita à alteração fiscal de NF';
 end if;
 select * into operator_row from public.users where id=p_actor;
 select * into manager_row from public.users where id=p_approver;
 if operator_row.id is null or operator_row.role not in ('general_manager','secretary')
    or manager_row.id is null or manager_row.role<>'general_manager' then
   raise exception 'Operador ou aprovador sem autorização';
 end if;
 select * into original_invoice from public.invoices
  where id=(p_data->>'id')::uuid;
 if original_invoice.id is null then raise exception 'NF não encontrada';end if;
 -- O financeiro antigo exige o perfil de gerente para executar a alteração.
 -- A trilha adicional abaixo registra o operador original de forma explícita.
 if p_kind='restore_invoice' then
  saved_id:=public.restore_billing_invoice(p_approver,p_data);
 else
  saved_id:=public.save_billing(p_approver,p_kind,p_data);
 end if;
 if p_kind='replace_invoice' then
  select * into new_invoice from public.invoices where id=saved_id;
 end if;
 insert into public.financial_logs(id,actor_id,actor_name,actor_email,kind,record_id)
 values(operation_id,operator_row.id,
  coalesce(nullif(operator_row.name,''),operator_row.email),
  operator_row.email,'manager_approval',original_invoice.id::text);
 insert into public.financial_log_changes(log_id,record_type,record_id,action,before_data,after_data)
 values(operation_id,'billing_manager_authorization',original_invoice.id::text,'INSERT',null,
  jsonb_build_object(
   'invoice_id',original_invoice.id,
   'invoice_number',original_invoice.invoice_number,
   'action_kind',p_kind,
   'authorized_by_id',manager_row.id,
   'authorized_by_name',coalesce(nullif(manager_row.name,''),manager_row.email),
   'operator_id',operator_row.id,
   'operator_name',coalesce(nullif(operator_row.name,''),operator_row.email),
   'operator_role',operator_row.role,
   'replacement_invoice_number',case when p_kind='replace_invoice'
    then new_invoice.invoice_number else null end
  ));
 return saved_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_company_finance(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid uuid:=coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());entity uuid:=(p_data->>'billing_entity_id')::uuid;old_row public.company_expenses%rowtype;link uuid:=nullif(p_data->>'paid_by_doctor_entity_link_id','')::uuid;
begin
 perform pg_advisory_xact_lock(194701,2);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Acesso restrito à gerência';end if;
 if p_kind<>'expense' then raise exception 'Cadastro de associados descontinuado. Use os vínculos com médicos';end if;
 perform public.financial_operation(p_actor,'expense',sid::text);
 select * into old_row from public.company_expenses where id=sid;
 if old_row.id is not null and old_row.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Registro alterado. Atualize';end if;
 if old_row.id is not null and old_row.billing_entity_id is distinct from entity then raise exception 'A entidade histórica não pode ser alterada';end if;
 if not exists(select 1 from public.billing_entities where id=entity and (active or old_row.id is not null)) then raise exception 'Entidade inativa ou inexistente';end if;
 if link is not null and not exists(select 1 from public.billing_doctor_entities where id=link and billing_entity_id=entity and (active or old_row.paid_by_doctor_entity_link_id=link)) then raise exception 'Selecione um vínculo médico ativo desta empresa';end if;
 if p_data->>'status'='PAGO' and (nullif(p_data->>'paid_at','') is null or (link is null and old_row.paid_by_associate_id is null)) then raise exception 'Pagamento exige data e médico vinculado';end if;
 if old_row.id is not null then
 update public.company_expenses set description=trim(p_data->>'description'),category=coalesce(p_data->>'category',''),supplier=coalesce(p_data->>'supplier',''),competence_date=(p_data->>'competence_date')::date,due_date=nullif(p_data->>'due_date','')::date,paid_at=case when p_data->>'status'='PAGO' then nullif(p_data->>'paid_at','')::date end,amount=(p_data->>'amount')::numeric,status=p_data->>'status',notes=p_data->>'notes',paid_by_doctor_entity_link_id=case when p_data->>'status'='PAGO' then link end where id=sid;
 else
 insert into public.company_expenses(id,billing_entity_id,description,category,supplier,competence_date,due_date,paid_at,amount,status,notes,paid_by_doctor_entity_link_id)
 values(sid,entity,trim(p_data->>'description'),coalesce(p_data->>'category',''),coalesce(p_data->>'supplier',''),(p_data->>'competence_date')::date,nullif(p_data->>'due_date','')::date,case when p_data->>'status'='PAGO' then nullif(p_data->>'paid_at','')::date end,(p_data->>'amount')::numeric,p_data->>'status',p_data->>'notes',case when p_data->>'status'='PAGO' then link end)
;
 end if;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return sid;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_doctor_directory(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid text; old_row jsonb; result_row jsonb; old_agenda jsonb; new_agenda jsonb;
begin
 perform pg_advisory_xact_lock(194701,1);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Somente a gerência pode alterar o cadastro central'; end if;
 sid:=coalesce(nullif(p_data->>'id',''),gen_random_uuid()::text);
 perform public.financial_operation(p_actor,'doctor',sid);
 if p_kind='doctor' then
  select to_jsonb(d) into old_row from public.doctors d where id=sid;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Médico alterado. Atualize a página'; end if;
  if coalesce(length(trim(p_data->>'name')),0)<2 then raise exception 'Informe o nome'; end if;
  if not coalesce(public.valid_medical_specialty(p_data->>'specialty'),false) then raise exception 'Selecione uma especialidade da lista';end if;
  if nullif(trim(p_data->>'crm'),'') is not null and exists(select 1 from public.doctors where id<>sid and lower(trim(crm))=lower(trim(p_data->>'crm'))) then raise exception 'CRM já cadastrado. Use o médico existente'; end if;
  insert into public.doctors(id,name,crm,specialty,category,active,scheduling_enabled,billing_enabled,invoice_enabled,updated_at,updated_by)
   values(sid,trim(p_data->>'name'),trim(coalesce(p_data->>'crm','')),trim(coalesce(p_data->>'specialty','')),case when public.is_anesthesiologist(p_data->>'specialty') then 'anesthetist' else 'doctor' end,coalesce((p_data->>'active')::boolean,true),coalesce((p_data->>'scheduling_enabled')::boolean,(old_row->>'scheduling_enabled')::boolean,true),coalesce((p_data->>'billing_enabled')::boolean,(old_row->>'billing_enabled')::boolean,true),coalesce((p_data->>'invoice_enabled')::boolean,(old_row->>'invoice_enabled')::boolean,true),clock_timestamp(),p_actor)
   on conflict(id) do update set name=excluded.name,crm=excluded.crm,specialty=excluded.specialty,category=excluded.category,active=excluded.active,scheduling_enabled=excluded.scheduling_enabled,billing_enabled=excluded.billing_enabled,invoice_enabled=excluded.invoice_enabled,updated_at=excluded.updated_at,updated_by=p_actor returning to_jsonb(doctors.*) into result_row;
 elsif p_kind='agenda' then
  if not exists(select 1 from public.doctors where id=sid and scheduling_enabled) then raise exception 'Agendamento não habilitado para o médico';end if;
  if not exists(select 1 from public.doctors where id=sid) then raise exception 'Médico não cadastrado'; end if;
  select to_jsonb(a) into old_row from public.doctor_agendas a where doctor_id=sid;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Agenda alterada. Atualize a página'; end if;
  if coalesce(p_data->>'workStart','')!~'^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$' or coalesce(p_data->>'workEnd','')!~'^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$' or p_data->>'workStart'>=p_data->>'workEnd' then raise exception 'Horário da agenda inválido'; end if;
  insert into public.doctor_agendas(doctor_id,active,settings,updated_at,updated_by) values(sid,coalesce((p_data->>'active')::boolean,true),jsonb_build_object('workStart',p_data->>'workStart','workEnd',p_data->>'workEnd'),clock_timestamp(),p_actor)
  on conflict(doctor_id) do update set active=excluded.active,settings=excluded.settings,updated_at=excluded.updated_at,updated_by=p_actor returning to_jsonb(doctor_agendas.*) into result_row;
 else raise exception 'Operação inválida'; end if;

 -- Provision only when first configured or when the scheduling service is enabled again.
 -- Editing a doctor must not override an explicitly paused agenda or custom hours.
 if p_kind='doctor' and (result_row->>'scheduling_enabled')::boolean then
  select to_jsonb(a) into old_agenda from public.doctor_agendas a where a.doctor_id=sid;
  if old_agenda is null or not coalesce((old_row->>'scheduling_enabled')::boolean,false) then
   insert into public.doctor_agendas(doctor_id,active,settings,updated_at,updated_by)
    values(sid,true,jsonb_build_object('workStart','07:00','workEnd','19:00'),clock_timestamp(),p_actor)
    on conflict(doctor_id) do update set active=true,updated_at=clock_timestamp(),updated_by=p_actor
    returning to_jsonb(doctor_agendas.*) into new_agenda;
   insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data) values(p_actor,'agenda',sid,old_agenda,new_agenda);
  end if;
 end if;
 insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data) values(p_actor,p_kind,sid,old_row,result_row);
 update public.app_state set payload=payload,updated_at=greatest(clock_timestamp(),updated_at+interval '1 millisecond') where id=1;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return sid;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_doctor_with_access(p_actor bigint, p_kind text, p_data jsonb, p_access jsonb DEFAULT NULL::jsonb, p_credentials jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare did text; account_id bigint; access_data jsonb;
begin
 did:=public.save_doctor_directory(p_actor,p_kind,p_data);
 if p_access is not null then
  if p_kind<>'doctor' then raise exception 'Acesso pertence ao médico, não à agenda'; end if;
  select id into account_id from public.users where doctor_id=did;
  if (p_access->>'id')::bigint is distinct from account_id then raise exception 'Acesso alterado por outro usuário. Atualize'; end if;
  access_data:=p_access||jsonb_build_object('id',account_id,'doctor_id',did,'role','doctor','name',p_data->>'name');
  perform public.save_user_access(p_actor,access_data,p_credentials);
 end if;
 return did;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_manual_attendance(p_actor bigint, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid text:=coalesce(nullif(p_data->>'id',''),gen_random_uuid()::text);old_row public.attendances%rowtype;d public.doctors%rowtype;entity uuid:=(p_data->>'billing_entity_id')::uuid;method text:=p_data->>'billing_method';patient text:=p_data->>'patient_id';
begin
 perform pg_advisory_xact_lock(194701,1);perform pg_advisory_xact_lock(194701,2);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Acesso restrito à gerência';end if;
 perform public.financial_operation(p_actor,'attendance',sid);
 select * into old_row from public.attendances where id=sid;
 if old_row.status='cancelled' then raise exception 'Atendimento cancelado não pode ser editado';end if;
 if old_row.id is not null and (old_row.origin='AGENDA' or old_row.updated_at is distinct from (p_data->>'updated_at')::timestamptz) then raise exception 'Edite a origem correta ou atualize o atendimento';end if;
 if exists(select 1 from public.billing_records b join public.invoice_billing_records ib on ib.billing_record_id=b.id where b.attendance_id=sid and ib.is_active) then raise exception 'Atendimento vinculado a NF não pode ter sua identificação alterada';end if;
 select * into d from public.doctors where id=p_data->>'doctor_id';
 if d.id is null or not d.active or not(d.billing_enabled or d.invoice_enabled) then raise exception 'Médico sem serviço financeiro/fiscal habilitado';end if;
 if method='CONVENIO' and not exists(select 1 from public.app_state s cross join lateral jsonb_array_elements(s.payload->'patients') p where public.billing_payer_key(p->>'insurance')=public.billing_payer_key(p_data->>'insurance') and nullif(p->>'insurance','') is not null) and not exists(select 1 from public.attendances where public.billing_payer_key(insurance)=public.billing_payer_key(p_data->>'insurance') and insurance<>'') then raise exception 'Selecione um convênio existente';end if;
 if nullif(patient,'') is null and length(trim(coalesce(p_data->>'patient_name','')))>=2 then
  if exists(select 1 from public.app_state s cross join lateral jsonb_array_elements(s.payload->'patients') p where s.id=1 and lower(trim(p->>'name'))=lower(trim(p_data->>'patient_name')) and p->>'doctorId'=d.id) then raise exception 'Paciente já cadastrado para este médico. Selecione o cadastro existente';end if;
  patient:=gen_random_uuid()::text;
  update public.app_state set payload=jsonb_set(payload,'{patients}',coalesce(payload->'patients','[]')||jsonb_build_array(jsonb_build_object('id',patient,'name',trim(p_data->>'patient_name'),'doctorId',d.id,'insurance',coalesce(p_data->>'insurance','')))),updated_at=greatest(clock_timestamp(),updated_at+interval '1 millisecond') where id=1;
 end if;
 if not exists(select 1 from public.app_state s cross join lateral jsonb_array_elements(s.payload->'patients') p where s.id=1 and p->>'id'=patient) then raise exception 'Selecione um paciente existente';end if;
 if method is null or method not in ('PARTICULAR','CONVENIO') or nullif(trim(p_data->>'procedure'),'') is null or nullif(p_data->>'date','') is null then raise exception 'Preencha procedimento, data e forma de cobrança';end if;
 if not exists(select 1 from public.billing_doctor_entities l join public.billing_entities e on e.id=l.billing_entity_id where l.doctor_id=d.id and l.billing_entity_id=entity and l.active and e.active) and old_row.billing_entity_id is distinct from entity then raise exception 'Entidade não vinculada ao médico';end if;
 if entity is null then raise exception 'Selecione a entidade recebedora';end if;
 if exists(select 1 from public.billing_records where attendance_id=sid and payment_status='PAGO') then raise exception 'Atendimento pago: preserve sua identificação financeira';end if;
 insert into public.attendances(id,origin,patient_id,doctor_id,date,procedure,insurance,billing_method,status,billing_entity_id)
 values(sid,case when d.billing_enabled then 'FATURAMENTO_MANUAL' else 'FISCAL_MANUAL' end,patient,d.id,(p_data->>'date')::date,trim(p_data->>'procedure'),coalesce(trim(p_data->>'insurance'),''),method,'realized',entity)
 on conflict(id) do update set patient_id=excluded.patient_id,doctor_id=excluded.doctor_id,date=excluded.date,procedure=excluded.procedure,insurance=excluded.insurance,billing_method=excluded.billing_method,billing_entity_id=excluded.billing_entity_id;
 insert into public.billing_records(attendance_id,appointment_id,billing_entity_id,billing_method,payment_status,settlement_mode)
 values(sid,null,entity,method,'PENDENTE',case when method='PARTICULAR' or not d.invoice_enabled then 'DIRECT' else 'INVOICE' end)
 on conflict(attendance_id) do update set billing_entity_id=excluded.billing_entity_id,billing_method=excluded.billing_method,settlement_mode=excluded.settlement_mode,received_amount=null,paid_at=null,invoice_number=null;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return sid;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_private_invoice(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.invoice_requests%rowtype;i public.invoices%rowtype;sid uuid;ids jsonb:=coalesce(p_data->'attendance_ids',p_data->'appointment_ids');
begin
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Somente a gerência pode registrar NF';end if;
 select * into r from public.invoice_requests where id=nullif(p_data->>'request_id','')::uuid or (invoice_id=nullif(p_data->>'id','')::uuid and status='ISSUED') for update;
 if r.id is null or r.status='CANCELLED' then raise exception 'Selecione uma solicitação fiscal pendente';end if;
 if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)<>1 or ids->>0 is distinct from r.attendance_id then raise exception 'NF Particular exige exatamente um atendimento, fixado pela solicitação';end if;
 if p_data->>'billing_entity_id' is distinct from r.billing_entity_id::text then raise exception 'Empresa diferente da solicitação fiscal';end if;
 if nullif(trim(p_data->>'invoice_number'),'') is null or nullif(p_data->>'issue_date','') is null then raise exception 'Informe número da NF e data de emissão';end if;
 if r.status='ISSUED' then
  select * into i from public.invoices where id=r.invoice_id;
  if nullif(p_data->>'id','') is null then
   if i.invoice_number=trim(p_data->>'invoice_number') and i.issue_date=(p_data->>'issue_date')::date and i.total_amount is not distinct from nullif(p_data->>'total_amount','')::numeric and i.net_amount is not distinct from nullif(p_data->>'net_amount','')::numeric then return i.id;end if;raise exception 'Solicitação já emitida. Atualize a lista';end if;
  if i.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'NF alterada. Atualize a página';end if;
  update public.invoices set invoice_number=trim(p_data->>'invoice_number'),issue_date=(p_data->>'issue_date')::date,total_amount=nullif(p_data->>'total_amount','')::numeric,net_amount=nullif(p_data->>'net_amount','')::numeric,notes=nullif(trim(p_data->>'notes'),'') where id=i.id;return i.id;
 end if;
 if not exists(select 1 from public.billing_records where id=r.billing_record_id and billing_method='PARTICULAR' and payment_status='PAGO' and received_amount=r.received_amount_snapshot and paid_at=r.paid_at_snapshot and billing_entity_id=r.billing_entity_id) then raise exception 'Pagamento incompatível com a solicitação';end if;
 insert into public.invoices(billing_entity_id,invoice_number,issue_date,total_amount,net_amount,paid_at,payer,notes,recipient_type,recipient_kind,recipient_name,recipient_tax_id,recipient_address,patient_id,patient_name_snapshot)
 values(r.billing_entity_id,trim(p_data->>'invoice_number'),(p_data->>'issue_date')::date,nullif(p_data->>'total_amount','')::numeric,nullif(p_data->>'net_amount','')::numeric,r.paid_at_snapshot,r.taker_name,nullif(trim(p_data->>'notes'),''),'PARTICULAR',r.taker_kind,r.taker_name,r.taker_tax_id,r.taker_address,r.patient_id,r.patient_name_snapshot) returning id into sid;
 insert into public.invoice_billing_records(invoice_id,billing_record_id,received_amount) values(sid,r.billing_record_id,r.received_amount_snapshot);
 update public.invoice_requests set status='ISSUED',invoice_id=sid where id=r.id;return sid;
end;$function$;

CREATE OR REPLACE FUNCTION public.save_professional_charge(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  prior public.billing_records%rowtype;
  saved public.billing_records%rowtype;
  old_request public.invoice_requests%rowtype;
  attendance public.attendances%rowtype;
  patient jsonb;
  entity public.billing_entities%rowtype;
  professional public.doctors%rowtype;
  fiscal jsonb := p_data->'fiscal';
  recipient_kind text;
  recipient_name text;
  recipient_cpf text;
  charge_id uuid;
begin
  -- Enquanto a composição de pagamentos DIRETOS de convênio não estiver
  -- representada no controle fiscal, não registrar pagamento inconsistente.
  if p_data->>'billing_method'='CONVENIO' and p_data->>'payment_status'='PAGO'
     and p_data->>'submission_channel_code'='DIRETO'
  then
    raise exception 'Pagamento direto de convênio depende da configuração fiscal do repasse';
  end if;

  -- O núcleo faz o bloqueio da cobrança, verifica os vínculos do profissional,
  -- atualiza a composição de pagamento e abre o contexto auditável.
  if nullif(p_data->>'id','') is not null then
    select * into prior from public.billing_records
    where id=(p_data->>'id')::uuid for update;
    if prior.id is not null then
      select * into old_request from public.invoice_requests
      where billing_record_id=prior.id and status in ('PENDING','ISSUED')
      for update;
    end if;
  end if;

  if coalesce((p_data->>'no_invoice')::boolean,false) and old_request.id is not null then
    raise exception 'Existe solicitação fiscal. Sem NF não pode substituir uma solicitação existente';
  end if;
  if old_request.status='ISSUED' then
    if p_data->>'billing_method' is distinct from prior.billing_method
       or p_data->>'professional_id' is distinct from prior.professional_id
       or p_data->>'payment_status' is distinct from prior.payment_status
       or nullif(p_data->>'billing_entity_id','')::uuid is distinct from prior.billing_entity_id
       or nullif(p_data->>'received_amount','')::numeric is distinct from prior.received_amount
       or nullif(p_data->>'paid_at','')::date is distinct from prior.paid_at
    then
      raise exception 'NF particular já emitida. Corrija primeiro a nota fiscal pelo fluxo próprio';
    end if;
  end if;

  if old_request.status='PENDING' and p_data->>'payment_status'='PAGO' then
    if p_data->>'billing_method'<>'PARTICULAR'
       or p_data->>'professional_id' is distinct from prior.professional_id
       or nullif(p_data->>'received_amount','')::numeric is distinct from old_request.received_amount_snapshot
       or nullif(p_data->>'paid_at','')::date is distinct from old_request.paid_at_snapshot
       or nullif(p_data->>'billing_entity_id','')::uuid is distinct from old_request.billing_entity_id
    then
      raise exception 'Pagamento possui solicitação fiscal. Reverta o pagamento para cancelá-la antes de alterar valores ou recebedora';
    end if;
  end if;

  charge_id:=public.save_professional_charge_core(p_actor,p_data);
  select * into saved from public.billing_records where id=charge_id;

  if old_request.status='PENDING' and (saved.payment_status<>'PAGO' or saved.billing_method<>'PARTICULAR') then
    update public.invoice_requests set status='CANCELLED',updated_at=clock_timestamp(),updated_by=p_actor
    where id=old_request.id;
  end if;

  if saved.billing_method='PARTICULAR' and saved.payment_status='PAGO'
    and coalesce((p_data->>'no_invoice')::boolean,false) then
    if nullif(trim(coalesce(saved.invoice_number,'')),'') is not null or
      exists(select 1 from public.invoice_requests
       where billing_record_id=saved.id and status in ('PENDING','ISSUED')) then
      raise exception 'NF ou solicitação existente: Sem NF não é permitido';
    end if;
    update public.billing_records set no_invoice=true where id=saved.id;
  else
    update public.billing_records set no_invoice=false where id=saved.id and no_invoice;
  end if;
  if saved.billing_method='PARTICULAR' and saved.payment_status='PAGO'
     and not coalesce((p_data->>'no_invoice')::boolean,false)
     and nullif(trim(coalesce(saved.invoice_number,'')),'') is null
     and not exists(select 1 from public.invoice_requests where billing_record_id=saved.id and status in ('PENDING','ISSUED'))
  then
    if jsonb_typeof(fiscal) is distinct from 'object' then
      raise exception 'Confirme o tomador da NF e as formas de pagamento particular';
    end if;
    recipient_kind:=fiscal->>'taker_kind';
    recipient_name:=nullif(trim(fiscal->>'taker_name'),'');
    recipient_cpf:=regexp_replace(coalesce(fiscal->>'taker_tax_id',''),'[^0-9]','','g');
    if recipient_kind not in ('PATIENT','OTHER') or recipient_name is null
       or length(recipient_name)>200 or length(recipient_cpf)<>11 or not public.valid_cpf(recipient_cpf)
    then raise exception 'Informe tomador e CPF válidos para solicitação fiscal';end if;

    select * into attendance from public.attendances where id=saved.attendance_id;
    select value into patient from public.app_state s
      cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb))
      where s.id=1 and value->>'id'=attendance.patient_id limit 1;
    if attendance.patient_id is null or patient is null then
      raise exception 'Paciente precisa estar cadastrado para gerar solicitação fiscal';
    end if;
    if recipient_kind='PATIENT' and
       (recipient_name is distinct from patient->>'name' or
       (nullif(regexp_replace(coalesce(patient->>'cpf',''),'[^0-9]','','g'),'') is not null
        and recipient_cpf is distinct from regexp_replace(patient->>'cpf','[^0-9]','','g')))
    then raise exception 'Tomador paciente diferente do cadastro';end if;

    select * into entity from public.billing_entities where id=saved.billing_entity_id;
    select * into professional from public.doctors where id=saved.professional_id;

    insert into public.invoice_requests(
      attendance_id,billing_record_id,billing_entity_id,status,
      taker_kind,taker_name,taker_tax_id,taker_address,notes,
      received_amount_snapshot,paid_at_snapshot,patient_id,patient_name_snapshot,
      doctor_id,doctor_name_snapshot,attendance_date_snapshot,procedure_snapshot,
      entity_name_snapshot,entity_tax_id_snapshot,created_by,updated_by)
    values(
      attendance.id,saved.id,saved.billing_entity_id,'PENDING',
      recipient_kind,recipient_name,recipient_cpf,nullif(trim(fiscal->>'taker_address'),''),
      nullif(trim(fiscal->>'notes'),''),
      saved.received_amount,saved.paid_at,attendance.patient_id,
      patient->>'name',saved.professional_id,professional.name,attendance.date,
      attendance.procedure,coalesce(entity.trade_name,entity.name),entity.tax_id,
      p_actor,p_actor);
  end if;
  return charge_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_professional_charge_core(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  role_name text;
  target_id uuid;
  current_row public.billing_records%rowtype;
  attendance public.attendances%rowtype;
  entity_id uuid;
  payer_id uuid;
  payer_name text;
  method text;
  status_value text;
  settlement text;
  channel text;
  modality text;
  paid_on date;
  received numeric;
begin
  perform pg_advisory_xact_lock(194701,3);
  select role into role_name from public.users where id=p_actor;
  if role_name is null or role_name not in ('general_manager','secretary') then raise exception 'Acesso negado'; end if;
  if coalesce(nullif(trim(p_data->>'attendance_id'),''),'')='' or coalesce(nullif(trim(p_data->>'professional_id'),''),'')='' then raise exception 'Informe atendimento e profissional responsável'; end if;
  select * into attendance from public.attendances where id=p_data->>'attendance_id' for update;
  if not found or attendance.status='cancelled' then raise exception 'Atendimento cancelado ou inexistente'; end if;
  if not (
    attendance.doctor_id=p_data->>'professional_id'
    or exists (
      select 1
      from public.app_state s
      cross join lateral jsonb_array_elements(coalesce(s.payload->'appointments','[]')) clinical
      where s.id=1
        and clinical->>'id'=attendance.appointment_id
        and p_data->>'professional_id' in (clinical->>'doctorId',clinical->>'anesthetistId')
    )
  ) then raise exception 'Profissional não participa deste atendimento'; end if;
  if role_name='secretary' and not exists (
    select 1 from public.agenda_access g
    where g.user_id=p_actor and g.professional_id=p_data->>'professional_id'
  ) then raise exception 'Agenda sem permissão para este profissional'; end if;
  if not exists(select 1 from public.doctors where id=p_data->>'professional_id' and active and billing_enabled) then raise exception 'Profissional inexistente ou sem faturamento habilitado'; end if;
  entity_id:=nullif(p_data->>'billing_entity_id','')::uuid;
  if entity_id is null or not exists(select 1 from public.billing_entities where id=entity_id and active) then raise exception 'Entidade recebedora inativa ou inexistente'; end if;
  if not exists(select 1 from public.billing_doctor_entities where doctor_id=p_data->>'professional_id' and billing_entity_id=entity_id and active) then raise exception 'Selecione uma entidade vinculada ao profissional'; end if;
  method:=p_data->>'billing_method'; status_value:=coalesce(p_data->>'payment_status','PENDENTE');
  if method not in ('PARTICULAR','CONVENIO') or status_value not in ('PENDENTE','PAGO') then raise exception 'Forma de cobrança ou status inválido'; end if;
  modality:=coalesce(nullif(p_data->>'commercial_modality_code',''),case when method='PARTICULAR' then 'PARTICULAR' else 'LEGADO' end);
  channel:=coalesce(nullif(p_data->>'submission_channel_code',''),case when method='PARTICULAR' then 'DIRETO' else 'LEGADO' end);
  if not exists(select 1 from public.billing_commercial_modalities where code=modality and active) or not exists(select 1 from public.billing_submission_channels where code=channel and active) then raise exception 'Modalidade ou canal de faturamento inválido'; end if;
  payer_id:=nullif(p_data->>'effective_payer_id','')::uuid;
  if payer_id is not null then select name into payer_name from public.billing_counterparties where id=payer_id and active; if payer_name is null then raise exception 'Pagador ou intermediário inativo ou inexistente'; end if; end if;
  target_id:=nullif(p_data->>'id','')::uuid;
  if target_id is not null then
    select * into current_row from public.billing_records where id=target_id for update;
    if not found or current_row.attendance_id<>attendance.id then raise exception 'Cobrança não encontrada'; end if;
    if current_row.updated_at is distinct from nullif(p_data->>'updated_at','')::timestamptz then raise exception 'Cobrança alterada. Atualize a página'; end if;
    if exists(select 1 from public.invoice_billing_records where billing_record_id=target_id and is_active)
       and (current_row.professional_id is distinct from p_data->>'professional_id' or current_row.billing_entity_id is distinct from entity_id or current_row.billing_method is distinct from method) then
      raise exception 'Edite os dados fiscais na NF/lote vinculada';
    end if;
  else
    select * into current_row from public.billing_records where attendance_id=attendance.id and professional_id=p_data->>'professional_id' for update;
    if found then raise exception 'Já existe uma cobrança para este profissional neste atendimento'; end if;
    target_id:=gen_random_uuid();
  end if;
  perform public.financial_operation(p_actor,'professional_charge',target_id::text);
  settlement:=case when method='PARTICULAR' or channel='DIRETO' then 'DIRECT' else 'INVOICE' end;
  if settlement='INVOICE' and status_value='PAGO' then raise exception 'Registre o pagamento do convênio na NF/lote'; end if;
  paid_on:=nullif(p_data->>'paid_at','')::date; received:=nullif(p_data->>'received_amount','')::numeric;
  if status_value='PAGO' and (paid_on is null or received is null or received<0) then raise exception 'Pagamento direto exige valor e data'; end if;
  perform set_config('rn.record',target_id::text,true);
  insert into public.billing_records(id,attendance_id,appointment_id,settlement_mode,billing_entity_id,billing_method,payment_status,invoice_number,received_amount,paid_at,notes,professional_id,professional_role,patient_insurance_snapshot,commercial_modality_code,submission_channel_code,effective_payer_id,effective_payer_role,effective_payer_name_snapshot,billing_entity_name_snapshot,service_group_key,updated_at,updated_by)
  values(target_id,attendance.id,attendance.appointment_id,settlement,entity_id,method,status_value,
    case when method='PARTICULAR' then nullif(trim(p_data->>'invoice_number'),'') end,
    case when settlement='DIRECT' then received end,case when settlement='DIRECT' then paid_on end,
    nullif(trim(p_data->>'notes'),''),p_data->>'professional_id',coalesce(nullif(p_data->>'professional_role',''),'OTHER'),coalesce(p_data->>'patient_insurance_snapshot',attendance.insurance,''),modality,channel,payer_id,
    case when payer_id is null then null else coalesce(nullif(p_data->>'effective_payer_role',''),'PAYER') end,
    coalesce(payer_name,nullif(trim(p_data->>'effective_payer_name_snapshot'),'')),
    (select coalesce(trade_name,name) from public.billing_entities where id=entity_id),nullif(trim(p_data->>'service_group_key'),''),clock_timestamp(),p_actor)
  on conflict(id) do update set settlement_mode=excluded.settlement_mode,billing_entity_id=excluded.billing_entity_id,billing_method=excluded.billing_method,payment_status=excluded.payment_status,invoice_number=excluded.invoice_number,received_amount=excluded.received_amount,paid_at=excluded.paid_at,notes=excluded.notes,professional_id=excluded.professional_id,professional_role=excluded.professional_role,patient_insurance_snapshot=excluded.patient_insurance_snapshot,commercial_modality_code=excluded.commercial_modality_code,submission_channel_code=excluded.submission_channel_code,effective_payer_id=excluded.effective_payer_id,effective_payer_role=excluded.effective_payer_role,effective_payer_name_snapshot=excluded.effective_payer_name_snapshot,billing_entity_name_snapshot=excluded.billing_entity_name_snapshot,service_group_key=excluded.service_group_key,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
  if settlement='DIRECT' and status_value='PAGO' then
    if jsonb_typeof(p_data->'payment_parts') is distinct from 'array' then raise exception 'Informe as formas de pagamento'; end if;
    perform public.write_payment_parts(target_id,null,p_data->'payment_parts');
    update public.billing_records set payment_composition_verified=true where id=target_id;
  elsif status_value='PENDENTE' then
    delete from public.payment_parts where billing_record_id=target_id;
    update public.billing_records set payment_composition_verified=false where id=target_id;
  end if;
  return target_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_professional_invoice(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  role_name text;
  previous_invoice public.invoices%rowtype;
  target_invoice_id uuid := coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());
  entity_id uuid := nullif(p_data->>'billing_entity_id','')::uuid;
  payer_value text := public.billing_payer_key(p_data->>'payer');
  record_id uuid;
  charge public.billing_records%rowtype;
  total numeric:=0;
  amount numeric;
begin
  perform pg_advisory_xact_lock(194701,4);
  select role into role_name from public.users where id=p_actor;
  if role_name is distinct from 'general_manager' then raise exception 'Somente a gerência pode gerenciar lotes'; end if;
  perform public.financial_operation(p_actor,'professional_invoice',target_invoice_id::text);
  if entity_id is null or not exists(select 1 from public.billing_entities where id=entity_id and active) then raise exception 'Entidade recebedora inativa ou inexistente'; end if;
  if payer_value='' or nullif(trim(p_data->>'invoice_number'),'') is null or nullif(p_data->>'issue_date','') is null then raise exception 'Preencha número, pagador e emissão'; end if;
  if jsonb_typeof(p_data->'record_ids') is distinct from 'array' or jsonb_array_length(p_data->'record_ids')=0 or jsonb_typeof(p_data->'item_amounts') is distinct from 'object' then raise exception 'Selecione as cobranças e informe cada valor'; end if;
  select * into previous_invoice from public.invoices where id=target_invoice_id for update;
  if previous_invoice.id is not null then
    if previous_invoice.status<>'ACTIVE' or previous_invoice.voided_at is not null then raise exception 'Documento histórico não pode ser editado'; end if;
    if previous_invoice.recipient_type<>'CONVENIO' then raise exception 'Documento não é NF de convênio'; end if;
    if previous_invoice.updated_at is distinct from nullif(p_data->>'updated_at','')::timestamptz then raise exception 'NF alterada. Atualize a página'; end if;
    if previous_invoice.paid_at is not null then raise exception 'NF já paga. Utilize o fluxo fiscal de correção ou substituição'; end if;
  end if;
  for record_id in select distinct value::uuid from jsonb_array_elements_text(p_data->'record_ids') loop
    select * into charge from public.billing_records where id=record_id for update;
    if not found or charge.billing_method<>'CONVENIO' or charge.settlement_mode='DIRECT' then raise exception 'Cobrança não elegível para NF de convênio'; end if;
    if charge.billing_entity_id<>entity_id then raise exception 'Todas as cobranças da NF devem usar a mesma entidade recebedora'; end if;
    if public.billing_payer_key(coalesce(charge.effective_payer_name_snapshot,charge.patient_insurance_snapshot,''))<>payer_value then raise exception 'Pagador efetivo diferente do lote'; end if;
    if exists(select 1 from public.invoice_billing_records ib where ib.billing_record_id=record_id and ib.invoice_id<>target_invoice_id and ib.is_active) then raise exception 'Cobrança já vinculada a outra NF'; end if;
    if not exists(select 1 from public.billing_doctor_entities where doctor_id=charge.professional_id and billing_entity_id=entity_id and active) then raise exception 'Profissional sem vínculo ativo com a entidade recebedora'; end if;
    amount:=nullif(p_data->'item_amounts'->>record_id::text,'')::numeric;
    if amount is null or amount<0 then raise exception 'Informe o valor de cada cobrança'; end if;
    total:=total+round(amount,2);
  end loop;
  if total+coalesce(nullif(p_data->>'closing_adjustment','')::numeric,0)<>round((p_data->>'net_amount')::numeric,2) then raise exception 'A soma dos itens e ajuste deve ser igual ao valor líquido'; end if;
  insert into public.invoices(id,billing_entity_id,invoice_number,payer,issue_date,total_amount,net_amount,paid_at,notes,recipient_type,closing_adjustment,closing_adjustment_reason,allocation_verified,payment_composition_verified,updated_at,updated_by)
  values(target_invoice_id,entity_id,trim(p_data->>'invoice_number'),payer_value,(p_data->>'issue_date')::date,nullif(p_data->>'total_amount','')::numeric,(p_data->>'net_amount')::numeric,nullif(p_data->>'paid_at','')::date,nullif(trim(p_data->>'notes'),''),'CONVENIO',coalesce(nullif(p_data->>'closing_adjustment','')::numeric,0),nullif(trim(p_data->>'closing_adjustment_reason'),''),true,false,clock_timestamp(),p_actor)
  on conflict(id) do update set billing_entity_id=excluded.billing_entity_id,invoice_number=excluded.invoice_number,payer=excluded.payer,issue_date=excluded.issue_date,total_amount=excluded.total_amount,net_amount=excluded.net_amount,paid_at=excluded.paid_at,notes=excluded.notes,closing_adjustment=excluded.closing_adjustment,closing_adjustment_reason=excluded.closing_adjustment_reason,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
  update public.billing_records set payment_status='PENDENTE',updated_at=clock_timestamp(),updated_by=p_actor where id in(select ib.billing_record_id from public.invoice_billing_records ib where ib.invoice_id=target_invoice_id);
  delete from public.invoice_billing_records ib where ib.invoice_id=target_invoice_id and not (ib.billing_record_id in(select value::uuid from jsonb_array_elements_text(p_data->'record_ids')));
  for record_id in select distinct value::uuid from jsonb_array_elements_text(p_data->'record_ids') loop
    amount:=(p_data->'item_amounts'->>record_id::text)::numeric;
    insert into public.invoice_billing_records(invoice_id,billing_record_id,received_amount,is_active)
      values(target_invoice_id,record_id,round(amount,2),true)
      on conflict(invoice_id,billing_record_id) do update set received_amount=excluded.received_amount,is_active=true;
  end loop;
  update public.billing_records set payment_status=case when nullif(p_data->>'paid_at','') is null then 'PENDENTE' else 'PAGO' end,received_amount=null,paid_at=null,invoice_number=null,updated_at=clock_timestamp(),updated_by=p_actor where id in(select value::uuid from jsonb_array_elements_text(p_data->'record_ids'));
  if nullif(p_data->>'paid_at','') is not null then
    if jsonb_typeof(p_data->'payment_parts') is distinct from 'array' then raise exception 'Informe as formas de pagamento'; end if;
    perform public.write_payment_parts(null,target_invoice_id,p_data->'payment_parts');
    update public.invoices set payment_composition_verified=true where id=target_invoice_id;
  else
    delete from public.payment_parts where invoice_id=target_invoice_id;
  end if;
  return target_invoice_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_user_access(p_actor bigint, p_data jsonb, p_credentials jsonb DEFAULT NULL::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare uid bigint:=nullif(p_data->>'id','')::bigint; old_account public.users%rowtype; did text:=nullif(p_data->>'doctor_id',''); email_value text:=lower(trim(p_data->>'email')); role_value text:=p_data->>'role'; grant_id text;
begin
 perform pg_advisory_xact_lock(194701,1);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Acesso restrito à gerência'; end if;
 if role_value not in ('general_manager','secretary','doctor') or role_value is null or email_value is null or email_value !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or length(email_value)>254 then raise exception 'Dados de acesso inválidos'; end if;
 if role_value='doctor' and (did is null or not exists(select 1 from public.doctors where id=did)) then raise exception 'Selecione um médico existente'; end if;
 if role_value<>'doctor' then did:=null; end if;
 if uid=p_actor and role_value<>'general_manager' then raise exception 'Outro gerente deve alterar seu nível de acesso'; end if;
 if uid is not null then
  select * into old_account from public.users where id=uid for update;
  if not found then raise exception 'Usuário inexistente'; end if;
  if p_data ? 'updated_at' and old_account.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Acesso alterado por outro usuário. Atualize'; end if;
 end if;
 if exists(select 1 from public.users where lower(email)=email_value and id is distinct from uid) then raise exception 'Já existe uma conta com este e-mail'; end if;
 if did is not null and exists(select 1 from public.users where doctor_id=did and id is distinct from uid) then raise exception 'Este médico já possui um acesso'; end if;
 if uid is null and p_credentials is null then raise exception 'Informe uma senha inicial'; end if;
 if p_credentials is not null and (coalesce(p_credentials->>'hash','') !~ '^pbkdf2-sha256\$600000\$[A-Za-z0-9+/=]+$' or length(coalesce(p_credentials->>'salt',''))<20) then raise exception 'Credencial inválida'; end if;
 if p_data ? 'agendaIds' then
  if jsonb_typeof(p_data->'agendaIds') is distinct from 'array' then raise exception 'Agendas inválidas'; end if;
  for grant_id in select jsonb_array_elements_text(p_data->'agendaIds') loop
   if not exists(select 1 from public.doctors where id=grant_id) then raise exception 'Agenda inexistente'; end if;
  end loop;
 end if;
 if uid is null then
  insert into public.users(email,name,role,doctor_id,password_hash,password_salt) values(email_value,coalesce(p_data->>'name',''),role_value,did,p_credentials->>'hash',p_credentials->>'salt') returning id into uid;
 else
  update public.users set email=email_value,name=coalesce(p_data->>'name',''),role=role_value,doctor_id=did,password_hash=coalesce(p_credentials->>'hash',password_hash),password_salt=coalesce(p_credentials->>'salt',password_salt),updated_at=clock_timestamp() where id=uid;
 end if;
 delete from public.sessions where user_id=uid;
 if p_data ? 'agendaIds' or role_value='general_manager' then
  delete from public.agenda_access where user_id=uid;
  if role_value<>'general_manager' then
   insert into public.agenda_access(user_id,professional_id) select uid,value from (select distinct jsonb_array_elements_text(p_data->'agendaIds') value) x;
  end if;
 end if;
 if did is not null and not exists(select 1 from public.agenda_access where user_id=uid and professional_id=did) then insert into public.agenda_access(user_id,professional_id) values(uid,did); end if;
 insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data) values(p_actor,'user_access',uid::text,case when old_account.id is not null then jsonb_build_object('email',old_account.email,'role',old_account.role,'doctor_id',old_account.doctor_id) end,jsonb_build_object('email',email_value,'role',role_value,'doctor_id',did,'password_changed',p_credentials is not null,'agendaIds',(select coalesce(jsonb_agg(professional_id),'[]') from public.agenda_access where user_id=uid)));
 return uid;
end;$function$;

CREATE OR REPLACE FUNCTION public.snapshot_appointment_insurance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare collection text;a jsonb;previous jsonb;result jsonb;insurance text;patient jsonb;
begin
 foreach collection in array array['appointments','cancelledAppointments'] loop
 result:='[]';
 for a in select value from jsonb_array_elements(coalesce(new.payload->collection,'[]')) loop
 previous:=null;
 if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]')||coalesce(old.payload->'cancelledAppointments','[]')) where value->>'id'=a->>'id' limit 1;end if;
 if a->>'insurance' is null then
  select t.insurance into insurance from public.attendances t where t.appointment_id=a->>'id';
  if insurance is null then
   if previous is not null then select value into patient from jsonb_array_elements(coalesce(old.payload->'patients','[]')) where value->>'id'=previous->>'patientId';
   else select value into patient from jsonb_array_elements(coalesce(new.payload->'patients','[]')) where value->>'id'=a->>'patientId';end if;
  end if;
  a:=a||jsonb_build_object('insurance',coalesce(previous->>'insurance',insurance,patient->>'insurance',''));
 end if;
 if public.appointment_billing_method(a)='CONVENIO' and nullif(trim(a->>'insurance'),'') is null and
 (previous is null or previous->>'insurance' is distinct from a->>'insurance' or public.appointment_billing_method(previous) is distinct from public.appointment_billing_method(a)) then raise exception 'Informe o convênio do atendimento';end if;
 result:=result||jsonb_build_array(a);
 end loop;
 new.payload:=jsonb_set(new.payload,array[collection],result);
 end loop;return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.stamp_patient_authorship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p jsonb;previous jsonb;result jsonb:='[]';actor bigint:=nullif(current_setting('rn.actor',true),'')::bigint;
begin
 for p in select value from jsonb_array_elements(coalesce(new.payload->'patients','[]')) loop
  previous:=null;
  if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'patients','[]')) where value->>'id'=p->>'id';end if;
  if previous is null or (previous-'created_by'-'created_at'-'updated_by'-'updated_at') is distinct from (p-'created_by'-'created_at'-'updated_by'-'updated_at') then
   if actor is null then raise exception 'Cadastro de paciente exige autoria';end if;
   p:=p||jsonb_build_object('created_by',case when previous is null then to_jsonb(actor) else previous->'created_by' end,'created_at',case when previous is null then to_jsonb(clock_timestamp()) else previous->'created_at' end,'updated_by',actor,'updated_at',clock_timestamp());
  else p:=(p-'created_by'-'created_at'-'updated_by'-'updated_at')||(select coalesce(jsonb_object_agg(key,value),'{}') from jsonb_each(previous) where key in('created_by','created_at','updated_by','updated_at'));
  end if;
  result:=result||jsonb_build_array(p);
 end loop;
 new.payload:=jsonb_set(new.payload,'{patients}',result);return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.submit_agenda_suggestion(p_request jsonb, p_notification jsonb, p_audit jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  request_id text := nullif(p_request->>'id','');
  requester bigint := nullif(p_request->>'requested_by','')::bigint;
  action_name text := p_request->>'action';
  appointment_key text := nullif(p_request->>'appointment_id','');
  existing_id text;
BEGIN
  IF request_id IS NULL OR requester IS NULL OR action_name NOT IN ('create','update','delete')
     OR appointment_key IS NULL OR p_notification->>'request_id' IS DISTINCT FROM request_id
     OR p_audit->'metadata'->>'requestId' IS DISTINCT FROM request_id THEN
    RAISE EXCEPTION 'Solicitação de agenda inválida';
  END IF;

  -- Também impede solicitações pendentes duplicadas em envios simultâneos.
  PERFORM pg_advisory_xact_lock(194701,3);
  SELECT id INTO existing_id
  FROM public.agenda_requests
  WHERE requested_by=requester AND action=action_name
    AND appointment_id IS NOT DISTINCT FROM appointment_key AND status='pending'
  ORDER BY created_at DESC LIMIT 1;
  IF existing_id IS NOT NULL THEN
    RETURN existing_id;
  END IF;

  INSERT INTO public.agenda_requests
    (id,professional_id,appointment_id,action,proposed_payload,previous_payload,requested_by,created_at)
  VALUES
    (request_id,p_request->>'professional_id',appointment_key,action_name,
     NULLIF(p_request->'proposed_payload','null'::jsonb),NULLIF(p_request->'previous_payload','null'::jsonb),requester,
     (p_request->>'created_at')::timestamptz);

  INSERT INTO public.notifications
    (id,user_id,type,request_id,message,created_at)
  VALUES
    (p_notification->>'id',requester,'request_sent',request_id,
     'Alteração de agenda enviada.',(p_request->>'created_at')::timestamptz);

  INSERT INTO public.audit_logs
    (id,actor_user_id,actor_name,actor_role,action,professional_id,appointment_id,
     patient_id,description,metadata,created_at)
  VALUES
    (p_audit->>'id',requester,p_audit->>'actor_name',p_audit->>'actor_role',
     'request_created',p_audit->>'professional_id',nullif(p_audit->>'appointment_id',''),
     nullif(p_audit->>'patient_id',''),p_audit->>'description',p_audit->'metadata',
     (p_request->>'created_at')::timestamptz);

  RETURN request_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_financial_attendances()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb;patient jsonb;owner text;t public.attendances%rowtype;previous jsonb;historical_insurance text;
begin
 for a in select value from jsonb_array_elements(coalesce(new.payload->'appointments','[]')||coalesce(new.payload->'cancelledAppointments','[]')) loop
  select * into t from public.attendances where appointment_id=a->>'id';
  if a->>'status'<>'realized' and t.id is null then continue;end if;
  select value into patient from jsonb_array_elements(coalesce(new.payload->'patients','[]')) where value->>'id'=a->>'patientId';
  owner:=coalesce(t.doctor_id,nullif(a->>'doctorId',''),a->>'anesthetistId');
  previous:=null;
  if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]')||coalesce(old.payload->'cancelledAppointments','[]')) where value->>'id'=a->>'id' limit 1;end if;
  historical_insurance:=coalesce(a->>'insurance',t.insurance,patient->>'insurance','');
  -- Legacy UI saved empty insurance even on already linked NFs. Preserve established
  -- financial history on unrelated edits without filling explicit empty clinical snapshots.
  if t.id is not null and previous->>'insurance' is not distinct from a->>'insurance'
    and exists(select 1 from public.billing_records b join public.invoice_billing_records ib on ib.billing_record_id=b.id where b.attendance_id=t.id)
  then historical_insurance:=t.insurance;end if;

  if t.id is null then
   insert into public.attendances(id,appointment_id,origin,patient_id,doctor_id,date,procedure,insurance,billing_method,status) values(a->>'id',a->>'id','AGENDA',nullif(a->>'patientId',''),owner,(a->>'date')::date,coalesce(a->>'procedure','Procedimento'),historical_insurance,public.appointment_billing_method(a),a->>'status');
  elsif (t.patient_id,t.date,t.procedure,t.insurance,t.billing_method,t.status) is distinct from (nullif(a->>'patientId',''),(a->>'date')::date,coalesce(a->>'procedure','Procedimento'),historical_insurance,public.appointment_billing_method(a,t.billing_method),a->>'status') then
   update public.attendances set patient_id=nullif(a->>'patientId',''),date=(a->>'date')::date,procedure=coalesce(a->>'procedure','Procedimento'),insurance=historical_insurance,billing_method=public.appointment_billing_method(a,t.billing_method),status=a->>'status' where id=t.id;
  end if;
 end loop;
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.unlock_billing_month(p_actor bigint, p_entity uuid, p_month text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 first_day date;
 latest public.billing_monthly_closing_events%rowtype;
 event_id uuid;
begin
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then
   raise exception 'Somente o Gerente Geral pode desbloquear';
 end if;
 if p_month is null or p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
   raise exception 'Competência inválida';
 end if;
 if length(trim(coalesce(p_reason,''))) not between 5 and 2000 then
   raise exception 'Justifique o desbloqueio (mínimo 5 caracteres)';
 end if;
 first_day:=(p_month||'-01')::date;
 perform pg_advisory_xact_lock(hashtext(p_entity::text||p_month)::bigint);
 select * into latest from public.billing_monthly_closing_events
   where billing_entity_id=p_entity and competence_month=first_day
   order by event_number desc limit 1;
 if latest.id is not null then
   if latest.event_type<>'CLOSED' then raise exception 'Competência já desbloqueada';end if;
 elsif not exists(select 1 from public.billing_monthly_closings
   where billing_entity_id=p_entity and competence_month=first_day) then
   raise exception 'A competência ainda não foi fechada';
 end if;
 insert into public.billing_monthly_closing_events(
   billing_entity_id,competence_month,event_type,notes,actor_id)
 values(p_entity,first_day,'UNLOCKED',trim(p_reason),p_actor)
 returning id into event_id;
 return event_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_pending_invoice_request(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare request_row public.invoice_requests%rowtype;
        actor_role text; kind text; name text; cpf text; address_value text; note_value text;
        patient jsonb; expected timestamptz; linked public.billing_records%rowtype;
begin
 perform pg_advisory_xact_lock(194701,1);
 perform pg_advisory_xact_lock(194701,2);
 select role into actor_role from public.users where id=p_actor;
 if actor_role not in ('general_manager','secretary') then raise exception 'Sem permissão para corrigir solicitações fiscais';end if;
 if nullif(p_data->>'id','') is null or nullif(p_data->>'updated_at','') is null then raise exception 'Solicitação e versão obrigatórias';end if;
 select * into request_row from public.invoice_requests where id=(p_data->>'id')::uuid for update;
 if request_row.id is null then raise exception 'Solicitação fiscal não encontrada';end if;
 if request_row.status<>'PENDING' or request_row.invoice_id is not null then
  raise exception 'A NF já foi emitida ou a solicitação não está pendente. Faça a correção fiscal na NF';
 end if;
 expected:=(p_data->>'updated_at')::timestamptz;
 if request_row.updated_at is distinct from expected then raise exception 'Solicitação alterada por outra pessoa. Atualize antes de editar';end if;
 select * into linked from public.billing_records where id=request_row.billing_record_id for update;
 if linked.id is null or linked.payment_status<>'PAGO' or linked.billing_method<>'PARTICULAR'
    or linked.attendance_id<>request_row.attendance_id
    or linked.billing_entity_id<>request_row.billing_entity_id
    or linked.received_amount is distinct from request_row.received_amount_snapshot
    or linked.paid_at is distinct from request_row.paid_at_snapshot then
   raise exception 'Pagamento e solicitação fiscal precisam ser regularizados antes da alteração';
 end if;
 if actor_role='secretary' and not exists (
  select 1 from public.app_state s
  cross join lateral jsonb_array_elements(coalesce(s.payload->'appointments','[]'::jsonb)) appointment
  join public.agenda_access access on access.user_id=p_actor
   and access.professional_id in (appointment->>'doctorId',appointment->>'anesthetistId')
  where s.id=1 and appointment->>'id'=linked.appointment_id
 ) then raise exception 'Acesso negado à agenda desta solicitação';end if;
 kind:=p_data->>'taker_kind';
 if kind not in ('PATIENT','OTHER') then raise exception 'Selecione Próprio paciente ou Outra pessoa';end if;
 cpf:=regexp_replace(coalesce(p_data->>'taker_tax_id',''),'[^0-9]','','g');
 if not public.valid_cpf(cpf) then raise exception 'Informe um CPF válido';end if;
 name:=trim(coalesce(p_data->>'taker_name',''));
 if kind='PATIENT' then
  select p into patient from public.app_state s
   cross join lateral jsonb_array_elements(coalesce(s.payload->'patients','[]'::jsonb)) p
   where s.id=1 and p->>'id'=request_row.patient_id;
  if patient is null or nullif(trim(patient->>'name'),'') is null then raise exception 'Paciente não encontrado';end if;
  if nullif(regexp_replace(coalesce(patient->>'cpf',''),'[^0-9]','','g'),'') is not null
   and regexp_replace(patient->>'cpf','[^0-9]','','g')<>cpf then
   raise exception 'CPF diferente do cadastro do paciente. Corrija o cadastro ou selecione Outra pessoa';
  end if;
  name:=trim(patient->>'name');
 end if;
 if name='' or length(name)>200 then raise exception 'Informe o nome do tomador (até 200 caracteres)';end if;
 address_value:=nullif(trim(coalesce(p_data->>'taker_address','')),'');
 note_value:=nullif(trim(coalesce(p_data->>'notes','')),'');
 if length(coalesce(address_value,''))>1000 or length(coalesce(note_value,''))>2000 then
  raise exception 'Endereço ou observação excede o limite';
 end if;
 if kind=request_row.taker_kind and name=request_row.taker_name and cpf=request_row.taker_tax_id
    and address_value is not distinct from request_row.taker_address
    and note_value is not distinct from request_row.notes then return request_row.id;end if;
 perform public.financial_operation(p_actor,'edit_invoice_request',request_row.id::text);
 update public.invoice_requests
  set taker_kind=kind,taker_name=name,taker_tax_id=cpf,taker_address=address_value,notes=note_value
  where id=request_row.id;
 perform set_config('rn.operation','',true);
 perform set_config('rn.actor','',true);
 return request_row.id;
end;$function$;

CREATE OR REPLACE FUNCTION public.valid_cpf(v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text:=regexp_replace(coalesce(v,''),'[^0-9]','','g');n int;k int;t int;
begin
 if length(s)<>11 or s=repeat(substr(s,1,1),11) then return false;end if;
 for n in 10..11 loop t:=0;for k in 1..n-1 loop t:=t+substr(s,k,1)::int*(n+1-k);end loop;t:=(t*10)%11;if t=10 then t:=0;end if;if t<>substr(s,n,1)::int then return false;end if;end loop;return true;
end;$function$;

CREATE OR REPLACE FUNCTION public.valid_medical_specialty(value text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select value=any(array['Acupuntura','Alergia e Imunologia','Anestesiologia','Angiologia','Cardiologia','Cirurgia Cardiovascular','Cirurgia da Mão','Cirurgia de Cabeça e Pescoço','Cirurgia do Aparelho Digestivo','Cirurgia Geral','Cirurgia Oncológica','Cirurgia Pediátrica','Cirurgia Plástica','Cirurgia Torácica','Cirurgia Vascular','Clínica Médica','Coloproctologia','Dermatologia','Endocrinologia e Metabologia','Endoscopia','Gastroenterologia','Genética Médica','Geriatria','Ginecologia e Obstetrícia','Hematologia e Hemoterapia','Homeopatia','Infectologia','Mastologia','Medicina de Emergência','Medicina de Família e Comunidade','Medicina do Trabalho','Medicina do Tráfego','Medicina Esportiva','Medicina Física e Reabilitação','Medicina Intensiva','Medicina Legal e Perícia Médica','Medicina Nuclear','Medicina Preventiva e Social','Nefrologia','Neurocirurgia','Neurologia','Nutrologia','Oftalmologia','Oncologia Clínica','Ortopedia e Traumatologia','Otorrinolaringologia','Patologia','Patologia Clínica/Medicina Laboratorial','Pediatria','Pneumologia','Psiquiatria','Radiologia e Diagnóstico por Imagem','Radioterapia','Reumatologia','Urologia']) $function$;

CREATE OR REPLACE FUNCTION public.validate_user_doctor_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.role<>'doctor' and new.doctor_id is not null then raise exception 'Somente usuário médico pode ter identidade profissional'; end if;
 if new.role='doctor' and new.doctor_id is null then
  if tg_op='INSERT' then raise exception 'Selecione o médico deste acesso'; end if;
  if old.role is distinct from new.role or old.doctor_id is distinct from new.doctor_id then raise exception 'Selecione o médico deste acesso'; end if;
 end if;
 return new;
end;$function$;

CREATE OR REPLACE FUNCTION public.write_payment_parts(p_record uuid, p_invoice uuid, p_parts jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare part jsonb;
begin
 if jsonb_typeof(p_parts) is distinct from 'array' or jsonb_array_length(p_parts)=0 then raise exception 'Informe as formas de pagamento';end if;
 delete from public.payment_parts where (p_record is not null and billing_record_id=p_record) or (p_invoice is not null and invoice_id=p_invoice);
 for part in select value from jsonb_array_elements(p_parts) loop
  if jsonb_typeof(part->'amount') is distinct from 'number' then raise exception 'Valor da forma de pagamento obrigatório';end if;
  insert into public.payment_parts(billing_record_id,invoice_id,method,amount,installments,notes)
  values(p_record,p_invoice,part->>'method',round((part->>'amount')::numeric,2),nullif(part->>'installments','')::integer,nullif(trim(part->>'notes'),''));
 end loop;
end;$function$;

