-- [6] ÍNDICES NÃO CRIADOS AUTOMATICAMENTE PELAS CONSTRAINTS
CREATE INDEX agenda_requests_requester_idx ON public.agenda_requests USING btree (requested_by);
CREATE INDEX idx_agenda_requests_professional_status ON public.agenda_requests USING btree (professional_id, status);
CREATE INDEX attendance_doctor_date ON public.attendances USING btree (doctor_id, date);
CREATE INDEX attendances_cancelled_by ON public.attendances USING btree (cancelled_by);
CREATE INDEX audit_logs_professional_idx ON public.audit_logs USING btree (professional_id);
CREATE INDEX idx_audit_logs_created ON public.audit_logs USING btree (created_at DESC);
CREATE INDEX billing_denial_appeals_case ON public.billing_denial_appeals USING btree (denial_id, filed_on, id);
